(window.GIM_TS=window.GIM_TS||{})["Chullin.6"]={"from":144,"a":[["\u0003אין בהן אלא מצות פרוש בלבד,\u0004 כלומר, אינם אסורים מן התורה, אלא מצוה מדברי סופרים לפרוש מאכילתם. הרי שלדעתו אין השחיטה עושה ניפול באבר המדולדל, לאוסרו משום אבר מן החי. ובענין זה מסופר,","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא, ויתיב וקאמר\u0004 \u0005[ויושב היה ואומר],\u0006 \u0003אמר רב יהודה אמר רב: אכלו לזה,\u0004 לאבר המדולדל — הרי הוא \u0003לוקה\u0004 משום איסור אבר מן החי. \u0003אמר ליה ההוא מרבנן\u0004 \u0005[אמר לו אחד\u0006 מן \u0005החכמים]:\u0006 \u0003לא תציתו ליה\u0004 \u0005[אל תקשיבו לו],\u0006 למה שאמר בשם רב, שהרי \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יצחק בר שמואל בר מרתא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אכלו לזה\u0004 — \u0003אינו לוקה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא: אנן אמאן\u0004 \u0005[אנחנו על מי]\u0006 \u0003נסמוך?\u0004 שהרי יש לנו שתי שמועות סותרות בשם רב! \u0003אהדרינהו\u0004 \u0005[החזיר]\u0006 \u0003רב יוסף לאפיה\u0004 \u0005[את פניו]\u0006 בהקפדה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי קושיא\u0004 \u0005[מה הקושיה]?\u0006 \u0003כי אמרי אנא\u0004 \u0005[כאשר אמרתי אני]\u0006 בשם רב שלוקה משום אבר מן החי — אמר רב דבר זה \u0003ב\u0004מקרה של \u0003מיתה,\u0004 שהיא \u0003עושה ניפול,\u0004 שהאבר נחשב כאילו נפל מן הבהמה בחייה. \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר איהו\u0004 \u0005[הוא]\u0006 רב יצחק בר שמואל בר מרתא בשם רב שאינו לוקה — הרי \u0003זה\u0004 \u0003בשחיטה,\u0004 ש\u0003אינה עושה ניפול,\u0004 והאבר נחשב כמחובר לגוף הבהמה בשעת השחיטה, והותר בשחיטתה, ולכן אינו לוקה על אכילתו.","\u0003אמר רבא: מנא הא מלתא דאמור רבנן\u0004 \u0005[מנין דבר זה שאמרו חכמים]:\u0006 \u0003מיתה עושה ניפול, שחיטה אינה עושה ניפול? דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשת השרצים הטמאים: \u0003\"וכל אשר יפול עליו מהם במותם יטמא\"\u0004 (ויקרא יא, לב), ויש לשאול: המילה \"במותם\" \u0003למעוטי מאי\u0004 \u0005[למעט את מה]\u0006 היא באה? \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 \u0003בחייהם,\u0004 לומר שבחייהם אינם מטמאים — הרי דבר זה \u0003מ\"נבלתם\" נפקא\u0004 \u0005[יוצא],\u0006 שנאמר: \"כל אשר יפול מנבלתם עליו יטמא\" (שם לז), ונבילה משמעה יצור מת! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 דין אחר, ביחס לאברים המדולדלים שבהם, כאילו נאמר: כל אשר יפול מהם — במותם, לומר: דווקא \u0003מיתה\u0004 \u0003עושה\u0004 להם \u0003ניפול,\u0004 להחשיבם כאילו נפלו, ומטמאים כאבר מן החי, \u0003ואין שחיטה עושה ניפול,\u0004 אלא הריהם נחשבים כחלק מגוף הבהמה בשעת השחיטה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא:\u0004 וכיצד ניתן לדייק מכאן ששחיטה אינה עושה ניפול? \u0003והא קרא\u0004 \u0005[והרי המקרא]\u0006 \u0003בשרצים כתיב\u0004 \u0005[נאמר],\u0006 ואין בהם שחיטה כלל! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם אינו ענין,\u0004 כלומר, הואיל ומקרא זה אינו נצרך \u0003לשרצים, דלאו\u0004 \u0005[שאין]\u0006 \u0003בני שחיטה נינהו\u0004 \u0005[הם]\u0006 — \u0003תנהו ענין לבהמה.\u0004","ומקשים: \u0003ואכתי מבעי ליה\u0004 \u0005[ועדיין צריך אותו]\u0006 את מה שנאמר \"במותם יטמא\" לומר: \u0003כעין מיתה,\u0004 שדווקא כשהשרצים \u0003לחין\u0004 כבשעת המיתה הם \u0003מטמאים,\u0004 כשהם \u0003יבשים\u0004 — \u0003אין מטמאים!\u0004 ומשיבים: \u0003תרי\u0004 \u0005[שתי\u0006 פעמים\u0005]\u0006 \u0003\"במותם\" כתיבי\u0004 \u0005[נאמרו],\u0006 ודין זה נלמד ממה שנאמר בפסוק הקודם (שם לא): \"כל הנוגע בהם במותם יטמא\".","ושבים למחלוקת במשנתנו, בענין עובר שהוציא את ידו, ושחט את אמו, שלדעת ר' מאיר אין היד נטהרת בשחיטת האם, והיא מטמאת כאבר מן החי, ולדעת חכמים טיהרה אותה שחיטת האם. \u0003אמר רב חסדא: מחלוקת\u0004 זו היא \u0003באבר\u0004 של \u0003עובר חי, אבל באבר\u0004 של \u0003עובר מת\u0004 — \u0003דברי הכל: שחיטה עושה ניפול,\u0004 ולא נטהרה היד בשחיטת האם, אלא מטמאת משום נבילה. \u0003ורבה אמר: כמחלוקת בזה כך מחלוקת בזה,\u0004 וגם בעובר שהוציא ידו ומת, שלדעת חכמים שחיטת אמו מטהרת את היד מטומאת נבילה.","שנינו במשנה שטריפה יש במינה שחיטה, ולכן שחיטתה מטהרתה מטומאת נבילה. ובהמשך לכך נאמר: עובר \u0003בן שמנה חי\u0004 אין שחיטתו מטהרתו, מפני שאין במינו שחיטה. ומתקשים, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003בן שמנה חי יוכיח, שאף על פי שיש במינו שחיטה\u0004 — \u0003אין שחיטתו מטהרתו,\u0004 הרי שבברייתא זו מחשיבים בן שמונה כמי יש במינו שחיטה!","\u0003אמר רב כהנא:\u0004 מה שנאמר באותה ברייתא ש\u0003יש במינו שחיטה,\u0004 כוונתו — \u0003אגב אמו,\u0004 שכאשר שוחטים את אמו גם הוא נעשה מותר על ידה. \u0003ותנא דידן\u0004 \u0005[והתנא שלנו],\u0006 \u0003מינא דאמיה לא פריך\u0004 \u0005[מהמין של אמו אינו מקשה],\u0006 שמה שהעובר ניתר בשחיטת אמו אינו מחשיב אותו כמי שיש במינו שחיטה, מפני שהוא נחשב אז כחלק מאמו.","ושואלים: \u0003ולהאי תנא דפריך\u0004 \u0005[ולאותו תנא שמקשה\u0006 קושיה זו\u0005],\u0006 \u0003טרפה\u0004 ש\u0003שחיטתה מטהרתה מנא ליה\u0004 \u0005[מנין לו]?\u0006 והרי לשיטתו, מה שיש במינה שחיטה אינו מועיל לטהר! ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שאמר \u0003רב יהודה אמר רב,\u0004 ש\u0003אמר רב יהודה אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003במתניתא תנא\u0004 \u0005[בברייתא היא שנויה]:\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וכי ימות מן הבהמה\u0004 וכו' הנוגע בנבלתה יטמא\" (ויקרא יא, לט), והלשון \"מן\" באה ללמד: \u0003מקצת בהמה מטמאה\u0004 בטומאת נבילה, \u0003ומקצת בהמה אינה מטמאה, ואיזו זו\u0004 שאינה מטמאה? \u0003זו טרפה ששחטה.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב הושעיא: הושיט את ידו למעי בהמה, ושחט\u0004 בתוכה \u0003בן תשעה חי, מהו?\u0004 האם שחיטתו במעי אמו מתירה אותו? ובזה \u0003תבעי\u0004 \u0005[תישאל\u0006 השאלה\u0005]\u0006 \u0003ל\u0004דעת \u0003ר' מאיר, ותבעי לרבנן\u0004 \u0005[ותישאל ל\u0006דעת \u0005חכמים].\u0006","ומפרטים: \u0003תבעי\u0004 \u0005[תישאל]\u0006 \u0005לר' מאיר:\u0006 \u0003עד כאן לא קאמר\u0004 \u0005[לא שמענו שאמר]\u0006 \u0003ר' מאיר\u0004 במשנה שבהמשך עמוד זה, ש\u0003בן פקועה,\u0004 בן תשעה שהוציאוהו חי ממעי בהמה שנשחטה, \u0003טעון שחיטה\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה אמורים]\u0006 \u0003היכא\u0004 \u0005[היכן]\u0006 שכבר \u0003יצא לאויר העולם, אבל\u0004 בעודו \u0003במעי אמו\u0004 — \u0003לא שריא ליה\u0004 \u0005[אין מתירה אותו]\u0006 \u0003שחיטה\u0004 שלו.","\u0003או דילמא\u0004 \u0005[שמא],\u0006 \u0003אפילו לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 החולקים על ר' מאיר, וסבורים ששחיטת אמו כשהוא במעיה מתירה אותו, יש לומר ש\u0003ארבעה סימנין אכשר ביה רחמנא\u0004 \u0005[הכשירה בו התורה],\u0006 שהוא ניתר בין בשחיטת שני סימנים (קנה וושט) של אמו, בין בשחיטת סימנים של עצמו?","\u0003אמר רב חנניא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר, ממה ששנינו במשנתנו: \u0003הרי שנולדה טרפה מן הבטן,\u0004 שלא היתה לה שעת הכושר — לא תטהרנה שחיטתה. \u0003ואי איתא\u0004 \u0005[ואם אכן]\u0006 ניתן לשחוט בן תשעה כשהוא במעי אמו, \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 ש\u0003היתה לה\u0004 לזו שנולדה כשהיא טריפה \u0003שעת הכושר, דאי בעי עייל ידיה ושחטה\u0004 \u0005[שאם היה רוצה היה מכניס ידו ושוחט אותה]\u0006 במעי אמה קודם שנטרפה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא, תני\u0004 \u0005[שנה]:\u0006 הרי \u0003שנוצרה טרפה מן הבטן,\u0004 שמתחילת יצירתה טריפה היא, ובמקרה זה לא ניתן היה לשוחטה. \u0003ומשכחת לה\u0004 \u0005[ומוצא אתה אותה]\u0006 \u0003בבעלת חמש רגלים,\u0004 שהיא טריפה מעיקרה, ואין לה היתר כלל.","\u0003השוחט את הבהמה, ומצא בה\u0004 עובר \u0003בן שמנה\u0004 חודשים (שלא נגמר הריונו) \u0003חי או מת, או\u0004 אפילו \u0003בן תשעה\u0004 שנגמרו חודשי הריונו, אבל הוא \u0003מת\u0004 — הותר בשחיטת הבהמה, ואינו צריך לשוחטו, אלא \u0003קורעו, ומוציא את דמו,\u0004 שהדם אסור כחלק מדם אמו, ואז הוא מותר באכילה.","\u0003מצא\u0004 בה \u0003בן תשעה חי\u0004 — הרי זה \u0003טעון שחיטה, וחייב\u0004 על שחיטתו \u0003באותו ואת בנו,\u0004 אם שחט אותו ביום ששחט את אמו, אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 גם בן תשעה חי שנמצא במעי בהמה שחוטה — \u0003שחיטת אמו מטהרתו,\u0004 ואינו טעון שחיטה."],["\u0003ר' שמעון שזורי אומר:\u0004 בן תשעה חי שנמצא במעי בהמה שנשחטה \u0003אפילו\u0004 המתינו לו עד שגדל, והוא \u0003בן חמש שנים\u0004 \u0003וחורש בשדה\u0004 — בכל זאת \u0003שחיטת אמו מטהרתו,\u0004 ואינו טעון שחיטה. \u0003קרעה\u0004 את הבהמה \u0003ומצא בה בן תשעה חי\u0004 — \u0003טעון שחיטה\u0004 לכל הדעות, \u0003לפי שלא נשחטה אמו.\u0004","בענין עובר בן תשעה חי, שנחלקו ר' מאיר וחכמים במשנתנו האם הוא טעון שחיטה, \u0003אמר ר' אלעזר אמר ר' אושעיא: לא הילכו\u0004 (דנו) \u0003בו\u0004 חכמים בבן תשעה חי, \u0003אלא על עסקי שחיטה בלבד.\u0004 ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט את מה]?\u0006 אם תאמר \u0003למעוטי\u0004 \u0005[למעט]\u0006 איסור \u0003חלבו\u0004 (שומן אסור שלו) \u0003ו\u0004איסור \u0003גידו\u0004 גיד הנשה שלו, יש לשאול:","\u0003חלבו דמאי\u0004 \u0005[של מה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]:\u0006 \u0003חלבו\u0004 של ה\u0003שליל,\u0004 העובר — הלוא \u0003מפלג פליגי\u0004 \u0005[נחלקו\u0006 בדבר\u0005]!\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 איסור \u0003גיד הנשה נוהג בשליל\u0004 (עובר), \u0003וחלבו אסור,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 גיד הנשה \u0003אינו נוהג בשליל, וחלבו מותר. ואמר ר' אלעזר אמר ר' אושעיא: מחלוקת\u0004 זו היא \u0003בבן תשעה חי, והלך ר' מאיר לשיטתו,\u0004 שעובר כזה נחשב כבהמה גמורה, שחלבה וגידה אסורים, \u0003ור' יהודה לשיטתו,\u0004 שהיא דעת חכמים במשנתנו, שאינו נחשב בהמה לעצמה!","\u0003אלא\u0004 תאמר שהכוונה היא ל\u0003חלבו\u0004 של \u0003גיד\u0004 הנשה של השליל, שלמרות שר' מאיר אוסר את חלב הכליות והקרב של העובר, גם הוא מודה שחלב הגיד שלו מותר; והרי גם בזה \u0003מפלג פליגי\u0004 \u0005[חלוקים הם]!\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003גיד הנשה\u0004 — \u0003מחטט אחריו\u0004 ומוציא אותו \u0003בכל מקום שהוא\u0004 בירך, \u0003וחותך שמנו מעיקרו,\u0004 אפילו את המובלע בעומק הבשר, \u0003דברי ר' מאיר. רבי יהודה אומר: גוממו\u0004 (חותך אותו) את הגיד והשומן \u0003עם השופי,\u0004 בשווה לבשר הירך, ואינו צריך לחטט אחריו. ונמצא שנחלקו לא רק על עסקי שחיטה של בן תשעה חי, אלא גם על איסורים אחרים, שלא כדברי ר' אלעזר בשם ר' אושעיא!","\u0003אלא אי אתמר\u0004 — \u0003הכי אתמר\u0004 \u0005[אם נאמר — כך נאמר],\u0006 \u0003אמר ר' אלעזר אמר ר' אושעיא: לא הילכו בו\u0004 בבן תשעה חי \u0003אלא על עסקי אכילה בלבד,\u0004 כגון שחיטה, וגיד הנשה וחלב, ודבר זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 אם \u0003רובעו,\u0004 או \u0003חורש בו\u0004 עם מין אחר, כגון חמור, שיש בו איסור \"לא תחרוש בשור ובחמור יחדיו\" (דברים כב, י), לומר שדינו לענין זה כבהמה גמורה.","ועוד נחלקו אמוראים בענין זה. \u0003אמר ר' שמעון בן לקיש: לדברי\u0004 ר' יהודה \u0003המתיר בחלבו\u0004 של בן תשעה חי הנמצא במעי בהמה שחוטה — \u0003מתיר\u0004 גם \u0003בדמו, לדברי\u0004 ר' מאיר \u0003האוסר בחלבו\u0004 — \u0003אוסר\u0004 גם \u0003בדמו. ורבי יוחנן אמר: אף לדברי המתיר בחלבו\u0004 — \u0003אוסר בדמו.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבי יוחנן לר' שמעון בן לקיש\u0004 ממה ששנינו במשנתנו: השוחט את הבהמה ומצא בה בן שמונה חי או מת, או בן תשעה מת — \u0003קורעו,\u0004 שאינו טעון שחיטה, \u0003ומוציא את דמו.\u0004 משמע שגם במקרה שהעובר אינו טעון שחיטה, וחלבו מותר — דמו אסור! \u0003אמר ר' זירא:\u0004 מה שאמר ר' שמעון בן לקיש, שלדעה זו דמו מותר, כוונתו \u0003לומר שאין ענוש כרת\u0004 על אכילתו, כדין האוכל מדם שהנפש יוצאת בו. אבל גם לדעתו הריהו אסור באכילה, כדם איבריה של האם, ולכן צריך להוציאו.","ושואלים: והרי \u0003למאן קאמרי\u0004 \u0005[לדעת מי הם אומרים]\u0006 דבר זה? \u0003ל\u0004דעת \u0003רבי יהודה,\u0004 שהוא המתיר את חלבו; והרי גם לשיטתו, \u0003לא יהא\u0004 דינו של דם הנפש של העובר \u0003אלא\u0004 כ\u0003דם התמצית,\u0004 הדם שמתמצה מן הבהמה לאחר שיצא ממנה דם הנפש, והרי גם עליו מחייב ר' יהודה כרת. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003דם התמצית\u0004 אינו בכרת אלא \u0003באזהרה\u0004 בלא תעשה בלבד, שחייב עליו מלקות, \u0003ר' יהודה אומר: בהכרת!\u0004","\u0003תרגמא\u0004 \u0005[תרגם,\u0006 הסביר \u0005אותה]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב סלא חסידא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא: אית ליה\u0004 \u0005[יש לו]\u0006 \u0003לר' יהודה\u0004 דרשה זו של \u0003\"דם\" ו\"כל דם\",\u0004 שהוא למד את דינו של דם התמצית מריבוי הכתוב \"כל דם\" שנאמר בעונש הכרת (\"...אשר יאכל כל דם וכו' והכרתי אותה\". ויקרא יז, י), שמ\"דם\" למדנו לדם הנפש, ומ\"כל דם\" — דם התמצית. ולכן, \u0003כל היכא דמיחייב\u0004 \u0005[כל מקום שהוא חייב]\u0006 כרת על \u0003דם הנפש\u0004 — \u0003מיחייב\u0004 \u0005[חייב]\u0006 גם על \u0003דם התמצית, וכל היכא דלא מחייב\u0004 \u0005[וכל מקום שאינו מחוייב]\u0006 על \u0003דם הנפש\u0004 — \u0003לא מחייב\u0004 \u0005[אינו מחוייב]\u0006 על \u0003דם התמצית.\u0004 ולדעת ר' יהודה, עיקר דמו של עובר זה אינו נחשב דם הנפש, לחייב עליו כרת, מפני שהוא חלק מאמו, וממילא גם אין חייבים כרת על דם התמצית שלו, אבל איסור יש בו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 \u0003מהו לפדות\u0004 פטר חמור \u0003ב\u0004שה שהוא \u0003בן פקועה,\u0004 ששחטו כבשה ופקעו את רחמה והוציאו משם שה שנגמרו חדשי הריונו, האם ניתן לקיים בו את המצוה \"ופטר חמור תפדה בשה\" (שמות יג, יג)? ומסבירים: \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' מאיר לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 ש\u0003כיון\u0004 ש\u0003אמר\u0004 שהוא \u0003טעון שחיטה\u0004 אם כן \u0003שה מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 ובוודאי אפשר לפדות בו.","\u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים],\u0006 \u0003דאמרי\u0004 \u0005[שהם אומרים]:\u0006 \u0003שחיטת אמו מטהרתו, מאי\u0004 \u0005[מה]\u0006 דינו? האם \u0003כיון דאמרי\u0004 \u0005[שהם אומרים]\u0006 \u0003שחיטת אמו מטהרתו\u0004 — \u0003כבשרא בדיקולא\u0004 \u0005[כבשר\u0006 של בהמה שחוטה שמונח \u0005בתוך הסל]\u0006 \u0003הוא\u0004 נחשב, אף על פי שהוא חי, ואין פודים בשחוטה (בכורות יב,א). \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון דרהיט ואזיל, ורהיט ואתי\u0004 \u0005[שהוא רץ והולך, ורץ ובא],\u0006 שהרי בפועל הוא חי — \u0003\"שה\" קרינא ביה\u0004 \u0005[קוראים אנו אותו]?\u0006","\u0003מר זוטרא אמר: אין פודין, ורב אשי אמר: פודין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי למר זוטרא: מאי\u0004 \u0005[מה]\u0006 \u0003דעתך?\u0004 מדוע אתה סבור שאין פודים בו — מפני \u0003דגמרת\u0004 \u0005[שאתה לומד]\u0006 בגזירה שווה \u0003\"שה\" \"שה\" מפסחים,\u0004 מקרבן הפסח, שגם בו נאמרה לשון \"שה\" (שם יב, יב), שכשם שבן פקועה פסול לקרבן פסח, שהרי הוא יוצא דופן שפסול לקרבן — כך הוא פסול לפדיון פטר חמור.","ואולם \u0003אי\u0004 \u0005[אם\u0006 כן\u0005]\u0006 תאמר גם: \u0003מה להלן\u0004 בענין פסחים — צריך להיות השה \u0003זכר, תמים, ובן שנה, אף כאן\u0004 בפדיון פטר חמור — צריך שיהיה \u0003זכר, תמים, ובן שנה!\u0004 והרי שנינו במפורש שפודים גם בנקבה, וכן בבעל מום, ובגדול שאינו בן שנה (בכורות ט,א)! השיב לו: במה שחזר הכתוב באותו פסוק על הציווי \u0003\"תפדה\" \"תפדה\"\u0004 (\"וכל פטר חמור תפדה, בשה ואם לא תפדה וערפתו\", שמות יג, יג) הרי זה \u0003ריבה,\u0004 שניתן לפדות גם בכל אלה.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"תפדה\" \"תפדה\" ריבה, אפילו כל מילי נמי\u0004 \u0005[כל דבר גם כן]\u0006 יכול לפדות בו, ואפילו בבן פקועה, שהוא יוצא דופן! ומתרצים: \u0003אם כן,\u0004 גזירה שווה \u0003\"שה\" \"שה\"\u0004 מפסחים, \u0003מאי אהני לך\u0004 \u0005[מה הועיל לך]?\u0006 אלא היא באה על כל פנים למעט יוצא דופן.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 עובר הנמצא במעי אמו שנשחטה, ולדעת חכמים הותר בשחיטתה באכילה, ויש לו דין אוכל לקבל טומאה, \u0003מהו למנות בו\u0004 לענין טומאה \u0003ראשון ושני?\u0004 אם נטמאה אמו לאחר שחיטה ממגע של אב הטומאה, ודינה כראשון לטומאה, האם גם העובר נחשב ראשון לטומאה, כחלק מאמו, או האם הוא נחשב כנוגע בבשר אמו, ודינו כשני לטומאה?","\u0003ר' יוחנן אמר: מונין בו ראשון ושני. רבי שמעון בן לקיש אומר: אין מונין בו ראשון ושני,\u0004 שכן \u0003נעשה\u0004 דינו \u0003כ\u0004דין \u0003אגוז המתקשקש בקליפתו,\u0004 שטומאה שנגעה בקליפה, שהיא שומר של הפרי, נחשבת כנוגעת באגוז עצמו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' שמעון בן לקיש לרבי יוחנן\u0004 ממה ששנינו במשנה (לעיל עב,ב): הוציא עובר ידו ממעי אמו, ונשחטה האם — דין היד כנבילה, ולא הותרה בשחיטת האם, ולכן \u0003הבשר\u0004 של העובר טמא ב\u0003מגע נבלה,\u0004 כדין בשר שנגע בנבילה, אלו \u0003דברי ר' מאיר,\u0004","\u0003וחכמים אומרים:\u0004 דין היד אינו כדין נבילה, אלא כטריפה, ולכן דין בשר העובר שנוגע בה כדין \u0003מגע\u0004 ב\u0003טרפה שחוטה.\u0004","ומעתה, \u0003בשלמא לדידי\u0004 \u0005[נניח לשיטתי],\u0006 \u0003דאמינא חד גופא\u0004 \u0005[שאני אומר\u0006 שהאם והעובר \u0005גוף אחד]\u0006 \u0003הוא\u0004 — \u0003היינו דאיתכשר בדמא דאמיה\u0004 \u0005[זהו שהוכשר\u0006 בשר העובר \u0005לקבל טומאה\u0006 מן היד \u0005בדם של אמו],\u0006 שכשם שדם השחיטה מכשיר את בשר האם לקבלת טומאה — כך הוא מכשיר את העובר שהוא חלק מבשרה. \u0003אלא לדידך\u0004 \u0005[לשיטתך],\u0006 שהעובר נחשב כגוף לעצמו, \u0003במאי איתכשר\u0004 \u0005[במה הוא הוכשר]\u0006 לקבל טומאה מן היד?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בשחיטה\u0004 של אמו הוכשר, \u0003וכ\u0004דעת \u0003ר' שמעון\u0004 ששחיטה מכשירה את בשר האם לקבל טומאה גם ללא דם. שכיון שגם העובר ניתר בשחיטה זו — הריהי מכשירה אותו לקבלת טומאה, למרות שאינו חלק מגופה של אמו.","מן הצד השני \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבי יוחנן לר' שמעון בן לקיש\u0004 ממה ששנינו: בן פקועה ש\u0003עבר בנהר\u0004 ונרטב במימי הנהר — \u0003הוכשר\u0004 לקבל טומאה ממי הנהר, וכיון ש\u0003הלך\u0004 משם \u0003לבית הקברות\u0004 — \u0003נטמא.\u0004","ומעתה, \u0003בשלמא לדידי דאמינא תרי גופי נינהו\u0004 \u0005[נניח לשיטתי שאני אומר\u0006 ש\u0005שני גופים הם],\u0006 האם והעובר שבמעיה — \u0003משום הכי\u0004 \u0005[כך],\u0006 אם \u0003הוכשר\u0004 במי הנהר — \u0003אין\u0004 \u0005[כן]\u0006 נטמא בבית הקברות, \u0003לא הוכשר\u0004 — \u0003לא. אלא לדידך\u0004 \u0005[לשיטתך],\u0006 \u0003דאמרת חד גופא\u0004 \u0005[שאתה אומר\u0006 שהעובר \u0005גוף אחד]\u0006 \u0003הוא\u0004 עם אמו, מדוע צריך שיעבור בנהר? \u0003הא איתכשר בדמא דאמיה\u0004 \u0005[הרי הוא הוכשר כבר בדם\u0006 השחיטה \u0005של אמו]!\u0006"],["ענה לו ריש לקיש: מדובר כאן \u0003בשחיטה יבישתא\u0004 \u0005[יבשה],\u0006 שלא יצא בה דם, שגם האם שנשחטה לא הוכשרה לקבל טומאה. \u0003ו\u0004הוא ש\u0003לא כ\u0004דעת \u0003רבי שמעון\u0004 האומר שהשחיטה לבדה מכשירה.","ושואלים: \u0003מאן תנא\u0004 \u0005[מיהו התנא]\u0006 שכשיטתו שנו בברייתא: \u0003עבר\u0004 בן פקועה \u0003בנהר\u0004 — \u0003הוכשר, הלך לבית הקברות\u0004 — \u0003נטמא,\u0004 למרות שהוא חי? \u0003אמר רבי יוחנן:\u0004 שיטת \u0003רבי יוסי הגלילי היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי שמעון בן אלעזר אומר משום רבי יוסי הגלילי:\u0004 בן פקועה \u0003מטמא טומאת אוכלים,\u0004 כלומר מקבל טומאה כאוכל, \u0003וצריך הכשר\u0004 משקה כדי לקבל טומאה. \u0003וחכמים אומרים: אינו מטמא טומאת אוכלין, מפני שהוא חי, וכל שהוא חי\u0004 — \u0003אינו מטמא טומאת אוכלין,\u0004 למרות שהוא מותר באכילה.","ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003רבי יוחנן לטעמיה\u0004 \u0005[לשיטתו],\u0006 ש\u0003אמר רבי יוחנן: רבי יוסי הגלילי ובית שמאי אמרו דבר אחד\u0004 כלומר, הלכו בשיטה אחת, שכל שאינו טעון שחיטה להתירו — מיטמא טומאת אוכלים;","\u0003רבי יוסי הגלילי\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 בענין בן פקועה; \u0003בית שמאי\u0004 — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003דגים, מאימתי מקבלין טומאה\u0004 כאוכלים? \u0003בית שמאי אומרים: משיצודו,\u0004 שבכך הם עומדים לאכילה, שהרי אינם צריכים שחיטה להתירם. \u0003ובית הלל אומרים: משימותו. רבי עקיבא אומר: משעה שאין יכולין לחיות\u0004 עוד.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין ר' עקיבא ובית הלל? \u0003אמר רבי יוחנן: דג מקרטע\u0004 (מפרפר) \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שאינו יכול לחיות עוד, שלדעת ר' עקיבא מיטמא, ולדעת בית הלל אינו מיטמא עד שימות לגמרי.","ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חסדא:\u0004 אם \u0003נולדו בדגים סימני טרפה,\u0004 כגון נקב בבני המעים, שעושה טריפה בבהמה (לעיל מב,א), \u0003מהו?\u0004 האם הם מיטמאים בטומאת אוכלים, כאילו היו מתים, או האם דינם כחיים? ואומרים: \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]\u0006 \u0003טרפה\u0004 שאסרה התורה — \u0003חיה,\u0004 אינה עומדת למות כתוצאה מכך. \u0003ותיבעי למאן דאמר\u0004 \u0005[ותישאל ל\u0006דעת \u0005מי שאומר]\u0006 \u0003טרפה אינה חיה,\u0004 אלא עומדת למות מחמת אותה לקות שיש בה.","ומפרטים: \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל ל\u0006דעת \u0005מי שאומר]\u0006 \u0003טרפה חיה; בהמה הוא\u0004 שאינה עומדת למות כתוצאה מכך, מפני \u0003דנפישא\u0004 \u0005[שמרובה]\u0006 \u0003חיותה, אבל דגים דלא נפישא חיותייהו\u0004 \u0005[שאין חיותם מרובה]\u0006 — \u0003לא,\u0004 ואם יש בהם סימני טריפה, הריהם עומדים למות. \u0003או דילמא\u0004 \u0005[שמא],\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003טרפה אינה חיה, הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003בהמה,\u0004 ש\u0003יש במינה שחיטה,\u0004 וכיון שאינה ראויה לשחיטה — רואים אותה כמתה, \u0003אבל דגים\u0004 ש\u0003אין במינן שחיטה\u0004 — \u0003לא,\u0004 וגם אם יש בהם סימני טריפה — אין זה מחשיב אותם כמתים? שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד].\u0006","ושבים לדין עובר הנמצא במעי בהמה שנשחטה, שלדעת חכמים הסבורים שהותר בשחיטתה — אינו נחשב כבהמה לעצמו, ולכן חלבו מותר. ונשאלה השאלה: בהמה \u0003ש\u0004\u0003הטילה נפל,\u0004 מה דין חלבו? \u0003רבי יוחנן אמר: חלבו\u0004 נידון \u0003כחלב בהמה,\u0004 וחייב כרת על אכילתו. \u0003ורבי שמעון בן לקיש אמר:\u0004 אינו נחשב כבהמה, שחלבה אסור, ולכן דין \u0003חלבו כ\u0004דין \u0003חלב חיה,\u0004 שאין בה איסור חלב.","ומסבירים, \u0003רבי יוחנן אמר: חלבו כחלב בהמה,\u0004 משום שלדעתו \u0003אוירא גרים\u0004 \u0005[האויר גורם],\u0006 היציאה לאויר העולם היא הגורמת לעובר להיחשב בהמה בפני עצמה, וממילא לאסור את חלבו. \u0003רבי שמעון בן לקיש אמר:\u0004 דין \u0003חלבו כ\u0004דין \u0003חלב חיה,\u0004 כי לדעתו \u0003חדשים גרמי\u0004 \u0005[גורמים]\u0006 שייחשב כבהמה שיש בה איסור חלב, ונפל זה לא נגמרו חודשיו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בהסבר מחלוקת זו: \u0003כל היכא\u0004 \u0005[כל מקום]\u0006 ש\u0003לא כלו לו חדשיו\u0004 — \u0003לא כלום הוא,\u0004 ובוודאי אין חלבו אסור. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003הושיט\u0004 אדם \u0003ידו למעי בהמה, ותלש חלב של בן תשעה חי ואכל; רבי יוחנן אמר: חלבו כחלב בהמה,\u0004 משום שלדעתו \u0003חדשים\u0004 לבד \u0003גרמי\u0004 \u0005[גורמים]\u0006 להחשיבו כבהמה לעצמו. \u0003רבי שמעון בן לקיש אמר: חלבו\u0004 מותר \u0003כחלב חיה,\u0004 כי לדעתו גם \u0003חדשים ו\u0004גם \u0003אוירא\u0004 \u0005[היציאה לאויר]\u0006 יחד \u0003גרמי\u0004 \u0005[גורמים]\u0006 לכך, וכיון שלא נולד — חלבו מותר.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לרבי שמעון בן לקיש\u0004 ממה ששנינו בענין הקרבת חלבו של עובר הנמצא במעי בהמת קדשים: \u0003מה\u0004 דין הקרבת \u0003חלב ושתי כליות האמורות ב\u0004קרבן \u0003אשם\u0004 — \u0003מוצא מכלל שליל\u0004 (עובר), אינו יכול להתקיים בשליל שבמעי אמו, שהרי קרבן אשם בא רק מן הזכרים, \u0003אף כל\u0004 קרבן, גם זה הבא מן הנקבה — \u0003מוצא מכלל שליל,\u0004 אין מצוה להקריב את החלב של השליל שנמצא בה.","ומעתה, \u0003בשלמא לדידי\u0004 \u0005[נניח לשיטתי],\u0006 שחלב שליל שבמעי אמו חלב גמור הוא — \u0003היינו דאיצטריך קרא למעוטי\u0004 \u0005[זה הוא\u0006 הטעם \u0005שהוצרך הפסוק למעט],\u0006 לומר שאין מקריבים אותו. \u0003אלא לדידך\u0004 \u0005[לשיטתך],\u0006 שאינו נחשב כחלב גמור, \u0003אמאי איצטריך\u0004 \u0005[מדוע הוצרך]\u0006 הכתוב למעט אותו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003טעמא דידי נמי מהכא\u0004 \u0005[הטעם שלי גם כן מכאן הוא]\u0006, כלומר, מדרשה זו עצמה אני לומד שחלב העובר אין בו איסור חלב.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת, \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבי שמעון בן לקיש לרבי יוחנן\u0004 ממה ששנינו בברייתא זו: \u0003מה חלב ושתי כליות האמורות באשם\u0004 — \u0003מוצא מכלל שליל, אף כל\u0004 — \u0003מוצא מכלל שליל.\u0004","ומעתה, \u0003בשלמא לדידי\u0004 \u0005[נניח לשיטתי],\u0006 שחלבו של עובר אינו נחשב חלב — \u0003משום הכי מיעטיה רחמנא\u0004 \u0005[משום כך מיעטה אותו התורה]\u0006 מהקרבה, \u0003אלא לדידך\u0004 \u0005[לשיטתך],\u0006 שדינו ככל חלב בהמה — \u0003ליקרב\u0004 \u0005[שיקרב]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: טעם הדבר שאינו מוקרב אינו משום שאינו חלב גמור, אלא משום שהשליל עצמו אינו נחשב קרבן שצריך להקריב את חלבו. \u0003מידי דהוה\u0004 \u0005[כמו שהוא הדין]\u0006 בקרבן שהוא \u0003מחוסר זמן,\u0004 שלא מלאו לו שבעה ימים, שהוא פסול להקרבה (ויקרא כב, כז), למרות שחלבו בוודאי אסור.","ושבים למחלוקת במשנתנו בדינו של בן תשעה חי הנמצא במעי בהמה שנשחטה, שלדעת ר' מאיר טעון שחיטה, ולדעת חכמים (ר' יהודה) הותר בשחיטת אמו. \u0003אמר רבי אמי: השוחט את הטרפה ומצא בה בן תשעה חי, לדברי\u0004 ר' מאיר \u0003האוסר\u0004 בן תשעה הנמצא בבהמה כשרה, שאינו ניתר בשחיטת אמו, וטעון שחיטה לעצמו, גם אם נמצא בטריפה הרי הוא \u0003מתיר\u0004 אותו בשחיטת עצמו. \u0003לדברי\u0004 ר' יהודה \u0003המתיר\u0004 בן תשעה הנמצא בבהמה כשרה, ששחיטת אמו מתירתו, אם נמצא בטריפה — הריהו \u0003אוסר\u0004 אותו, מפני ששחיטת אמו לא התירה אותו באכילה, כשם שלא התירה את עצמה, וגם אינו ניתר בשחיטת עצמו.","\u0003רבא אמר: לדברי המתיר\u0004 בן תשעה שנמצא בבהמה כשרה שנשחטה, כשנמצא בטריפה \u0003נמי\u0004 \u0005[גם כן]\u0006 הוא \u0003מותר\u0004 בשחיטת עצמו, שכן \u0003ארבע סימנין אכשר ביה רחמנא\u0004 \u0005[הכשירה בו התורה]\u0006 בבן תשעה חי, או בשחיטת שני סימנים (קנה וושט) של אמו, או במקרה שלא הותר בשחיטתה — בשחיטת שני סימנים שלו.","בענין זה מסופר, \u0003ש\u0004\u0003אמר רב חסדא\u0004 לתלמידיו: \u0003השוחט את הטרפה, ומצא בה בן תשעה חי\u0004 —"],["הרי זה \u0003טעון שחיטה\u0004 בעצמו ומותר באכילה, \u0003ו\u0004כיון שיש בו שחיטה לעצמו הריהו \u0003חייב ב\u0004נתינת \u0003זרוע והלחיים והקבה,\u0004 שצריך לתת לכהן מכל בהמת חולין שנשחטה, \u0003ואם מת\u0004 — \u0003טהור מלטמא במשא\u0004 כנבילה, ששחיטת אמו כשהוא במעיה טיהרה אותו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב חסדא בתמיהה: כשאתה אומר \u0003טעון שחיטה, כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אתה אומר? \u0003כ\u0004דעת \u0003ר' מאיר\u0004 במשנתנו, שבן תשעה חי אינו ניתר כלל בשחיטת אמו, \u0003ו\u0004כשאתה אומר \u0003ש\u0004\u0003אם מת טהור מלטמא במשא, כמאן\u0004 \u0005[כדעת מי]\u0006 אתה אומר? \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים]\u0006 אתה אומר, ששחיטת אמו מטהרתו!","אמר לו רב חסדא: \u0003וליטעמיך\u0004 \u0005[ולשיטתך],\u0006 \u0003הא דתני\u0004 \u0005[\u0006ברייתא \u0005זו ששנה]\u0006 \u0003רבי חייא: השוחט את הטרפה ומצא בה בן תשעה חי\u0004 — \u0003טעון שחיטה, וחייב בזרוע והלחיים והקבה, ואם מת\u0004 — \u0003טהור מלטמא במשא\u0004 — גם על ברייתא זו תקשה: \u0003טעון שחיטה, כמאן\u0004 \u0005[כשיטת מי]?\u0006 \u0003כר' מאיר, ואם מת\u0004 — \u0003טהור מלטמא במשא, כרבנן\u0004 \u0005[כדעת חכמים]!\u0006","השיב לו רבא: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 כי אפשר לומר ש\u0003ר' חייא, אם כבר מצאו מת\u0004 במעי אמו \u0003קאמר\u0004 \u0005[אמר]\u0006 שאינו מטמא במשא, ובמקרה זה גם ר' מאיר מודה ששחיטת אמו מטהרתו, כפי ששנינו במשנה, ויש לומר שברייתא זו כולה כשיטת ר' מאיר. \u0003אלא לדידך\u0004 \u0005[לשיטתך]\u0006 שלא תירצת כך, \u0003קשיא\u0004 \u0005[קשה]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003לדידי נמי לא קשיא\u0004 \u0005[לשיטתי גם כן לא קשה],\u0006 כי יש לומר שברייתא זו כולה שיטת חכמים, הסבורים ששחיטת האם מטהרתו, ולמרות זאת הריהו ניתר בשחיטה עצמו, כי \u0003ארבעה סימנים אכשר ביה רחמנא\u0004 \u0005[הכשירה בו התורה]\u0006 בבן תשעה, בשחיטת סימנים (קנה וושט) של אמו, וגם בשחיטת סימנים שלו.","מסופר, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' זירא\u0004 לארץ ישראל, \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003רב אסי דיתיב\u0004 \u0005[שיושב],\u0006 \u0003וקאמר ליה להא שמעתא\u0004 \u0005[ואמר את השמועה הזו],\u0006 שאמר רב חסדא, שארבעה סימנים הכשירה התורה בבן תשעה חי. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יישר\u0004 \u0005[יפה],\u0006 \u0003וכן אמר ר' יוחנן.\u0004 שאל אותו ר' זירא: האם \u0003מכלל\u0004 הדברים יש להבין \u0003דפליג\u0004 \u0005[שחלק]\u0006 \u0003עליה ר' שמעון בן לקיש\u0004 שהיה יושב עמו בבית המדרש?","אמר לו: לא נתברר לי הדבר, כי \u0003משהא הוה שהי ליה ושתיק ליה\u0004 \u0005[שוהה היה לו ושותק לו]\u0006 באותה שעה, ואיני יודע האם לאחר מכן חלק עליו. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שכך אמר רב אסי: \u0003משתא הוה שתי ושתיק ליה\u0004 \u0005[שותה היה דבר מה ושותק לו],\u0006 ואין אני יודע אם חלק עליו או לא.","שנינו במשנה, שלדעת חכמים, בן תשעה חי הנמצא במעי בהמה שחוטה (בן פקועה) — הותר בשחיטתה. \u0003רבי שמעון שזורי אומר: אפילו\u0004 בן חמש שנים וחורש בשדה — שחיטת אמו (כשהיה במעיה) מטהרתו, ואינו טעון שחיטה. ושואלים: שיטת ר' שמעון שזורי \u0003היינו תנא קמא\u0004 \u0005[הרי זו שיטתו של התנא הראשון],\u0006 דעת חכמים! \u0003אמר רב כהנא:\u0004 אם \u0003הפריס\u0004 (עמד, הניח פרסותיו) \u0003על גבי קרקע איכא בינייהו\u0004 \u0005[יש ביניהם].\u0006 שלדעת התנא הראשון, אם לאחר שהוציאוהו ממעי אמו נעמד על רגליו — הריהו טעון שחיטה, גזירה שמא יבואו אנשים להתיר בהמות אחרות ללא שחיטה.","ובענין בן פקועה \u0003אמר רב משרשיא: לדברי\u0004 התנא \u0003האומר\u0004 ש\u0003חוששין\u0004 בבהמה \u0003לזרע האב,\u0004 כלומר, מתחשבים גם באב בהגדרת הוולד, \u0003בן פקועה\u0004 שאינו טעון שחיטה, \u0003הבא על בהמה מעלייתא\u0004 \u0005[מעולה,\u0006 רגילה\u0005]\u0006 — \u0003הולד\u0004 של זו \u0003אין לו תקנה\u0004 להתירו בשחיטה, כיון שמצד אמו הוא טעון שחיטה, ומצד אביו אינו טעון שחיטה. ושבים למחלוקת חכמים ור' שמעון שזורי.","\u0003אמר אביי: הכל,\u0004 כלומר, גם חכמים המצריכים שחיטה לבן פקועה שהפריס, גם הם \u0003מודים\u0004 לענין \u0003קלוט\u0004 (שפרסתו אינה שסועה, כשל בהמה רגילה) \u0003בן פקועה, ש\u0004הוא \u0003מותר\u0004 בלא שחיטה; \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כל מלתא דתמיהא מידכר דכירי לה אינשי\u0004 \u0005[כל דבר תמוה,\u0006 חריג, \u0005זוכרים אותו בני האדם],\u0006 שכיון שהוא קלוט, זוכרים שהוא מקרה יוצא דופן, ולא יבואו ללמוד ממנו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, \u0003אמר אביי: הכל מודים בקלוט בן קלוטה בן פקועה שמותר\u0004 בלא שחיטה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003תרי תמיהי מידכר דכירי אינשי\u0004 \u0005[שני\u0006 דברים \u0005תמוהים זוכרים אנשים].\u0006","\u0003אמר זעירי אמר ר' חנינא: הלכה כר' שמעון שזורי,\u0004 שבן פקועה מותר בלא שחיטה, אפילו הפריס על גבי הקרקע. \u0003וכן היה רבי שמעון שזורי מתיר בבנו\u0004 של בן פקועה \u0003ובן בנו עד סוף כל הדורות. ר' יוחנן אמר: הוא מותר, ובנו אסור.\u0004","מסופר, \u0003אדא בר חבו הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003בן פקועה דנפל דובא עליה\u0004 \u0005[שנפל דוב עליו],\u0006 טרף אותו, ועמד למות. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב אשי\u0004 לשאול מה לעשות, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שחטיה\u0004 \u0005[לך שחוט אותו]\u0006 קודם שימות כדי שתוכל לאוכלו, וכדין בן פקועה שהפריס על גבי קרקע. \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003זעירי אמר ר' חנינא: הלכה כר' שמעון שזורי\u0004 שבן פקועה אינו טעון שחיטה, \u0003וכן היה ר' שמעון שזורי מתיר בבנו ובן בנו עד סוף כל הדורות. ואפילו ר' יוחנן לא קאמר\u0004 \u0005[אמר]\u0006 שיש לאסור \u0003אלא\u0004 את \u0003בנו, אבל איהו\u0004 \u0005[הוא עצמו]\u0006 — \u0003לא!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רבי יוחנן לדברי ר' שמעון שזורי קאמר\u0004 \u0005[אמר],\u0006 שגם לדברי ר' שמעון שזורי, דווקא בן פקועה עצמו מותר, אבל בנו אסור. ואולם ר' יוחנן עצמו סבור כחכמים, שגם בן הפקועה עצמו אסור.","הוסיף והקשה לו אדא בר חבו: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבין בר חנינא אמר עולא אמר רבי חנינא\u0004 לענין אחר: \u0003הלכה כרבי שמעון שזורי; ו\u0004הוסיף כי \u0003לא עוד, אלא כל מקום ששנה ר' שמעון שזורי במשנתנו\u0004 (בששה סדרי משנה) \u0003הלכה כמותו!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אנא כי הא סבירא לי\u0004 \u0005[אני כשיטה זו סבור אני],\u0006 ש\u0003אמר רבי יונתן: הלכה כר' שמעון שזורי ב\u0004דין \u0003מסוכן, וב\u0004דין \u0003תרומת מעשר של דמאי,\u0004 ולא בשאר דברים כגון בדין בן פקועה.","ומפרטים: \u0003מסוכן\u0004 מהו? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003בראשונה היו אומרים, היוצא בקולר\u0004 ליהרג \u0003ואמר: \"כתבו גט לאשתי\",\u0004 אף על פי שלא אמר \u0003\"תנו\" —\u0004 \u0003הרי אלו\u0004 השומעים \u0003יכתבו ויתנו,\u0004 שבוודאי לכך היתה כוונתו. \u0003חזרו לומר\u0004 — \u0003אף המפרש\u0004 לים \u0003והיוצא בשיירא\u0004 שאמר \"כתבו\" — דנים אותו כאילו אמר \"תנו\", ו\u0003ר' שמעון שזורי אומר: אף\u0004 החולה \u0003המסוכן.\u0004","\u0003תרומת מעשר של דמאי,\u0004 מה עניינה? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003תרומת מעשר של דמאי,\u0004 שהפרישו מתבואה של עם הארץ החשוד על המעשרות, \u0003שחזרה\u0004 ונפלה \u0003למקומה\u0004 והתערבה עם שאר התבואה, \u0003ר' שמעון שזורי אומר:\u0004 במקרה זה, לא רק בשבת התירו לשאול את עם הארץ אם עישר את תבואתו, ולסמוך עליו, אלא \u0003אף בחול שואלו, ו\u0004\u0003אם אמר שהוא היה מעושר מתחילה —\u0004 \u0003אוכלו על פיו.\u0004"],["\u0003בהמה שנחתכו רגליה\u0004 האחוריות, \u0003מן הארכובה\u0004 (הברך) \u0003ולמטה\u0004 — \u0003כשרה, מן הארכובה ולמעלה\u0004 — \u0003פסולה\u0004 (טריפה), \u0003וכן שניטל צומת הגידין,\u0004 המקום שבו מתחברים הגידים יחד בתחתית העצם האמצעית, עצם השוק.","\u0003נשבר העצם,\u0004 ולא נחתכה הרגל לגמרי, \u0003אם רוב הבשר קיים\u0004 במקום השבר — \u0003שחיטתו\u0004 של הבהמה \u0003מטהרתו,\u0004 והוא מותר באכילה, \u0003ואם לאו,\u0004 אם אין רוב הבשר קיים — \u0003אין שחיטתו מטהרתו,\u0004 אלא כל אותו חלק מדולדל אסור באכילה.","\u0003אמר רב יהודה אמר רב אמר רבי חייא:\u0004 מה ששנינו שבהמה שנחתכו רגליה מן הארכובה ולמטה כשרה, \u0003למטה\u0004 כוונתו — כל מה ש\u0003למטה מן הארכובה,\u0004 ומה ששנינו: מן הארכובה ולמעלה טריפה, \u0003למעלה\u0004 כוונתו — כל מה ש\u0003למעלה מן הארכובה,\u0004 ו\u0003באיזו ארכובה אמרו? בארכובה\u0004 שבראש העצם התחתונה, \u0003הנמכרת עם הראש,\u0004 שהקצבים חותכים ומוכרים יחד עם הפרסה. והיא הארכובה שבין העצם האמצעית לעצם התחתונה. ולפי זה, רק אם נחתכה הרגל בעצם האמצעית ולמעלה — הרי זו טריפה.","\u0003עולא אמר\u0004 בשם \u0003רבי אושעיא:\u0004 ארכובה שמדובר עליה היא הארכובה העליונה, שבין העצם העליונה והאמצעית, שאינה ניכרת כלפי חוץ, אבל \u0003כנגדו ב\u0004רגל ה\u0003גמל\u0004 הוא \u0003ניכר,\u0004 בולט. ולפי זה, רק אם נחתכה העצם העליונה הריהי טריפה, אבל אם נחתכה העצם האמצעית — כשרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003עולא לרב\u0004 \u0003יהודה: בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטתי שאני אומר]\u0006 שהארכובה היא זו ש\u0003כנגדו בגמל ניכר,\u0004 ואם נחתכה העצם האמצעית כשרה — \u0003היינו דקתני\u0004 \u0005[זהו ש\u0006התנא \u0005שונה]\u0006 במשנה: \u0003וכן שניטל צומת הגידין,\u0004 להשמיענו שלמרות שאם נחתכה הרגל בחלקה העליון של העצם האמצעית — הריהי כשרה, אם נחתכה בתחתית אותה עצם וכך ניטל צומת הגידים — הריהי טריפה. \u0003אלא\u0004 \u0003לדידך\u0004 \u0005[לשיטתך],\u0006 שמדובר בארכובה התחתונה, ואם נחתכה הרגל בכל מקום למעלה משם הריהי טריפה, \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003וכן שניטל צומת הגידין?\u0004 מדוע הוצרך לומר כן? והרי כל מקום בעצם האמצעית הוא למעלה מן הארכובה, וגם מקום צומת הגידים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: לשיטתי שנינו שני מקרים שעושים טריפה: האחד — שנחתכה העצם למעלה מן ה\u0003רכובה\u0004 (הארכובה) \u0003בלא\u0004 שיינטל \u0003צומת הגידים, ו\u0004השני — שניטל \u0003צומת הגידים בלא\u0004 שנחתכה הרגל למעלה מן ה\u0003רכובה.\u0004 הקשה לו עולא: כיצד אתה יכול לפרש כך? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"נחתכו\u0004 רגליה מן הארכובה ולמעלה\" \u0003קתני\u0004 \u0005[הוא שונה],\u0006 ומשמע — נחתכו לגמרי, כולל צומת הגידים! \u0003אישתיק\u0004 \u0005[שתק]\u0006 רב יהודה ולא מצא תשובה.","\u0003לבתר דנפק\u0004 \u0005[אחרי שיצא]\u0006 עולא \u0003אמר\u0004 רב יהודה לעצמו: \u0003מאי טעמא לא אמרי ליה\u0004 \u0005[מה טעם לא אמרתי לו],\u0006 שלשיטתי, \"מן הארכובה ו\u0003למטה\u0004 כשרה\" פירושו — \u0003למטה מן הארכובה,\u0004 אבל \"מן הארכובה ו\u0003למעלה\u0004 טריפה\" פירושו — \u0003למעלה\u0004 מן הארכובה וגם \u0003מצומת הגידין?\u0004 שהרי באופן זה, צריך התנא להוסיף ולומר כי לא רק אם נחתכה הרגל למעלה מצומת הגידים הרי זו טריפה, אלא גם אם נחתכה בצומת הגידים!","\u0003הדר\u0004 \u0005[חזר]\u0006 רב יהודה ו\u0003אמר\u0004 לעצמו: \u0003ולא אמרי ליה\u0004 \u0005[ו\u0006כי \u0005לא אמרתי לו]\u0006 תירוץ, \u0003ואמר לי: \"נחתכו\" קתני\u0004 \u0005[שנה],\u0006 שהדבר אינו עולה כראוי עם לשון המשנה? \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יכול היה להקשות לי: כיצד אתה מפרש מן הארכובה ולמעלה — למעלה מן הארכובה ומצומת הגידים? והרי \u0003\"מן הארכובה ולמעלה\" קתני\u0004 \u0005[הוא שונה],\u0006 ומשמע — כל מה שלמעלה מן הארכובה, וגם בצומת הגידים. עד כאן נוסח אחד של הדברים.","\u0003רב פפא מתני הכי\u0004 \u0005[היה שונה\u0006 \u0005כך]\u0006, \u0003אמר רב יהודה אמר רב אמר רבי חייא:\u0004 הארכובה שמדובר עליה במשנה היא הארכובה העליונה, שבין העצם האמצעית לעצם העליונה, שכנגדו בגמל ניכר. ולפיכך, מה ששנינו: נחתכו רגליה \u0003למטה\u0004 מן הארכובה כשרה, כוונתו — \u0003למטה מן הארכובה ומצומת הגידין\u0004 שבתחתית העצם האמצעית, כלומר, כשנחתכו בעצם התחתונה. ומה ששנינו שאם נחתכו רגליה \u0003למעלה\u0004 מן הארכובה טריפה — פירושו שנחתכו \u0003למעלה מן הארכובה ומצומת הגידין,\u0004 כלומר שנחתכו בעצם העליונה. ועל כך הוסיף התנא: \u0003וכן שניטל,\u0004 שנחתכה הרגל במקום \u0003צומת הגידין\u0004 שבתחתית העצם האמצעית, גם כן טריפה, למרות שאם נחתכה הרגל בעצם האמצעית למעלה משם — הריהי כשרה. \u0003ו\u0004כאמור, לדרך זו \u0003ארכובה גופה\u0004 \u0005[עצמה]\u0006 היא הארכובה העליונה, הניכרת בגמל, \u0003כ\u0004דברי \u0003עולא\u0004 ש\u0003אמר\u0004 כן לעיל בשם \u0003רב אושעיא.\u0004","ותמהים על הסבר זה: \u0003ומי איכא מידי\u0004 \u0005[והאם יש,\u0006 יתכן \u0005דבר כזה],\u0006 \u0003דאילו מדלי פסיק ליה\u0004 \u0005[שאם למעלה,\u0006 בעצם האמצעית, \u0005חותך אותו]\u0006 \u0003ו\u0004הבהמה \u0003חיה, מתתי פסיק ליה\u0004 \u0005[\u0006ואם \u0005למטה,\u0006 בצומת הגידים שבתחתית עצם זו, \u0005חותך אותו]\u0006 \u0003ו\u0004היא \u0003מתה?\u0004","\u0003אמר רב אשי: טרפות קא מדמית להדדי\u0004 \u0005[אתה מדמה זו לזו]?\u0006 \u0003אין אומרין בטרפות זו דומה לזו, שהרי\u0004 מקומות שונים יש בגוף הבהמה, \u0003חותכה מכאן ומתה, חותכה מכאן וחיה.\u0004","ושואלים: \u0003ואלו הן,\u0004 מהם גבולות \u0003צומת הגידין\u0004 שאם נחתכו שם הגידים הרי זו טריפה\u0003? רבה אמר רב אשי: דאגרמא ולבר\u0004 \u0005[\u0006המקום \u0005שמן העצם ולחוץ],\u0006 לא ממש בתחתית העצם האמצעית, שם הגידים צמודים לעצם, אלא למעלה משם, ממקום בו הגידים נפרדים מן העצם. ומשם ולמעלה, כל זמן שהם צמותים יחד עד שהם מתפצלים ונבלעים בבשר (בשרירים) — הרי זה צומת הגידים. \u0003רבה בר רב הונא אמר רב אשי: דאגרמא ולגיו\u0004 \u0005[מן העצם ולפנים],\u0006 האזור שבו הגידים צמודים לעצם — הוא צומת הגידים. \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר רב הונא אמר רב אסי:\u0004 גם למטה משם, \u0003דעילוי ערקומא\u0004 \u0005[\u0006באזור \u0005שמעל הערקום],\u0006 מעל אותה עצם קטנה שבין העצם האמצעית לעצם התחתונה — הרי זה צומת הגידים.","מסופר, \u0003יתיב ההוא מרבנן קמיה\u0004 \u0005[ישב אחד מהחכמים לפני]\u0006 \u0003ר' אבא, ויתיב וקאמר\u0004 \u0005[ויושב היה ואומר]:\u0006 צומת הגידים הוא \u0003דערקומא גופה\u0004 \u0005[\u0006הגידים \u0005של הערקום עצמו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי אבא: לא תציתו ליה\u0004 \u0005[אל תקשיבו לו],\u0006 מחמיר הוא מדי, להטריף בהמה שנחתכו שם גידיה! \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה: היכא דפרעי טבחי\u0004 \u0005[במקום שבו פותחים,\u0006 חותכים \u0005הטבחים]\u0006 את רגלי הבהמות. ומעירים: \u0003והיינו\u0004 \u0005[והוא\u0006 הדבר\u0005]\u0006 שאמר \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר רב הונא אמר רב אסי,\u0004 שהוא האזור שמעל הערקום.","ומביאים מה ש\u0003אמר רב יהודה אמר שמואל: צומת הגידים שאמרו\u0004 במשנה הוא ה\u0003מקום ש\u0004בו \u0003הגידין צומתין\u0004 (מתחברים ונראים כאחד), \u0003ועד כמה\u0004\u0003?\u0004 מה אורכו? \u0003אמר להו ההוא מדרבנן\u0004 \u0005[אמר להם אחד מהחכמים],\u0006 \u0003ורב יעקב שמיה\u0004 \u0005[שמו]:\u0006 \u0003כי הוינן בי\u0004 \u0005[כאשר היינו בבית]\u0006 \u0003רב יהודה אמר לן\u0004 \u0005[לנו]:\u0006 \u0003שמעו מני מלתא דמגברא רבה שמיע לי\u0004 \u0005[שמעו ממני דבר, שמאדם גדול שמעתי אותו],\u0006 \u0003ומנו\u0004 \u0005[ומיהו]?\u0006 \u0003שמואל: צומת הגידין שאמרו\u0004 — \u0003מקום שהגידין צומתין בו, וממקום שצומתין עד מקום שמתפשטין.\u0004","\u0003וכמה?\u0004 עד היכן? \u0003אמר אביי: ארבעה בטדי בתורא\u0004 \u0005[טפחים בשור].\u0006 ושואלים: \u0003ב\u0004בהמה \u0003דקה מאי\u0004 \u0005[מה השיעור]?\u0006 \u0003אמר אביי: בליטי\u0004 \u0005[כל שהם בולטים]\u0006 ואינם נבלעים בבשר \u0005—\u0006 \u0003הוו\u0004 \u0005[הריהם]\u0006 נחשבים כ\u0003צומת הגידים, בליעי\u0004 \u0005[\u0006כאשר הם \u0005מובלעים\u0006 בבשר\u0005]\u0006 — \u0003לא הוו\u0004 \u0005[אין הם]\u0006 נחשבים \u0003צומת הגידים.\u0004","\u0003אשוני\u0004 \u0005[\u0006כאשר הם \u0005קשים]\u0006 — \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003צומת הגידים, רכיכי\u0004 \u0005[\u0006כאשר הם \u0005רכים]\u0006 — \u0003לא הוו\u0004 \u0005[אין הם]\u0006 נחשבים \u0003צומת הגידים; אלימי\u0004 \u0005[\u0006כשהם \u0005עבים]\u0006 — \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003צומת הגידים, קטיני\u0004 \u0005[\u0006כאשר הם \u0005דקים]\u0006 — \u0003לא הוו\u0004 \u0005[אין הם]\u0006 \u0003צומת הגידים; חוורי\u0004 \u0005[\u0006כאשר הם \u0005לבנים]\u0006 — \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003צומת הגידים, לא חוורי\u0004 \u0005[כשאינם לבנים]\u0006 — \u0003לא הוו\u0004 \u0005[אין הם]\u0006 \u0003צומת הגידים.\u0004"],["\u0003מר בר רב אשי אמר: כיון דזיגי\u0004 \u0005[שהם שקופים],\u0006 \u0003אף על גב דלא חוורי\u0004 \u0005[אף על פי שאינם לבנים]\u0006 ממש, הרי זה מקום צומת הגידים.","ובשאלה מה נחשבת נטילה של צומת הגידים, שעושה טריפה, \u0003אמר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב זביד: תלתא חוטי הוו\u0004 \u0005[שלושה חוטים,\u0006 גידים \u0005הם],\u0006 \u0003חד אלימא ותרי קטיני\u0004 \u0005[אחד עבה ושנים דקים];\u0006 \u0003איפסיק אלימא\u0004 \u0005[נפסק,\u0006 נחתך החוט \u0005העבה]\u0006 — \u0003אזדא\u0004 \u0005[הלך]\u0006 \u0003רוב\u0004 ה\u0003בנין\u0004 של צומת הגידים, שהעבה — עבה משני הדקים יחדיו, ודין רובו ככולו; \u0003איפסיק קטיני\u0004 \u0005[נפסקו הדקים]\u0006 — \u0003אזדא\u0004 \u0005[הלך]\u0006 \u0003רוב מנין\u0004 הגידים, וגם בזה דין רובו ככולו. ואילו \u0003מר בר רב אשי מתני לקולא\u0004 \u0005[היה שונה\u0006 אותו דבר אבל \u0005להקל]:\u0006 \u0003איפסיק אלימא\u0004 \u0005[נפסק העבה]\u0006 — \u0003האיכא\u0004 \u0005[הרי יש]\u0006 עדיין \u0003רוב מנין,\u0004 ואינו טריפה, וכן \u0003איפסיק קטיני\u0004 \u0005[נפסקו הדקים]\u0006 — \u0003האיכא\u0004 \u0005[הרי יש]\u0006 עדיין \u0003רוב בנין.\u0004","וממשיכה הגמרא: וכל זה הוא בבהמה, אבל \u0003בעופות שיתסר חוטי הוו\u0004 \u0005[שישה עשר חוטים הם],\u0006 \u0003אי פסיק חד מינייהו\u0004 \u0005[אם נפסק אחד מהם]\u0006 — הרי זו \u0003טרפה. אמר מר בר רב אשי: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003אבא,\u0004 רב אשי, \u0003ואייתו לקמיה עופא\u0004 \u0005[והביאו לפניו עוף],\u0006 \u0003ובדק ואשכח ביה חמיסר\u0004 \u0005[ובדק ומצא בו חמישה עשר\u0006 חוטים\u0005],\u0006 \u0003הוה חד דהוה שני מחבריה\u0004 \u0005[היה אחד מהם שהיה שונה מחבריו],\u0006 \u0003נפציה ואשכח תרי\u0004 \u0005[ניפץ,\u0006 פירק \u0005אותו ונמצא\u0006 שהיה מורכב מ\u0005שני\u0006 חוטים\u0005]\u0006 דבוקים זה לזה. ושבים לדין צומת הגידים שבבהמה.","\u0003אמר רב יהודה אמר רב: צומת הגידין שאמרו\u0004 שאם ניטל הרי זו טריפה — \u0003ברובו;\u0004 והוסיף: \u0003מאי\u0004 \u0005[\u0006ו\u0005מה\u0006 פירוש\u0005]\u0006 \u0003רובו?\u0004 אם נחתך \u0003רוב אחד מהן\u0004 מן הגידים. והוסיף רב יהודה \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי הלכה זו\u0006 בשם רב \u0005לפני]\u0006 \u0003שמואל, אמר לי: מכדי תלתא הוו\u0004 \u0005[הואיל ושלושה\u0006 גידים \u0005הם],\u0006 \u0003כי מיפסיק חד מינייהו\u0004 \u0005[כאשר נפסק אחד מהם]\u0006 \u0003לגמרי, הא איכא תרי\u0004 \u0005[הרי יש\u0006 עדיין \u0005שנים],\u0006 ורובו של צומת הגידים קיים!","ומדייקים מדברי שמואל: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דאיכא תרי\u0004 \u0005[כשיש שנים]\u0006 הרי זו כשרה, \u0003הא ליכא תרי\u0004 \u0005[הרי כשאין\u0006 אפילו \u0005שנים]\u0006 — \u0003לא,\u0004 אלא טריפה היא, למרות שהגיד שנותר שלם. ומעירים: \u0003ופליגא\u0004 \u0005[וחלוק\u0006 הדבר הזה\u0005]\u0006 על מה שאמר \u0003רבנאי\u0004 משמו, ש\u0003אמר רבנאי אמר שמואל: צומת הגידים, אפילו לא נשתייר בה אלא\u0004 גיד אחד שעוביו \u0003כחוט הסרבל\u0004 —","הרי זו \u0003כשרה. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 מסורת אחרת בענין זה. שרב יהודה אמר בשם רב: צומת הגידים שאמרו שאם ניטל עושה טריפה — ברובו, \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003רובו?\u0004 שנחתך \u0003רוב\u0004 של \u0003כל אחד ואחד.\u0004 והוסיף רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי הלכה זו לפני]\u0006 \u0003שמואל, אמר לי: מכדי תלתא הוו\u0004 \u0005[הואיל ושלושה\u0006 גידים \u0005הם],\u0006 \u0003האיכא תלתא דכל חד וחד\u0004 \u0005[הרי\u0006 עדיין \u0005יש שליש של כל אחד ואחד],\u0006 ודי בכך! ומעירים: דבר זה שאמר רב יהודה בשם שמואל \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרבנאי,\u0004 ש\u0003אמר רבנאי אמר שמואל: צומת הגידין שאמרו, אפילו לא נשתייר בה\u0004 בכל אחד משלושת הגידים \u0003אלא כחוט הסרבל\u0004 — \u0003כשרה.\u0004","שנינו במשנה: \u0003נשבר העצם\u0004 של רגל הבהמה האחורית, אם רוב הבשר שם קיים — שחיטתו מטהרתו, ואם לאו — אין שחיטתו מטהרתו, והוא אסור באכילה כדין אבר המדולדל העומד ליפול.","ובענין זה \u0003אמר רב:\u0004 נשבר העצם \u0003למעלה מן הארכובה, אם רוב הבשר קיים\u0004 במקום השבר — \u0003זה וזה מותר,\u0004 כלומר, גם הבהמה מותרת — שאינה נעשית טריפה בכך, וגם האבר — שאינו נחשב כאבר מדולדל, אלא ניתר בשחיטת הבהמה. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאין רוב הבשר קיים במקום השבר — \u0003זה וזה אסור.\u0004 אבל אם נשבר העצם \u0003למטה מן הארכובה, אם רוב הבשר קיים\u0004 — \u0003זה וזה מותר, אם לאו\u0004 \u0005[לא]\u0006 — \u0003אבר\u0004 עצמו \u0003אסור\u0004 (ממקום השבר ולמטה), שאינו ניתר בשחיטת הבהמה, \u0003ובהמה\u0004 עצמה \u0003מותרת.\u0004","\u0003ושמואל אמר: בין\u0004 נשבר \u0003למעלה\u0004 מן הארכובה \u0003בין למטה\u0004 ממנה, \u0003אם רוב הבשר קיים\u0004 — \u0003זה וזה,\u0004 האבר והבהמה, \u0003מותר, אם לאו\u0004 \u0005[לא]\u0006 נשתייר רוב הבשר — ה\u0003אבר אסור, ובהמה\u0004 עצמה \u0003מותרת,\u0004 שאינה נעשית טריפה (אפילו נשברה הרגל למעלה מן הארכובה) עד שתיחתך הרגל לגמרי.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: ל\u0004שיטת \u0003שמואל,\u0004 כשנשברה העצם למעלה מן הארכובה (ורוב הבשר אינו קיים), שהאבר אסור והבהמה מותרת — \u0003יאמרו\u0004 אנשים בתמיהה: \u0003אבר ממנה\u0004 מן הבהמה \u0003מוטל באשפה,\u0004 שנאסר באכילה, \u0003ו\u0004היא עצמה \u0003מותרת? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר רב הונא לרב נחמן: ל\u0004שיטת \u0003רב נמי\u0004 \u0005[גם כן],\u0006 כשנשברה העצם למטה מן הארכובה, ואין רוב הבשר קיים — גם כן \u0003יאמרו: אבר ממנה מוטל באשפה ומותרת!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן, \u0003הכי קאמינא\u0004 \u0005[כך אני אומר]:\u0006 לשיטת שמואל, האומר דין זה בעצם שנשברה למעלה מן הארכובה, יאמרו: \u0003אבר ש\u0004בהמה זו \u0003חיה ממנה,\u0004 שאם נחתכה שם הריהי נעשית טריפה — \u0003מוטל באשפה,\u0004 \u0003ו\u0004היא \u0003מותרת?\u0004 אבל דברי רב נאמרו כשנשבר העצם מן הארכובה ולמטה, והוא מקום שאינו עושה טריפה.","בפסיקת ההלכה בענין זה, \u0003שלחו מתם\u0004 \u0005[משם],\u0006 מארץ ישראל: \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב,\u0004 ואם נשברה העצם למעלה מן הארכובה ואין בשר קיים — גם האבר וגם הבהמה אסורים, שטריפה היא. \u0003הדור\u0004 \u0005[חזרו]\u0006 ו\u0003שלחו:\u0004 הלכה \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003שמואל,\u0004 שרק האבר אסור. \u0003הדור\u0004 חזרו ו\u0003שלחו:\u0004 הלכה \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב,\u0004 שהבהמה טריפה, ואמרו: \u0003ואבר עצמו\u0004 אינו נטהר בשחיטתה, אלא \u0003מטמא במשא\u0004 כדין אבר מן החי. שהוא נחשב כאילו נפל ממנה, ואין שחיטתה מטהרת אותו, כפי שהיא מטהרת את הבהמה עצמה מטומאת נבילה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב חסדא\u0004 ממה ששנינו בברייתא: \u0003לא, אם טיהרה שחיטת טרפה אותה ואת האבר המדולדל בה\u0004 — \u0003דבר שגופה, תטהר את העובר\u0004 — \u0003דבר שאינו גופה?\u0004 הרי שהאבר המדולדל של טריפה נטהר בשחיטה, ואינו נחשב כאבר מן החי!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: הדורי אפירכי\u0004 \u0005[לחזר אחר פירכות,\u0006 קושיות\u0005]\u0006 מברייתות שאינן ידועות לכל \u0003למה לך? אותיב ממתניתין\u0004 \u0005[תקשה ממשנה\u0006 מפורשת\u0005]\u0006 ששנינו להלן (קכז,ב) ביחס לאבר ובשר המדולדלים: \u0003נשחטה בהמה\u0004 — \u0003הוכשרו\u0004 \u0003בדמיה\u0004 לקבל טומאת אוכלים, \u0003דברי ר' מאיר, ר' שמעון אומר: לא הוכשרו.\u0004 הרי שדין אוכלים יש להם, שאם תיגע בהם טומאה ייטמאו, ואין להם דין אבר מן החי, שמטמא כבר עכשיו, ואינו צריך הכשר במשא!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתניתין איכא לדחויי כדדחינן\u0004 \u0005[את משנתנו אפשר לדחות כמו שדחינו]\u0006 לעיל (עג,ב), ש\"הוכשרו\" אינו מתייחס לאבר המדולדל, שהוא טמא כאבר מן החי, אלא דווקא לבשר הפורש מן החי, שהוא אינו מטמא במשא.","מסופר \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' זירא\u0004 לארץ ישראל \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003רב ירמיה דיתיב וקאמר לה להא שמעתא\u0004 \u0005[שיושב ואומר את ההלכה הזו],\u0006 שנאמרה לעיל בשם רב, שאם נשבר העצם למעלה מן הארכובה ואין הבשר קיים — הרי זו טריפה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יישר\u0004 \u0005[יפה],\u0006 \u0003וכן תרגמה\u0004 \u0005[תרגם,\u0006 הסביר אותה\u0005]\u0006 את משנתנו, \u0003אריוך בבבל.\u0004 ושואלים: \u0003אריוך מנו\u0004 \u0005[מי הוא]?\u0006 כינויו של מי הוא? \u0003של\u0004 \u0003שמואל, והא מיפלג פליג\u0004 \u0005[והרי חולק הוא],\u0006 כפי שנאמר לעיל! ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003שמואל לגביה\u0004 \u0005[לשיטתו]\u0006 של \u0003רב.\u0004","ועוד בביאור משנתנו, מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נשבר העצם ויצא לחוץ, אם עור ובשר חופין\u0004 (מכסים) \u0003את רובו\u0004 של העצם — \u0003מותר, אם לאו\u0004 \u0005[לא]\u0006 — \u0003אסור.\u0004 ושואלים: \u0003וכמה\u0004 הוא \u0003רובו\u0004 של עצם? \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר\u0004 בשם \u0003ר' יוחנן: רוב עוביו, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר: \u0003רוב הקיפו. אמר רב פפא: הלכך\u0004 \u0005[משום כך],\u0006 שאין לנו הלכה ברורה, \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה מחופה ב\u0003רוב עוביו, ובעינן\u0004 \u0005[וצריכים אנו]\u0006 שיהיה מחופה גם \u0003רוב הקיפו.\u0004","\u0003אמר עולא אמר רבי יוחנן: עור הרי הוא כבשר\u0004 לענין זה, שאם ניטל הבשר, והעור חופה את רוב העצם — הרי זה מותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לעולא: ולימא מר\u0004 \u0005[ושיאמר אדוני]\u0006 \u0003עור מצרף\u0004 \u0005[מצטרף]\u0006 \u0003לבשר,\u0004 שאם בשר ועור יחד חופים את רוב העצם הרי זה כשר, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003\"עור ובשר\" קתני\u0004 \u0005[התנא שונה]\u0006 בברייתא לעיל, אבל עור לבדו אינו מועיל! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנן\u0004 \u0005[אנחנו]\u0006 \u0003\"עור או בשר\" תנינן\u0004 \u0005[שונים אנו].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 נוסח אחר לדברים אלו, \u0003אמר עולא אמר ר' יוחנן: עור מצטרף לבשר. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לעולא: ולימא מר\u0004 \u0005[ושיאמר אדוני]:\u0006 \u0003עור משלים לבשר,\u0004 והוא \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 שאם רוב העצם מחופה ברובו בבשר, ובמיעוטו בעור — הרי זה כשר, אבל מחצה למחצה אינו מצטרף!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא עובדא ידענא\u0004 \u0005[אני מעשה יודע אני],\u0006 \u0003דההוא בר גוזלא דהוה בי\u0004 \u0005[של אותו גוזל שהיה בביתו]\u0006 של \u0003רבי יצחק,\u0004 ונשברה רגלו, ו\u0003עור מצרף\u0004 \u0005[מצטרף]\u0006 \u0003לבשר הוה\u0004 \u0005[היה],\u0006 \u0003ואתא לקמיה\u0004 \u0005[ובא לפני]\u0006 \u0003ר' יוחנן, ואכשריה\u0004 \u0005[והכשיר אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003בר גוזלא קאמרת\u0004 \u0005[בן גוזל אומר אתה]?\u0006 \u0003בר גוזלא דרכיך שאני\u0004 \u0005[\u0006עורו של \u0005בן גוזל שהוא רך שונה],\u0006 שהוא נחשב כבשר!","מסופר, \u0003הנהו\u0004 \u0005[אותם]\u0006 \u0003גידין רכין\u0004 שהיו מצטרפים לבשר לכסות את רוב העצם שנשברה \u0003דאתו לקמיה\u0004 \u0005[שבאו לפני]\u0006 \u0003רבה, אמר רבה: למאי ליחוש להו\u0004 \u0005[למה נחשוש להם]?\u0006 \u0003חדא\u0004 \u0005[אחת],\u0006 ש\u0003אמר ר' יוחנן, גידין שסופן להקשות\u0004"],["\u0003נמנין עליהן בפסח\u0004 לאוכלם, משום שהם נחשבים כבשר. \u0003ועוד: התורה חסה על ממונן של ישראל.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבה\u0004 בתמיהה: והרי \u0003ר' שמעון בן לקיש\u0004 חולק על ר' יוחנן, וסבור שאין נמנים על גידים כאלה, מפני שסופם להקשות, \u0003ואיסורא דאורייתא\u0004 \u0005[ו\u0006יש כאן חשש ל\u0005איסור תורה]\u0006 של אכילת טריפה, \u0003ואת אמרת מאי ליחוש להו\u0004 \u0005[ואתה אומר מה נחשוש להם]?!\u0006 \u0003אישתיק\u0004 \u0005[שתק]\u0006 רבה.","ושואלים: \u0003ואמאי אישתיק\u0004 \u0005[ומדוע שתק]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003ר' שמעון בן לקיש\u0004 במחלוקתו עם ר' יוחנן רק \u0003בהני תלת\u0004 \u0005[באותם שלושה]\u0006 עניינים שהוזכרו במסכת יבמות (לו,א), ולא בעניינים אחרים, ואם כן יכול היה לומר שאין הלכה כריש לקיש בענין זה!","ומשיבים: \u0003שאני הכא דהדר ביה\u0004 \u0005[שונה כאן,\u0006 בענין גידים שסופם להקשות, \u0005שחזר בו]\u0006 \u0003ר' יוחנן לגביה\u0004 \u0005[לשיטתו]\u0006 של \u0003ר' שמעון בן לקיש.\u0004 שהרי בענין עור רך שעתיד להקשות אמר שהוא נדון על שם סופו. וכשהקשה לו ריש לקיש ממשנה שמוכח ממנה להיפך, \u0003אמר לו: אל תקניטני,\u0004 אל תצער אותי, אל תקשה עלי מאותה משנה, ש\u0003בלשון יחיד אני שונה אותה,\u0004 שדעת יחיד היא, ואין הלכה כמותו.","ובפסיקת הלכה למעשה בענין משנתנו מסופר, \u0003ההוא\u0004 \u0005[אותו\u0006 מקרה\u0005]\u0006 ש\u0003נשבר העצם\u0004 של רגל הבהמה \u0003ויצא לחוץ,\u0004 והיה מכוסה ברובו בבשר ועור, אלא \u0003דאישתקיל קורטיתא מיניה\u0004 \u0005[שניטלה חתיכה קטנה ממנו]\u0006 מן העצם, \u0003אתא לקמיה\u0004 \u0005[בא אותו\u0006 מקרה \u0005לפני]\u0006 \u0003אביי. שהייה תלתא ריגלי\u0004 \u0005[השהה אותו\u0006 אביי \u0005שלושה רגלים]\u0006 כדי להתייעץ בדבר עם חכמים אחרים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנא\u0004 לבעל הבהמה: \u0003זיל קמיה\u0004 \u0005[לך לפני]\u0006 \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בר חמא,\u0004 הוא רבא המפורסם, \u0003דחריפא סכיניה\u0004 \u0005[שחריפה סכינו]\u0006 כלומר, שהוא פוסק במהירות. \u0003אתא לקמיה\u0004 \u0005[בא לפניו]\u0006 ושאלו, \u0003אמר\u0004 לו רבא: \u0003מכדי\u0004 \u0005[הואיל]\u0006 ו\u0003נשבר העצם ויצא לחוץ תנן\u0004 \u0005[שנינו]\u0006 במשנתנו, שאם רוב הבשר קיים שחיטתו מטהרתו, \u0003מה לי\u0004 אם \u0003נפל\u0004 העצם, \u0003מה לי איתיה\u0004 \u0005[אם ישנו]\u0006 במקומו?","עוד בעניינים אלה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא:\u0004 אם נשברה העצם והבשר מכסה את רובה כשהוא \u0003מתלקט\u0004 מעט כאן ומעט כאן, \u0003מהו?\u0004 וכן אם היה הבשר \u0003מתרוסס,\u0004 מרוסק ודק, \u0003מהו?\u0004 וכן אם היה \u0003מתמסמס\u0004 (רקוב) \u0003מהו?\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003מתמסמס? אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: כל\u0004 שהוא בשר כזה \u0003שהרופא קודרו,\u0004 חותך אותו מסביב ומוציא אותו, כדי שיוכל המקום להירפא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 אם \u0003ניקב\u0004 הבשר המכסה את העצם \u0003מהו?\u0004 האם דינו כניטל? וכן אם \u0003נקלף\u0004 הבשר מעל העצם \u0003מהו?\u0004 אם \u0003נסדק מהו?\u0004 אם \u0003ניטל שליש התחתון\u0004 של עוביו, הצמוד לעצם, וכל השאר מנותק מן העצם, אבל עדיין מכוסה בעור, \u0003מהו?\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמר עולא אמר ר' יוחנן: עור הרי הוא כבשר,\u0004 הרי שדי במה שנשאר העור. ודוחים: מכאן אין להוכיח, \u0003דלמא\u0004 \u0005[שמא]\u0006 עוסק ר' יוחנן במקום שמעיקרו אין בו בשר, אלא רק עור, כגון סמוך לארכובה, \u0003דקנה משכא דידיה\u0004 \u0005[שקנה,\u0006 החזיק \u0005העור בשלו],\u0006 שהעור דבוק לעצם ומחזיקו. אבל במקום שהבשר ניטל והעור אינו דבוק לעצם לא אמר!","\u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו בבית]\u0006 \u0003רב פפי איבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 השאלה: אם \u0003נקדר,\u0004 נחתך הבשר והעור בסכין \u0003כמין טבעת\u0004 סביב מקום השבר, ומכל מקום רוב היקף העצם מכוסה בבשר, \u0003מהו? ופשטנא מהא\u0004 \u0005[ופתרנו\u0006 שאלה זו \u0005מזו]\u0006 ש\u0003אמר רב יהודה אמר רב: דבר זה שאלתי לחכמים ולרופאים,\u0004 מה לעשות כשנשבר העצם וחתכו את הבשר סביב, \u0003ואמרו: מסרטו\u0004 את מקום החתך \u0003ב\u0004חתיכת \u0003עצם\u0004 חדה, והדם שיוצא נקרש, \u0003ו\u0004כך הוא \u0003מעלה ארוכה.\u0004 ומעירים: ודווקא כשסורטים בעצם, \u0003אבל פרזלא מזרף זריף\u0004 \u0005[ברזל רק חותך]\u0006 ואינו מתקן. \u0003אמר רב פפא: והוא\u0004 שאנו רואים \u0003דקנה גרמא דידיה\u0004 \u0005[שקנה,\u0006 החזיק \u0005העצם את\u0006 הבשר \u0005שלו],\u0006 שהוא דבוק אליו.","\u0003השוחט את הבהמה ומצא בה\u0004 ברחמה \u0003שליא\u0004 — \u0003נפש היפה\u0004 (מי שאינו איסטניס) \u0003תאכלנה,\u0004 מפני שהותרה בשחיטת הבהמה. \u0003ו\u0004כל עוד לא חישב אדם לאוכלה, השליה \u0003אינה מטמאה לא טומאת אוכלין,\u0004 שאם נגעה בה טומאה אינה נטמאת, לפי שאינה עומדת לאכילה, ודינה כפרש בלבד. \u0003ו\u0004כן מטעם זה, אם מתה הבהמה \u0003לא\u0004 מטמאה השליה \u0003טומאת נבלות,\u0004 שהנוגע בה אינו טמא. אבל אם \u0003חישב עליה\u0004 לאכול אותה — \u0003מטמאה טומאת אוכלין, אבל לא טומאת נבלות.\u0004","\u0003שליא שיצתה\u0004 אפילו \u0003מקצתה\u0004 קודם שנשחטה הבהמה — הרי היא \u0003אסורה\u0004 כולה \u0003באכילה,\u0004 שכן שליה היא \u0003סימן ולד באשה וסימן ולד בבהמה,\u0004 ויש לחשוש שבאותו מקצת שיצא — יצא ראש העובר, ובמקרה זה דינו כילוד שאינו נטהר בשחיטת אמו, וכשנאסר הוולד — נאסרה השליה שלו.","\u0003המבכרת\u0004 שעדיין לא ילדה, \u0003שהפילה שליא\u0004 — \u0003ישליכנה לכלבים,\u0004 ואין חוששים שהיה שם זכר והוא בכור. \u0003ובמוקדשין\u0004 אם היתה זו בהמה שהוקדשה לקרבן — \u0003תקבר\u0004 השליה, מפני שאין שליה בלא ולד, ובהמת קדשים שילדה — ולדה קדוש בקדושתה, בין זכר ובין נקבה. ועוד אמרו בענין שליה: \u0003ואין קוברין אותה בפרשת\u0004 (בצומת) \u0003דרכים, ואין תולין אותה באילן,\u0004 כדי שבהמה זו לא תפיל עוד, \u0003מפני דרכי האמורי,\u0004 שהן אמונות טפילות שבהם נוהגים הגויים.","על מה ששנינו ששליה שנמצאת בבהמה מותרת באכילה, אומרים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 \u0003\"כל\u0004 ב\u0003בהמה\u0004 אותה \u0003תאכלו\"\u0004 (דברים יד, ו), לשון \"כל\" — הרי זה בא \u0003לרבות את השליא. יכול אפילו יצתה מקצתה\u0004 של השליה קודם שחיטה הריהי מותרת? \u0003תלמוד לומר: \"אותה\u0004 תאכלו\" — \u0003אותה ולא\u0004 את \u0003שליתה.\u0004","ושואלים: \u0003מכדי\u0004 \u0005[הואיל]\u0006 ואנו מניחים כי \u0003אין שליא בלא ולד,\u0004 הרי די בטעם זה כדי לאוסרה, ואם כן \u0003למה לי קרא\u0004 \u0005[מקרא]\u0006 ללמד שאם יצאה מקצתה אסורה? ומשיבים: \u0003קרא אסמכתא בעלמא\u0004 \u0005[הכתוב היא אסמכתא בלבד],\u0006 שהסמיכו אליו דין זה, אף שבאמת אין צורך ללומדו מכאן.","שנינו על השליה הנמצאת במעי בהמה שנשחטה: \u0003ואינה מטמאה\u0004 לא טומאת אוכלין ולא טומאת נבלות. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יצחק בר נפחא: עור חמור ששלקו\u0004 (שבישל אותו), \u0003מהו\u0004 דינו? ושואלים: \u0003למאי\u0004 \u0005[לאיזה ענין]\u0006 הוא שואל, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003טומאת אוכלין\u0004 — \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר דבר זה,"],["\u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003טומאת נבלות\u0004 — \u0003תנינא\u0004 \u0005[שנינו]!\u0006","ומפרטים: \u0003טומאת אוכלין\u0004 — \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003העור והשליא\u0004 — \u0003אין מטמאין טומאת אוכלין,\u0004 אבל \u0003עור ששלקו, והשליא שחישב עליה\u0004 — \u0003מטמאין טומאת אוכלין.\u0004","\u0003טומאת נבילות נמי תנינא\u0004 \u0005[גם כן שנינו]:\u0006 שעור ששלקו אינו מטמא, שנאמר: \"וכי ימות מן הבהמה וכו' הנוגע בנבלתה יטמא עד הערב\" (ויקרא יא, לט), ודרשו חכמים \u0003\"בנבלתה\"\u0004 — \u0003ולא בעור, ולא בעצמותיו, ולא בגידין, ולא בקרנים, ולא בטלפים.\u0004","\u0003ואמר רבה בר רב חנא: לא נצרכה\u0004 הלכה זו \u0003אלא\u0004 אפילו \u0003שעשאן ציקי קדרה,\u0004 שבישל את העור והעצמות וכו' בישול מרובה עם תבלינים, שבכל זאת אינם מטמאים. ואם כן, מדוע הוצרך ר' יצחק נפחא לשאול מה דינו של עור חמור ששלקו?","ומשיבים: \u0003לעולם\u0004 שאל ר' יצחק נפחא מה דינו לענין \u0003טומאת אוכלין, ו\u0004אף שלכאורה שנינו שעור ששלקו מיטמא טומאת אוכלים, יש לומר ש\u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עור חמור דמאיס\u0004 \u0005[שהוא מאוס],\u0006 והשאלה היתה האם על ידי הבישול הוא נעשה אוכל.","שנינו במשנה: \u0003שליא שיצתה\u0004 מקצתה קודם שחיטה אסורה באכילה, שמא יצא באותו מקצת ראשו של העובר. \u0003אמר ר' אלעזר: לא שנו אלא שאין עמה ולד\u0004 שלם במעי הבהמה, \u0003אבל יש עמה ולד\u0004 שלם — \u0003אין חוששין לולד אחר\u0004 שהיה בשליה זו ויצא ראשו או רובו. \u0003ור' יוחנן אמר: בין אין עמה ולד, בין יש עמה ולד\u0004 — \u0003חוששין לולד אחר\u0004 שהיה בה, ויצא, ואסורה באכילה. ומכאן עולה שר' יוחנן הוא המחמיר ור' אלעזר מיקל.","ושואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' ירמיה\u0004 בקשר למחלוקת זו: \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003אמרה ר' אלעזר,\u0004 ור' יוחנן הוא המיקל!","\u0003אלא, אי אתמר הכי אתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 \u0003אמר ר' אלעזר: לא שנו\u0004 ששליה שיצאה מקצתה אסורה באכילה \u0003אלא\u0004 במקרה \u0003שאינה קשורה בולד\u0004 (שלם) שנמצא במעי הבהמה, \u0003אבל\u0004 אם \u0003קשורה בולד\u0004 — \u0003אין חוששין לולד אחר.\u0004","\u0003ור' יוחנן אמר: אנו אין לנו\u0004 לאסור \u0003אלא\u0004 ב\u0003שליא בלא ולד, אבל יש עמה ולד, בין קשורה בולד בין אין קשורה בולד\u0004 — \u0003אין חוששין לולד אחר. והיינו\u0004 \u0005[והוא]\u0006 ש\u0003אמר ר' ירמיה: לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003אמרה ר' אלעזר.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' אלעזר:\u0004 אשה \u0003המפלת\u0004 עובר הנראה כ\u0003מין בהמה חיה ועוף, ושליא עמהן, בזמן ש\u0004השליה \u0003קשורה בהן\u0004 — \u0003אין חוששין לולד אחר,\u0004 וכיון שעובר כזה אינו נחשב לוולד — אין האשה נחשבת יולדת, להביא עליו קרבן ולשבת בגללו ימי טומאה וימי טהרה. אבל אם השליה \u0003אינה קשורה בהן\u0004 — \u0003הריני מטיל עליה חומר שני ולדות,\u0004 שדנים אותה להחמיר כיולדת זכר וכיולדת נקבה,","\u0003שאני אומר: שמא נימוח שפיר\u0004 (עובר) \u0003של שליא\u0004 זו שנמצא שם, והיתה בו צורת אדם (ואין ידוע אם זכר או נקבה), ו\u0003שמא נימוחה שליתו של שפיר\u0004 זה שנמצא, שיש לו צורת בהמה, והשליה שנמצאה היא של עובר אחר בצורת אדם שהיה שם.","שנינו: \u0003המבכרת שהפילה\u0004 שליה — יכול להשליכה לכלבים, ואין חוששים שהיה שם זכר והוא בכור. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר רב איקא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי: רוב בהמות יולדות דבר הקדוש בבכורה\u0004 כלומר, ולד גמור, \u0003ומיעוט בהמות\u0004 יולדות \u0003דבר שאינו קדוש בבכורה, ומאי ניהו\u0004 \u0005[ומהו זה]?\u0006 \u0003נדמה,\u0004 שהוא דומה ליצור אחר ולא לאמו;","\u0003וכל היולדות\u0004 — \u0003יולדות מחצה זכרים ומחצה נקבות.\u0004 אם כן, \u0003סמוך מיעוטא\u0004 \u0005[צרף את המיעוט] ל\u0006של \u0003נדמה\u0004 שפטור מבכורה, \u0003למחצה\u0004 של \u0003נקבות, והוו להו\u0004 \u0005[ונמצאו]\u0006 ה\u0003זכרים מיעוטא\u0004 \u0005[מיעוט],\u0006 ולכן אין לחשוש שזו שליה של בכור. עוד שנינו:","\u0003ו\u0004שליה שנמצאה \u0003ב\u0004מעי בהמת \u0003מוקדשין\u0004 — \u0003תקבר,\u0004 מפני שהיא אסורה בהנאה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003רובא בר מיקדש\u0004 \u0005[רוב\u0006 הוולדות \u0005בן הקדשה]\u0006 \u0003הוא,\u0004 שהרי בניגוד לבכורה, בשאר קדשים גם ולד נקבה קדוש.","עוד שנינו בענין שליה, \u0003ואין קוברים אותה\u0004 בפרשת דרכים. ובענין זה, \u0003אביי ורבא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כל דבר שיש בו רפואה,\u0004 שאנשים עושים אותו כדי להתרפא — \u0003אין בו משום\u0004 איסור \u0003דרכי האמורי,\u0004 וכל דבר ש\u0003אין בו רפואה,\u0004 אלא עושים אותו כמין כישוף — \u0003יש בו משום דרכי האמורי.\u0004","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אילן שמשיר פירותיו,\u0004 שפירותיו נושרים — \u0003סוקרו\u0004 (צובעו) \u0003בסיקרא\u0004 בצבע אדום, \u0003וטוענו\u0004 (מעמיס אותו) \u0003באבנים! בשלמא\u0004 \u0005[נניח]\u0006 שמה ש\u0003טוענו באבנים\u0004 יש לזה טעם מסברה — \u0003כי היכי\u0004 \u0005[כדי]\u0006"],["\u0003דניכחוש חיליה\u0004 \u0005[שייחלש כוחו],\u0006 שמא מרוב שומן שבו הוא משיר פירותיו. \u0003אלא סוקרו בסיקרא, אמאי\u0004 \u0005[מדוע]?\u0006 ומשיבים: \u0003כי היכי דליחזיוה אינשי וליבעי רחמי עילויה\u0004 \u0005[כדי שיראו אותו בני האדם ויבקשו רחמים עליו].\u0006","\u0003כדתניא\u0004 \u0005[כמו ששנויה ברייתא]\u0006 על המצורע: \u0003\"וטמא טמא יקרא\"\u0004 (ויקרא יג, נה) — \u0003צריך להודיע לרבים\u0004 שהוא טמא, \u0003ורבים מבקשים עליו רחמים. וכן\u0004 כל \u0003מי שאירע בו דבר\u0004 של צרה \u0003צריך להודיע לרבים, ורבים מבקשים עליו רחמים.\u0004","\u0003אמר רבינא: כמאן תלינן כובסא בדיקלא\u0004 \u0005[כ\u0006דעת \u0005מי תולים אנו אשכול תמרים בדקל שמשיר פירותיו],\u0006 \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]?\u0006 \u0003כי האי תנא\u0004 \u0005[כדעת תנא זה]\u0006 שאומר שצריך להודיע לרבים, ורבים יבקשו עליו רחמים.","","איסור \u0003אותו ואת בנו נוהג בין בארץ בין בחוץ לארץ,\u0004 בין \u0003בפני הבית,\u0004 בזמן שהמקדש קיים, \u0003ו\u0004בין \u0003שלא בפני הבית, בחולין ובמוקדשין.\u0004","\u0003כיצד? השוחט אותו ואת בנו\u0004 באותו יום, והיו שניהם \u0003חולין,\u0004 ושחטם \u0003בחוץ,\u0004 מחוץ לעזרה — \u0003שניהם כשרים\u0004 לאכילה, \u0003ו\u0004על שחיטת \u0003השני סופג את הארבעים\u0004 מלקות, שעבר על \"אותו ואת בנו לא תשחטו ביום אחד\" (ויקרא כב, כח).","אם היו שניהם \u0003קדשים\u0004 ושחטם \u0003בחוץ\u0004 ביום אחד — על \u0003הראשון חייב כרת\u0004 משום שחיטת קדשים בחוץ. ועל השני אינו חייב משום שחיטת חוץ, שהרי אינו ראוי להקרבה בגלל איסור אותו ואת בנו. \u0003ושניהם פסולים\u0004 להקרבה. \u0003ו\u0004על שחיטת \u0003שניהם סופגים את הארבעים,\u0004 על הראשון — משום שחיטת חוץ, ועל השני — משום אותו ואת בנו.","אם היו שניהם \u0003חולין\u0004 ושחטם \u0003בפנים\u0004 העזרה — \u0003שניהם פסולין\u0004 להקרבה, כדין חולין שנשחטו בעזרה, \u0003ו\u0004על \u0003השני סופג את הארבעים\u0004 משום אותו ואת בנו. היו שניהם \u0003קדשים\u0004 ושחטום \u0003בפנים\u0004 ביום אחד — \u0003הראשון כשר\u0004 להקרבה \u0003ופטור\u0004 על שחיטתו, \u0003ו\u0004על \u0003השני\u0004 — \u0003סופג את הארבעים\u0004 משום אותו ואת בנו, \u0003ופסול,\u0004 להקרבה, משום שהוא מחוסר זמן עד שיעבור אותו יום. שחט \u0003חולין ו\u0004אחר כך \u0003קדשים בחוץ\u0004 ביום אחד — \u0003הראשון כשר\u0004 לאכילה, \u0003ופטור, ו\u0004על \u0003השני סופג את הארבעים\u0004 משום אותו ואת בנו, \u0003ופסול\u0004 להקרבה. שחט תחילה \u0003קדשים ו\u0004אחר כך \u0003חולין בחוץ\u0004 — על \u0003הראשון חייב כרת\u0004 משום שחיטת חוץ, \u0003ו\u0004הוא \u0003פסול\u0004 להקרבה, \u0003והשני כשר\u0004 לאכילה, \u0003ו\u0004על \u0003שניהם סופגים את הארבעים,\u0004 על הראשון — משום שחיטת קדשים בחוץ, ועל השני — משום אותו ואת בנו. שחט \u0003חולין ו\u0004אחר כך \u0003קדשים בפנים\u0004 — \u0003שניהם פסולין\u0004 להקרבה, הראשון — משום שהוא חולין, והשני — משום שהוא מחוסר זמן, \u0003ו\u0004על \u0003השני סופג את הארבעים\u0004 משום אותו ואת בנו. שחט \u0003קדשים ו\u0004אחר כך \u0003חולין בפנים\u0004 ביום אחד — \u0003הראשון כשר ופטור, ו\u0004על שחיטת \u0003השני סופג את הארבעים\u0004 משום אותו ואת בנו, \u0003ופסול\u0004 להקרבה, משום שהוא חולין. שחט \u0003חולין בחוץ ו\u0004אחר כך את השני \u0003בפנים\u0004 — \u0003הראשון כשר ופטור, ו\u0004על \u0003השני סופג את הארבעים\u0004 משום אותו ואת בנו, \u0003ופסול\u0004 מפני שהוא חולין. שחט \u0003קדשים בחוץ ו\u0004אחר כך \u0003בפנים\u0004 — על \u0003הראשון חייב כרת, ו\u0004על \u0003שניהם סופגים את הארבעים,\u0004 על הראשון — משום שחיטת חוץ, ועל השני — משום אותו ואת בנו, \u0003ושניהם פסולים\u0004 להקרבה, הראשון — מפני שנשחט בחוץ, והשני — מפני שהוא מחוסר זמן. שחט אותו ואת בנו \u0003חולין בפנים ו\u0004אחר כך את השני \u0003בחוץ\u0004 — \u0003הראשון פסול\u0004 להקרבה, שהרי הוא חולין, \u0003ופטור\u0004 עליו ממלקות, \u0003ו\u0004על \u0003השני סופג את הארבעים\u0004 משום אותו ואת בנו, \u0003וכשר.\u0004 שחט \u0003קדשים בפנים ו\u0004אחר כך \u0003בחוץ\u0004 — \u0003הראשון כשר ופטור, ו\u0004על \u0003השני סופג את הארבעים\u0004 משום אותו ואת בנו, \u0003ופסול,\u0004 שהרי הוא מחוסר זמן. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין ל\u0004איסור \u0003אותו ואת בנו שנוהג במוקדשין? תלמוד לומר: \"שור או כשב או עז כי יולד\u0004 וכו' ומיום השמיני והלאה ירצה לקרבן לה'\" (ויקרא כב, כז), \u0003וכתיב בתריה\u0004 \u0005[ונאמר\u0006 מיד \u0005אחריו]:\u0006 \u0003\"ושור או שה אותו ואת בנו לא תשחטו ביום אחד\"\u0004 (שם כח) — \u0003לימד על אותו ואת בנו שנוהג\u0004 גם \u0003במוקדשין.\u0004","","","","","","","","ושואלים: הואיל ונאמר איסור זה בענייני קדשים, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003במוקדשין\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 יש איסור אותו ואת בנו, \u0003בחולין\u0004 — כלל \u0003לא!\u0004 ומשיבים, מה שחזר הכתוב ואמר \u0003\"שור\u0004 או שה\", שלא הוצרך, שהרי בשור ושה עסק מתחילה — \u0003הפסיק הענין,\u0004 לומר שאין כתוב זה מדבר בקדשים שעסק בהם הכתוב תחילה. ושואלים: אם כן, שהפסיק הענין, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003בחולין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יש איסור אותו ואת בנו, \u0003במוקדשין\u0004 — \u0003לא!\u0004 ומשיבים: \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ושור\u0004 וכו' אותו ואת בנו\" — \u0003וי\"ו מוסיף\u0004 את מה שנאמר כאן גם \u0003על\u0004 ה\u0003ענין ראשון\u0004 שעסק בו הכתוב תחילה, כלומר, מוקדשים.","","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כך, שכתוב זה נאמר גם בענין קדשים, אמור: \u0003מה קדשים כלאים לא,\u0004 שוולד הנולד לכבשה מן התייש פסול לקרבן — \u0003אף\u0004 איסור שחיטת \u0003אותו ואת בנו\u0004 ב\u0003כלאים לא,\u0004 שאם שחט את הכבשה — מותר לשחוט ולד שנולד לה מן התיש! \u0003אלמה תניא\u0004 \u0005[\u0006ו\u0005מדוע שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אותו ואת בנו נוהג\u0004 בין \u0003בכלאים ו\u0004בין \u0003בכוי,\u0004 יצור שהוא ספק בהמה ספק חיה?","\u0003ועוד,\u0004 מדוע דין אותו ואת בנו נוהג בכלאיים? הרי \u0003\"שה\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003ואמר רבא:\u0004"],["\u0003זה בנה אב,\u0004 כלומר מן הכתוב \"שה כבשים ושה עזים\" (דברים יד, ד) למדנו בבנין אב: \u0003כל מקום\u0004 בתורה \u0003שנאמר \"שה\", אינו אלא להוציא את הכלאים!\u0004 ומשיבים, \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בענין אותו ואת בנו: \"שור או שה\" (ויקרא כב, כח), \u0003\"או\"\u0004 — \u0003לרבות את הכלאים.\u0004","ושואלים: והרי \u0003האי\u0004 \u0005[אותו]\u0006 \u0003\"או\" מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 כדי \u0003לחלק, דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]:\u0006 \u0003עד דשחיט\u0004 \u0005[ששוחט]\u0006 גם \u0003שור ובנו\u0004 וגם \u0003שה ובנו\u0004 ביום אחד \u0003לא מיחייב\u0004 \u0005[אינו חייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \"שור או שה\", שאם שחט או שור ובנו, או שה ובנו — חייב! ומשיבים: \u0003לחלק\u0004 ולחייב על כל אחד מהם, \u0003מ\u0004\"ואת \u0003בנו\" נפקא\u0004 \u0005[יוצא],\u0006 שלא נאמר \"ואת בניהם\".","ושואלים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין נצרך לו]\u0006 \"או\" לחלק, \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אילו נאמר\u0004 רק \u0003\"שור ושה ובנו\u0004 לא תשחטו ביום אחד\", \u0003הייתי אומר:\u0004 אינו חייב \u0003עד שישחוט שור ושה ובנו\u0004 של אחד מהם, לכך \u0003תלמוד לומר: \"שור או שה אותו ואת בנו\",\u0004 שחייב גם אם שחט רק אחד מהם ובנו; \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003מ\"או\" נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הלימוד הזה? ודוחים: \u0003לא, מ\"אותו\"\u0004 הוא נלמד, שאסור לשחוט אפילו אחד מהם ובנו, ומ\"או\" למדנו לרבות כלאיים.","ומקשים: \u0003הניחא לרבנן\u0004 \u0005[זה נוח ל\u0006שיטת \u0005חכמים]\u0006 שתובא להלן, \u0003דמייתר להו\u0004 \u0005[שמיותר להם]\u0006 \u0003\"אותו\"\u0004 לחלק, ומ\"או\" למדנו לרבות כלאיים. \u0003אלא ל\u0004שיטת \u0003חנניה, דלא מייתר ליה\u0004 \u0005[שלא מיותר לו]\u0006 \u0003\"אותו\", לחלק\u0004 ולחייב על כל אחד מהם, שור ובנו או שה ובנו, \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: לשיטתו, \u0003לחלק לא צריך קרא\u0004 \u0005[מקרא]\u0006 מיוחד, מפני \u0003דסבר לה\u0004 \u0005[שהוא סבור]\u0006 \u0003כ\u0004דעת ר' יונתן.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 לענין אחר: \u0003\"איש אשר יקלל את אביו ואת אמו\u0004 מות יומת\" (ויקרא כ, ט), \u0003אין לי\u0004 שחייב \u0003אלא\u0004 מי שקילל את \u0003אביו ו\u0004גם את \u0003אמו,\u0004 אבל אם קילל \u0003אביו שלא\u0004 (ולא) \u0003אמו,\u0004 או \u0003אמו שלא\u0004 \u0003אביו, מנין\u0004 שחייב? \u0003תלמוד לומר\u0004 בהמשך הפסוק: \u0003\"אביו ואמו קלל\u0004 דמיו בו\", לומר: \u0003אביו קלל\u0004 — חייב, \u0003אמו קלל\u0004 — חייב, אלו \u0003דברי ר' יאשיה.\u0004","\u0003ר' יונתן אומר:\u0004 לא הוצרכנו לכך, אלא בכל מקום שנאמר \"ואת\" \u0003משמע\u0004 גם \u0003שניהם כאחד, ומשמע\u0004 גם כל \u0003אחד בפני עצמו, עד שיפרוט לך הכתוב \"יחדו\",\u0004 לומר: דווקא שניהם יחד. ולשיטת ר' יונתן נמצא שלענין אותו ואת בנו, גם אם היה הכתוב אומר \"ושור ושה\" ולא \"שור או שה\", היינו למדים לחלק ולחייב על כל אחד מהם, ואם כן \"או\" מיותר לרבות את הכלאיים. וכשיטה זו הולך חנניה.","הזכרנו את שיטת חנניה וחכמים. ומבררים: \u0003מאי\u0004 \u0005[מהי]\u0006 שיטת \u0003חנניה ומאי רבנן\u0004 \u0005[ומהי\u0006 שיטת \u0005חכמים]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 איסור \u0003אותו ואת בנו נוהג בנקבות,\u0004 כלומר, באם ובנה, \u0003ואינו נוהג בזכרים,\u0004 שאין איסור לשחוט אב ובנו ביום אחד. \u0003חנניה אומר:\u0004 איסור אותו ואת בנו \u0003נוהג בין בזכרים ובין בנקבות.\u0004","ומסבירים: \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול יהא\u0004 איסור \u0003אותו ואת בנו נוהג בין בזכרים ובין בנקבות? ו\u0004לכאורה \u0003דין הוא,\u0004 אפשר ללמוד דבר זה מסברה, ממצוה דומה: \u0003חייב כאן\u0004 באותו ואת בנו, \u0003וחייב ב\u0004איסור לקיחת \u0003אם על הבנים,\u0004 כלומר, במצות שילוח הקן; \u0003מה כשחייב באם על הבנים\u0004 — חייב \u0003בנקבות ולא בזכרים,\u0004 שהרי נאמר \"והאם רובצת על האפרוחים\" (דברים כב, ו), \u0003אף כשחייב כאן,\u0004 באותו ואת בנו — הרי זה \u0003בנקבות ולא בזכרים.\u0004","אלא שיש לדחות: \u0003לא, אם אמרת באם על הבנים,\u0004 שהוא נוהג רק באם, מפני שהקל במצוה זו, \u0003שכן לא עשה בה מזומן כשאינו מזומן,\u0004 שאין חובה זו אלא כשהוא מוצא באקראי אם על הבנים, ולא בקן שבביתו — \u0003תאמר\u0004 כן \u0003באותו ואת בנו, ש\u0004החמיר בו יותר, ו\u0003עשה בו מזומן כשאינו מזומן?\u0004 ואם כן הדין נותן שינהג בזכרים ובנקבות!","על כן \u0003תלמוד לומר:\u0004 \"ושור או שה אותו ואת בנו\" (ויקרא כב, כח), והמלה \u0003\"אותו\"\u0004 שהיא מיותרת, באה לומר: ב\u0003אחד\u0004 מן ההורים מדובר, בזכר או בנקבה, \u0003ולא\u0004 ב\u0003שנים.\u0004 וממשיכה הברייתא: מעתה, \u0003אחר שחלק הכתוב\u0004 בדין אותו ואת בנו, והבהיר כי דווקא באחד מדובר, בזכרים או בנקבות — \u0003זכיתי\u0004 לחזור ו\u0003לדין\u0004 (לדון) כפי שהייתי סבור מתחילה: \u0003חייב כאן וחייב באם על הבנים, מה כשחייב באם על הבנים\u0004 — \u0003בנקבות ולא בזכרים, אף כשחייב כאן\u0004 — \u0003בנקבות ולא בזכרים.\u0004","\u0003ואם נפשך\u0004 (רצונך) \u0003לומר\u0004 ולטעון טענה כנגד זה — על כך יש להשיב: נאמר \"אותו ואת \u0003בנו\"\u0004 — \u0003מי שבנו כרוך אחריו, יצא זכר שאין בנו כרוך אחריו.\u0004","ושואלים: \u0003מה\u0004 כוונת \u0003\"אם נפשך לומר\"?\u0004 מה אפשר היה לומר כדי לסתור את הדברים? ומסבירים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003\"אותו\"\u0004 לשון \u0003זכר משמע,\u0004 על כך יש להשיב: \u0003הרי הוא אומר \"בנו\"\u0004 — לומר \u0003מי שבנו כרוך אחריו, יצא זכר שאין בנו כרוך אחריו.\u0004"],["\u0003ו\u0004מן הצד השני, \u0003ל\u0004שיטת \u0003חנניה,\u0004 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אותו\"\u0004 ש\u0003משמע זכר, וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"בנו\"\u0004 — \u0003מי שבנו כרוך אחריו,\u0004 ש\u0003משמע נקבה, הלכך\u0004 \u0005[על כן]\u0006 \u0003נוהג\u0004 איסור זה \u0003בין בזכרים בין בנקבות.\u0004","ובפסיקת ההלכה במחלוקת זו, \u0003אמר רב הונא בר חייא אמר שמואל: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כחנניה,\u0004 שאיסור אותו ואת בנו נוהג בין בזכרים ובין בנקבות. ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005]:\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 במסכת כלאיים, \u0003ר' יהודה אומר:\u0004 כל \u0003הנולדים מן\u0004 נקבת \u0003הסוס, אף על פי שאביהן\u0004 של אחד מהם \u0003חמור,\u0004 ושל האחר סוס — \u0003מותרין זה בזה\u0004 בהרבעה, שכיון ששניהם בני סוסה — הריהם נחשבים בני אותו מין. \u0003אבל הנולדין מן\u0004 נקבת \u0003החמור עם הנולדין מן\u0004 נקבת \u0003הסוס,\u0004 גם אם אביו של זה ושל זה חמור או סוס — \u0003אסורין\u0004 בהרבעה זה בזה משום כלאיים.","\u0003ואמר רב יהודה אמר שמואל: זו דברי ר' יהודה,\u0004 ש\u0003אמר אין חוששין לזרע האב\u0004 בקביעת זהות הוולד, אלא הוולד מתייחס רק לאמו, \u0003אבל חכמים אומרים:\u0004 זהות הוולד נקבעת גם לפי האם וגם לפי האב, ולכן \u0003כל מיני פרדות,\u0004 כל תערובת של סוס וחמור — \u0003אחת הן,\u0004 נחשבים למין אחד, ומותרים בהרבעה זה בזה.","והרי \u0003מאן\u0004 \u0005[מי הוא]\u0006 הקרוי כאן \u0003חכמים? חנניה הוא,\u0004 ש\u0003אמר חוששין לזרע האב,\u0004 שהרי לדעתו חל איסור אותו ואת בנו גם על הזכר ובנו. \u0003ו\u0004אם כן, גם לענין כלאיים, \u0003האי בר סוסיא וחמרא\u0004 \u0005[זה\u0006 הפרד \u0005בן הסוסה והחמור],\u0006 \u0003והאי בר חמרא וסוסיא\u0004 \u0005[וזה\u0006 הפרד \u0005בן החמורה והסוס]\u0006 — \u0003כולהו חדא מינא נינהו\u0004 \u0005[כולם מין אחד הם].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003מי פשיט ליה\u0004 \u0005[האם פשוט לו]\u0006 \u0003לר' יהודה\u0004 ש\u0003אין חוששין לזרע האב,\u0004 ואין מתחשבים בו כלל בהגדרת הוולד, \u0003או דלמא ספוקי מספקא ליה\u0004 \u0005[שמא מסופק בעיניו\u0006 הדבר\u0005]?\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא\u0006 מכאן משאלה \u0005זו]\u0006 להלכה?","ומשיבים: \u0003למישרא\u0004 \u0005[להתיר]\u0006 \u0003פרי\u0004 (ולד הסוס והחמור) בהרבעה \u0003עם\u0004 מין \u0003האם,\u0004 כגון להתיר הרבעה של פרד בן סוסה וחמור, עם סוסה. \u0003אי אמרת\u0004 \u0005[אם אתה אומר]:\u0006 \u0003מיפשט פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 שאין חוששים כלל לזרע האב, אם כן \u0003פרי עם האם שרי\u0004 \u0005[מותר],\u0006 שהרי שניהם מין סוס בלבד, \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]:\u0006 \u0003ספוקי מספקא ליה\u0004 \u0005[מסופק לו],\u0006 הרי גם \u0003פרי עם האם\u0004 כגון פרד בן חמור וסוסה, עם סוסה — \u0003אסור\u0004 בהרבעה, שמא יש לחשוש לזרע האב שבו, שהוא חמור.","ואם כן, \u0003מאי\u0004 \u0005[מה]\u0006 התשובה לכך? ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו לעיל, \u0003ר' יהודה אומר: כל הנולדים מן\u0004 נקבת \u0003הסוס, אף על פי שאביהן חמור\u0004 — \u0003מותרין זה בזה.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר],\u0006 \u0003אילימא דאבוה דהאי\u0004 \u0005[אם תאמר\u0006 שמדובר בפרד ופרדה, \u0005שאביו של זה]\u0006 הוא \u0003חמור\u0004 ואמו סוסה, \u0003ואבוה דהאי\u0004 \u0005[ו\u0006גם \u0005אביו של זה,\u0006 של הנקבה\u0005]\u0006 \u0003חמור\u0004 ואמה סוסה, \u0003צריכא למימר\u0004 \u0005[צריך\u0006 הדבר \u0005להיאמר]\u0006 שהם מותרים זה בזה? והרי מדובר באותו מין בעל חיים! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דאבוה דהאי\u0004 \u0005[שאביו של זה]\u0006 \u0003סוס\u0004 ואמו סוסה, \u0003ואבוה דהאי\u0004 \u0005[ואביו של זה,\u0006 של הנקבה\u0005]\u0006 \u0003חמור\u0004 ואמה סוסה?","\u0003וקתני\u0004 \u0005[והוא שונה]\u0006 שהם \u0003מותרים זה עם זה. אלמא מיפשט פשיטא ליה\u0004 \u0005[מכאן שפשוט לו]\u0006 שאין חוששים כלל לזרע האב, שאם היה לו ספק אם חוששים לזרע האב — צריך היה לאסור, שהרי אביו של זה סוס ושל זו חמור!","ומשיבים: \u0003לא,\u0004 אין מכאן ראיה, \u0003לעולם\u0004 תפרש שמדובר \u0003דאבוה דהאי\u0004 \u0005[שאביו של זה]\u0006 \u0003חמור, ואבוה דהאי\u0004 \u0005[ואביו של זה,\u0006 הנקבה\u0005]\u0006 גם כן \u0003חמור. ודקאמרת, צריכא למימר\u0004 \u0005[ומה שאמרת, וכי צריך הדבר להיאמר]\u0006 שהם מותרים? על כך יש להשיב, כי יש בכך חידוש, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 הרי בכל אחד מהם יש צד סוס מצד האם, וצד חמור מצד האב, ואם כן נאמר: \u0003אתי\u0004 \u0005[בא]\u0006 \u0003צד\u0004 ה\u0003סוס\u0004 שבזכר ו\u0003משתמש\u0004 (רובע) \u0003בצד\u0004 ה\u0003חמור\u0004 שבנקבה, \u0003וצד\u0004 ה\u0003חמור\u0004 שבזכר \u0003משתמש\u0004 (רובע) \u0003בצד\u0004 ה\u0003סוס\u0004 שבנקבה, ויש פה לכאורה הרבעת כלאיים, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ר' יהודה שאין אומרים כן, אלא כולם מין אחד הם.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו בברייתא, \u0003ר' יהודה אומר: פרדה שתבעה\u0004 זכר — \u0003אין מרביעין עליה לא סוס ולא חמור, אלא מינה,\u0004 כלומר, פרד. \u0003ואי אמרת מפשט פשיטא ליה\u0004 \u0005[ואם אתה אומר שפשוט לו]\u0006 לר' יהודה שאין חוששים לזרע האב, אלא רק לאם — \u0003לרבע עלה מינא דאמה\u0004 \u0005[שירביע עליה את מין אמה],\u0006 שאם היתה אמה סוסה — ירביע עליה סוס, ואם היתה אמה חמורה — ירביע עליה חמור! אלא מכאן שלדעתו יש לחשוש מספק לזרע האב, ולכן אם היה אביה חמור ואמה סוסה — אינו יכול להרביע עליה סוס, בגלל זרע החמור שיש בה. ודוחים: יש לומר שמדובר במקרה \u0003דלא ידעינן מינא דאמה מאי ניהו\u0004 \u0005[שאין אנו יודעים מין אמה מהו].\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 בלשון \"אין מרביעין עליה \u0003אלא מינה\" קתני\u0004 \u0005[הוא שונה],\u0006 משמע שאנו יודעים מהו מינה! ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אומר]:\u0006 \u0003אין מרביעין עליה לא מין סוס ולא מין חמור, לפי ש\u0004סתם פרדה שלפנינו \u0003אין\u0004 אנו \u0003יודעין במינה\u0004 של אמה. ושואלים: וכיצד ייתכן הדבר? \u0003וליבדוק\u0004 \u0005[ושיבדוק]\u0006 \u0003בסימנין\u0004 שיש בגופה, ש\u0003אמר אביי: עבי קליה\u0004 \u0005[\u0006פרד \u0005שעבה קולו]\u0006 — \u0003בר חמרא\u0004 \u0005[בן חמורה]\u0006 הוא, \u0003צניף קליה\u0004 \u0005[דק קולו]\u0006 — \u0003בר סוסיא\u0004 \u0005[בן סוסה]\u0006 הוא. \u0003ו\u0004כן \u0003אמר רב פפא: רברבן אודניה וזוטרא גנובתיה\u0004 \u0005[גדולות אוזניו וקטן זנבו]\u0006 — \u0003בר חמרא\u0004 \u0005[בן חמורה]\u0006 הוא, \u0003זוטרן אודניה ורבה גנובתיה\u0004 \u0005[קטנות אוזניו וגדול זנבו]\u0006 — \u0003בר סוסיא\u0004 \u0005[בן סוסה]\u0006 הוא! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003ב\u0004פרדה שהיא \u0003אלמת,\u0004 שאין לה קול, \u0003ו\u0004היא \u0003גידמת,\u0004 שאזניה וזנבה קצוצים. ואין להוכיח מכאן את שיטתו של ר' יהודה.","ושואלים: בסופו של דבר \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]?\u0006 כיצד נפתרה השאלה ביחס לשיטת ר' יהודה? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 בענין הרבעה של פרד, \u0003הכל,\u0004 ובכללם ר' יהודה, \u0003מודין\u0004 \u0003ב\u0004הרבעת \u0003פרי עם האם,\u0004 כגון פרד בן חמור וסוסה, עם סוסה — \u0003שאסור; שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003ספוקי מספקא ליה\u0004 \u0005[\u0006ש\u0005מסופק לו]\u0006 לר' יהודה האם חוששים לזרע האב. שאם ודאי לו שאין חוששים לזרע האב — מותר היה הפרד במין אמו, שהרי אין חשיבות למין האב. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ובענין זה מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003אי מעיילת לי כודנייתא בריספק\u0004 \u0005[אם אתה מכניס לי פרדות בעגלה],\u0006 \u0003עיין להנך דדמיין להדדי, ועייל לי\u0004 \u0005[בדוק את אלה שדומות זו לזו\u0006 בקולותיהן, וכן בגודל האזנים והזנב שלהן, \u0005והכנס לי],\u0006 שלא אהיה נוהג בכלאיים. \u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]:\u0006 \u0003אין חוששין לזרע האב,\u0004 שהרי כפי שנאמר לעיל, הסימנים הללו מורים על מין האם."],["\u0003וסימנין\u0004 כמו אלו שאמרנו, של קול הבהמה, וכן גודל האזניים והזנב, הם \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 שאפשר לסמוך עליהם לגמרי, עד כדי להתיר חשש איסור.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 איסור \u0003אותו ואת בנו נוהג בכלאים\u0004 של שני מיני בהמה, כגון של עז (תיש) ורחל. \u0003ו\u0004גם \u0003בכוי,\u0004 הבא מן העז ומן הצבי, למרות שאותו ואת בנו אינו נוהג בצבי, שהוא חיה. \u0003ר' אליעזר אומר: כלאים הבא מן העז ומן הרחל\u0004 — \u0003אותו ואת בנו נוהג בו,\u0004 ואילו \u0003כוי\u0004 — \u0003אין אותו ואת בנו נוהג בו. אמר רב חסדא: איזהו כוי שנחלקו בו ר' אליעזר וחכמים? זה הבא מן התייש ומן הצבייה.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 מדובר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בתייש הבא על הצבייה, וילדה, וקא שחיט לה ולברה\u0004 \u0005[והוא שוחט אותה ואת בנה];\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא: הכל מודים בהיא צבייה ובנה תייש\u0004 (שאביו תייש), שאם שחטם ביום אחד — \u0003שפטור\u0004 ממלקות, ומדוע? \u0003שה ובנו,\u0004 כלומר, בהמה ובנה \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שאסור לשחוט ביום אחד, שנאמר \"ושור או שה אותו ואת בנו לא תשחטו ביום אחד\" (ויקרא כב, כח), \u0003ולא\u0004 חיה ובנה, כגון \u0003צבי ובנו\u0004 (צביה ובנה)!","\u0003אלא\u0004 תאמר שמדובר \u0003בצבי הבא על התיישה\u0004 (העז) \u0003וילדה, וקא שחיט לה ולברה\u0004 \u0005[והוא שוחט אותה ואת בנה],\u0006 ובכך נחלקו; \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא: הכל מודים בהיא תיישה ובנה צבי\u0004 (שאביו צבי) \u0003—\u0004 \u0003שחייב,\u0004 שהרי \u0003\"שה\u0004 אותו ואת בנו\" \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שאסור לשחוט, והכוונה שהוא שה, כלומר, בהמה, \u0003ובנו\u0004 — \u0003כל דהו\u0004 \u0005[כל שהוא],\u0006 ואפילו אינו שה!","ומשיבים: \u0003לעולם\u0004 מדובר \u0003בתייש הבא על הצבייה, וילדה בת, ובת\u0004 זו, שהיא כלאיים, \u0003ילדה בן, וקא שחיט לה ולברה\u0004 \u0005[והוא שוחט אותה ואת בנה].\u0006","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003חוששין לזרע האב,\u0004 מתחשבים בו בהגדרת הוולד, ואם כן יש באם (בת התיש והצביה) גם צד בהמה (\"שה\"). \u0003ו\u0004לשיטתם מה שנאמר \u0003\"שה\"\u0004 שאסור לשחוט אותו ואת בנו ביום אחד, כוונתו — \u0003ואפילו\u0004 יש בו \u0003מקצת שה,\u0004 ולכן אסור לשחוט אותה ואת בנה. \u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003אין חוששין\u0004 כלל \u0003לזרע האב\u0004 שיש באם, \u0003ו\u0004ממילא, לומר: \u0003\"שה\" ואפילו מקצת שה\u0004— \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 אינו שייך כאן, באם שנולדה מתיש וצביה, שהרי אין מתחשבים כלל באב.","ושואלים: אם כן, מדוע נחלקו דווקא במקרה זה? \u0003וליפלוג\u0004 \u0005[ושיחלקו]\u0006 \u0003ב\u0004שאלה העקרונית האם \u0003חוששין לזרע האב, בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003חנניה ורבנן\u0004 \u0005[וחכמים],\u0006 האם יש איסור אותו ואת בנו גם באב ובנו, מפני שחוששים לזרע האב, או אין חוששים לזרע האב, ויש איסור רק באם ובנה!","ומשיבים: \u0003אי פליגי\u0004 \u0005[אם היו חולקים רק]\u0006 \u0003ב\u0004שאלה \u0003ההיא,\u0004 האם חוששים לזרע האב, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003בהא\u0004 \u0005[ב\u0006מקרה \u0005זה],\u0006 שאמה צביה ואביה תיש (\"שה\") — \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שאין הולכים אחרי האב, מפני שהם סבורים ש\u0003\"שה\" ואפילו מקצת שה\u0004— \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלדעת חכמים לא רק שחוששים לזרע האב, אלא גם אומרים: שה — ואפילו מקצת שה.","ושואלים: \u0003ו\u0004אלא, \u0003הא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כוי\u0004 — לכתחילה \u0003אין שוחטין אותו ביום טוב,\u0004 מספק שמא מין חיה הוא וצריך לכסות את דמו בעפר, \u0003ואם\u0004 עברו ו\u0003שחטו\u0004 כוי — \u0003אין מכסין את דמו,\u0004 מפני שחכמים אסרו לטלטל עפר ביום טוב, אם לא לצורך מצוה ודאית שמן התורה.","ויש לשאול: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה מקרה \u0005עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בתייש הבא על הצבייה וילדה,\u0004 הלוא \u0003בין ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003בין ל\u0004דעת \u0003ר' אליעזר\u0004 — \u0003לשחוט וליכסי\u0004 \u0005[שישחט ויכסה את הדם],\u0006 שהרי מצד אמו הוא חיה, ויש לומר בענין זה: \u0003צבי\u0004 — \u0003ואפילו מקצת צבי,\u0004 שהרי אין מי שחולק שמייחסים את הוולד לאם!","\u0003אלא\u0004 תאמר שמשנה זו עוסקת \u0003בצבי הבא על התיישה וילדה\u0004 — גם באופן זה לא ניתן להסביר את המשנה, שהרי \u0003אי לרבנן\u0004 \u0005[אם ל\u0006דעת \u0005חכמים]\u0006 האומרים שחוששים לזרע האב, מדוע לא ישחט אותו ביום טוב? \u0003לשחוט וליכסי\u0004 \u0005[שישחט\u0006 לכתחילה \u0005ויכסה],\u0006 שהרי מקצת חיה הוא מצד אביו; \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר,\u0004 הסבור שאין חוששים כלל לזרע האב — \u0003לשחוט ולא ליכסי\u0004 \u0005[שישחוט\u0006 לכתחילה \u0005ולא יכסה],\u0006 שהרי מין בהמה הוא, ואין דמו צריך כיסוי!","ומשיבים: \u0003לעולם\u0004 מדובר \u0003בצבי הבא על התיישה,\u0004 ומשנה זו כשיטת חכמים היא. \u0003ורבנן\u0004 \u0005[חכמים]\u0006 אינם אומרים בוודאות שחוששים לזרע האב, אלא \u0003ספוקי מספקא להו\u0004 \u0005[מסופק להם]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003חוששין לזרע האב אי\u0004 \u0005[או]\u0006 \u0003אין חוששין,\u0004 ולכן לכתחילה לא ישחוט, כדי שלא להיכנס לספק איסור, ואם שחט — לא יכסה את דמו, שאין מחללים יום טוב בספק מצוה.","ואומרים: \u0003ומדלרבנן מספקא להו\u0004 \u0005[ומכיון ש\u0006לדעת \u0005חכמים מסופק להם]\u0006 אם חוששים לזרע האב, ומחמת כן הם סבורים שאותו ואת בנו נוהג בכוי, נמצא ש\u0003לר' אליעזר\u0004 הפוטר — \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 שבכוי כזה, הבא מצבי הבא על התיישה — אין לחשוש לזרע האב.","ומקשים: \u0003ו\u0004אלא מעתה, \u0003הא דתניא\u0004 \u0005[זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003הזרוע והלחיים והקבה,\u0004 שמצוה לתת לכהן מכל בהמת חולין, \u0003נוהגים\u0004 גם \u0003בכוי ו\u0004גם \u0003בכלאים. ר' אליעזר אומר: כלאים הבא מן העז ומן הרחל\u0004 — \u0003חייב במתנות, מן הכוי\u0004 — \u0003פטור מן המתנות.\u0004","ויש לשאול: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 באיזה כוי? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בתייש הבא על הצבייה וילדה, בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר\u0004 ש\u0003פטר\u0004 אותו מן המתנות — \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003\"שה\" ואפילו מקצת שה לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 שהרי אין חוששים לזרע האב, ואין כאן אלא בן של צביה שפטור מן המתנות.","\u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים],\u0006 \u0003נהי דקסברי\u0004 \u0005[גם אם אמנם הם סבורים]\u0006 \u0003שה ואפילו מקצת שה\u0004מחייב במתנות, מדוע צריך לתת הבעלים את המתנות לכהן? שכן \u0003בשלמא\u0004 \u0005[פשוט הדבר]\u0006 ש\u0003פלגא לא יהיב ליה\u0004 \u0005[חצי\u0006 מן המתנות \u0005לא נותן לו],\u0006 שהרי בחציו שמצד אמו הוא חיה שאינה חייבת במתנות, ואולם גם את \u0003אידך פלגא\u0004 \u0005[החצי האחר]\u0006 מדוע חייב לתת לכהן? \u0003לימא ליה\u0004 \u0005[יאמר לו\u0006 לכהן\u0005]:\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראייה\u0004 ש\u0003חוששין לזרע האב, ושקול\u0004 \u0005[וטול]!\u0006","\u0003אלא\u0004 תאמר שמדובר כאן \u0003בצבי הבא על התיישה וילדה; בשלמא לרבנן\u0004 \u0005[נניח לדעת חכמים]\u0006 שאמרו שזרוע לחיים וקיבה נוהגים בו, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003חייב\u0004 — \u0003בחצי מתנות,\u0004 שמצד אמו הוא בוודאי חייב במתנות, ועל הצד השני הוא אומר לכהן: הבא ראיה שאין חוששים לזרע האב, וטול. \u0003אלא ל\u0004דעת \u0003ר' אליעזר,\u0004 הסבור שאין חוששים כלל לזרע האב, נמצא שהוא מתייחס רק לאמו התיישה, ואם כן \u0003ליחייב בכולהי\u0004 \u0005[שיתחייב בכל]\u0006 ה\u0003מתנות,\u0004 ומדוע הוא פוטרו?","ומשיבים: \u0003לעולם\u0004 מדובר \u0003בצבי הבא על התיישה וילדה, ו\u0004צריכים לומר ש\u0003ר' אליעזר נמי ספוקי מספקא ליה\u0004 \u0005[גם כן מסופק לו]\u0006 \u0003אי\u0004 \u0005[האם]\u0006 \u0003חוששין לזרע האב או לא.\u0004 ושואלים: \u0003וכיון דלרבנן מספקא להו\u0004 \u0005[שלחכמים מסופק הדבר],\u0006 \u0003ול\u0004דעת \u0003ר' אליעזר מספקא ליה\u0004 \u0005[\u0006גם כן \u0005מסופק לו],\u0006 \u0003במאי פליגי\u0004 \u0005[במה הם חולקים]?\u0006 מדוע פוטר ר' אליעזר לגמרי מן המתנות?"],["\u0003ב\u0004שאלה האם אומרים: \u0003\"שה\"\u0004 שאמר הכתוב, כוונתו — \u0003ואפילו מקצת שה. רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003\"שה\"\u0004 — \u0003ואפילו מקצת שה, ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003\"שה\"\u0004 כוונתו שה גמור, \u0003ולא מקצת שה.\u0004 \u0003אמר רב\u0004","\u0003פפא: הלכך\u0004 \u0005[על כן],\u0006 לדרך זו, שגם לדעת חכמים וגם לדעת ר' אליעזר, ספק אם חוששים לזרע האב או לא, אלא שנחלקו האם אומרים \"שה\" ואפילו מקצת שה, יש לפרש את המקורות השונים שהובאו לעיל בענין כוי באופן זה: \u0003לענין כסוי הדם,\u0004 שעולה מן המשנה שדמו של הכוי טעון כיסוי מצד הספק, \u0003ו\u0004לענין \u0003מתנות,\u0004 שחכמים מחייבים את הכוי בזרוע לחיים וקיבה כדין בהמה, ור' אליעזר פוטר — \u0003לא משכחת\u0004 \u0005[אין אתה מוצא],\u0006 אין אתה יכול להעמידם \u0003אלא ב\u0004כוי הנולד מ\u0003צבי הבא על התיישה.\u0004","ש\u0003בין ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ובין ל\u0004דעת \u0003ר' אליעזר, מספקא להו\u0004 \u0005[מסופק להם]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003חוששין לזרע האב,\u0004 והריהו נחשב מקצת חיה, \u0003או לא,\u0004 אלא הוא נחשב בהמה גמורה.","\u0003וקא מיפלגי\u0004 \u0005[והם חלוקים]\u0006 \u0003ב\u0004שאלה האם אומרים \u0003\"שה\" ואפילו מקצת שה.\u0004 ולכן, המשנה המחייבת כיסוי של דם הכוי מספק הולכת במקרה זה רק לשיטת חכמים, הסבורים ש\"שה\" ואפילו מקצת שה (ובהקשר זה, צבי — ואפילו מקצת צבי), ושמא דמו חייב בכיסוי מצד הצבי שבו. אבל ר' אליעזר פוטר, משום שלשיטתו רק צבי גמור חייב בכיסוי הדם, ואין אומרים צבי ואפילו מקצת צבי. ולענין מתנות — חכמים מחייבים בן צבי ותיישה במחצית המתנות, משום שיש כאן מקצת שה, ור' אליעזר פוטר, משום שלדעתו אין אומרים: \"שה\" — ואפילו מקצת שה, ורק בהמה גמורה חייבת במתנות.","\u0003לענין\u0004 איסור \u0003אותו ואת בנו,\u0004 שנחלקו ר' אליעזר וחכמים האם הוא נוהג בכוי, \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 את המחלוקת \u0003בין בתייש הבא על הצבייה\u0004 וילדה בת, \u0003ובין בצבי הבא על התיישה\u0004 וילדה בת.","ומפרטים: \u0003בתייש הבא על הצבייה\u0004 וילדה בת — \u0003ולאיסורא\u0004 \u0005[ולענין איסור]\u0006 לכתחילה, האם מותר לשחוט אותה בת ואת בנה ביום אחד. \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003חוששין לזרע האב,\u0004 והאם היא מקצת שה, ולשיטתם הרי \u0003שה ואפילו מקצת שה אמרינן\u0004 \u0005[אומרים אנו],\u0006 \u0003ו\u0004לכן \u0003אסור\u0004 לשחוט אותה ואת בנה ביום אחד, אלא שאינו לוקה משום הספק.","\u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003נהי נמי\u0004 \u0005[גם אם אמנם]\u0006 \u0003חוששין לזרע האב,\u0004 ויש באם מקצת שה, הרי \u0003שה ואפילו מקצת שה לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 ואם כן מותר לשחוט אותה ואת בנה ביום אחד.","וכן חולקים ר' אליעזר וחכמים \u0003בצבי הבא על התיישה,\u0004 וילדה בת, ושחט אותה ואת בנה ביום אחד, \u0003ול\u0004ענין \u0003מלקות.\u0004 \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003נהי נמי\u0004 \u0005[גם אם אמנם]\u0006 נאמר ש\u0003חוששין לזרע האב,\u0004 ואם זו היא במקצתה צבי, הרי במקצתה היא שה, ולשיטתם \u0003\"שה\" ואפילו מקצת שה אמרינן\u0004 \u0005[אומרים אנו],\u0006 \u0003ו\u0004לכן \u0003מלקינן ליה\u0004 \u0005[מלקים אותו],\u0006 שעבר על איסור ודאי. \u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003איסורא איכא\u0004 \u0005[איסור יש]\u0006 בבת הצבי והתיישה, לשחוט אותה ואת בנה ביום אחד, אבל אם עשה כן — \u0003מלקות ליכא\u0004 \u0005[אין כאן].\u0006","ומסבירים: \u0003איסורא איכא\u0004 \u0005[איסור יש כאן]\u0006 — \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003אין חוששין\u0004 כלל \u0003לזרע האב, והאי\u0004 \u0005[וזה],\u0006 האם \u0005—\u0006 \u0003שה מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 כאמה. אבל \u0003מלקות ליכא\u0004 \u0005[אין כאן],\u0006 מספק \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003חוששין לזרע האב,\u0004 והאם חציה צבי וחציה שה,","\u0003ו\u0004לשיטתו \u0003\"שה\" ואפילו מקצת שה לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006 ואם כן אינו לוקה, שאין לוקים אלא בהתראה ודאית, וכאן אם התרו בו, התראת ספק היא.","עד כאן דנה הגמרא בעניינו של הכוי, מתוך הנחה שהוא הכלאה של צבי ועז. וכאן מובאות דעות נוספות בעניינו. \u0003אמר רב יהודה: כוי\u0004 — \u0003בריה בפני עצמה היא, ולא הכריעו בה חכמים אם מין בהמה היא אם מין חיה היא. רב נחמן אמר: כוי\u0004 — \u0003זה איל הבר.\u0004","ומעירים: מחלוקת זו היא \u0003כתנאי\u0004 \u0005[כמחלוקת תנאים]\u0006 ששנינו בברייתא: \u0003כוי\u0004 — \u0003זה איל הבר. ויש אומרים: זה\u0004 יצור כלאיים \u0003הבא מן התייש ומן הצבייה. ר' יוסי אומר: כוי בריה בפני עצמה היא, ולא הכריעו בה חכמים אם מין חיה אם מין בהמה. רבן שמעון בן גמליאל אומר: מין בהמה היא, ו\u0004אנשיהם \u0003של בית דושאי היו מגדלין מהן עדרים עדרים\u0004 כשאר בהמות.","מתוך שהוזכר איל הבר, מביאים מה ש\u0003אמר ר' זירא אמר רב ספרא אמר רב המנונא: הני עזי דבאלא\u0004 \u0005[אותן עיזים של יער,\u0006 עזי בר\u0005]\u0006 \u0003כשרות לגבי מזבח,\u0004 שהן נחשבות בהמות, כאחד ממיני העיזים. ומעירים: \u0003סבר לה כי הא\u0004 \u0005[סבור הוא כמו זו]\u0006 ש\u0003אמר ר' יצחק: עשר בהמות\u0004 טהורות \u0003מנה הכתוב,\u0004 שנאמר: \"זאת הבהמה אשר תאכלו, שור, שה כשבים, שה עזים, איל, צבי, יחמור, אקו, דישון, תאו, זמר\" (דברים יד, ד— ה). שלוש מהן הן בהמות — שור, כשבים, עיזים, ושבע מהן חיות \u0003ותו לא\u0004 \u0005[ולא יותר].\u0006","\u0003והני\u0004 \u0005[ואלו],\u0006 עיזי היער, \u0003מדלא קחשיב להו בהדי\u0004 \u0005[מתוך שלא מנה אותן בתוך]\u0006 ה\u0003חיות\u0004 כמין בפני עצמו — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמין \u0003עז נינהו\u0004 \u0005[הן],\u0006 שהרי הן קרויות עז ודומות לה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בר יעקב:\u0004 ושמא מין אחר של חיה הן, שלא נתפרש בכתוב. שהרי לאחר רשימת הבהמות והחיות נאמר: \"וכל בהמה מפרסת פרסה\" וכו', \u0003ואימא\u0004 \u0005[ואמור],\u0006 דרוש כך את הכתוב: \u0003\"איל וצבי\u0004 ויחמור\" וכו' — הרי כל אחד מהם הוא \u0003פרט, \"כל בהמה\"\u0004 — \u0003כלל,\u0004 ולפי כללי מדרש ההלכה, במקום שיש","\u0003פרט ו\u0004אחריו \u0003כלל\u0004 — \u0003נעשה כלל מוסף\u0004 (מוסיף) \u0003על הפרט,\u0004 ואם כן \u0003איכא טובא\u0004 \u0005[יש יותר]\u0006 מיני חיות טהורות מאלו שפירט הכתוב, ועיזי היער אחד מהם!","ודוחים: \u0003אם כן,\u0004 שיש כאן פרט וכלל, \u0003כל הני פרטי\u0004 \u0005[כל אותם הפרטים],\u0006 כל מיני החיות שמנה הכתוב בפירוט, \u0003למה לי?\u0004 די שיזכיר אחד מהם! אלא ודאי רק אלו הם המינים הכשרים. ואם כן, בהכרח צריך אתה לומר שעיזי היער — מין עז הן. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 גם אם נניח שעיזי היער אינן מין חיה לעצמו, מדוע נאמר שמין עז הן? \u0003ודלמא מינא\u0004 \u0005[ושמא מין]\u0006 \u0003אקו\u0004 אחד ממיני החיות שפירש הכתוב \u0003נינהו\u0004 \u0005[הם]!\u0006","וכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי: דלמא מינא\u0004 \u0005[שמא מין]\u0006 \u0003תאו, או מינא\u0004 \u0005[מין]\u0006 \u0003זמר נינהו\u0004 \u0005[הם],\u0006 שמנה הכתוב בין החיות! ואכן בניגוד למה שנאמר בשם רב המנונא, שעיזי היער מין בהמה הן, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנן לרב אשי: אמימר שרי תרבייהו\u0004 \u0005[התיר את חלבן]\u0006 של עיזי היער, שהוא סבור בוודאות שהם מין חיה, שחלבה מותר.","ועוד בענין זה מסופר, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מנימין בר חייא מרב הונא בר חייא: הני עזי דבאלא\u0004 \u0005[אותם עזי היער],\u0006 \u0003מהו\u0004 דינן \u0003לגבי מזבח? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003ר' יוסי ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003אלא בשור הבר,\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 במסכת כלאיים: \u0003שור הבר מין בהמה הוא, ר' יוסי אומר: מין חיה. דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003מדמתרגמינן\u0004 \u0005[מתוך שמתרגמים אנו]\u0006 \"תאו\" שבכתוב — \u0003תורבלא\u0004 \u0005[שור יער],\u0006 אם כן \u0003מינא\u0004 \u0005[מין]\u0006 של \u0003בהמה הוא,\u0004 אחד ממיני השור. \u0003ור' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003מדקא חשיב ליה בהדי\u0004 \u0005[מכיון שהוא מונה אותו בין]\u0006 ה\u0003חיות\u0004 — \u0003מינא\u0004 \u0005[מין]\u0006 של \u0003חיה הוא. אבל הני\u0004 \u0005[אלה],\u0006 עיזי היער, מתוך שלא נימנו בין החיות — \u0003דברי הכל מינא\u0004 \u0005[מין]\u0006 ה\u0003עז נינהו\u0004 \u0005[הם]\u0006 וראויות להקרבה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: ודלמא מינא\u0004 \u0005[ושמא מין]\u0006 \u0003אקו נינהו\u0004 \u0005[הם]!\u0006 וכיוצא בזה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ודלמא מינא\u0004 \u0005[ושמא מין]\u0006 \u0003תאו, או מינא\u0004 \u0005[מין]\u0006 \u0003זמר נינהו\u0004 \u0005[הם]!\u0006 וכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב אשי: אמימר שרי תרבייהו\u0004 \u0005[התיר את חלבן],\u0006 שהוא מגדיר אותן כחיה.","שנינו במשנה: \u0003כיצד השוחט וכו'. אמר ר' אושעיא: כולה מתניתין\u0004 \u0005[כל משנתנו\u0006 זו\u0005]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' שמעון\u0004 היא, \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אתה יודע זאת? \u0003מדקא תני\u0004 \u0005[ממה שהוא שונה\u0006 בה\u0005]:\u0006 אם שחט אם ובנה ששניהם מן ה\u0003קדשים בחוץ\u0004 ביום אחד — על שחיטת \u0003הראשון חייב כרת,\u0004 משום שחיטת חוץ, \u0003ושניהם פסולים, ושניהם סופגים\u0004 (לוקים) \u0003את הארבעים\u0004 (מלקות). \u0003מכדי שמעינן ליה\u0004 \u0005[הואיל ושמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אמר: שחיטה שאינה ראויה\u0004 לאכילה — \u0003לא שמה שחיטה,\u0004 אינה נחשבת לשחיטה כלל, אלא כהריגה סתם,"],["אם כן, כששוחט קדשים בחוץ, אם ובנה — \u0003קמא מיקטל קטליה\u0004 \u0005[את הראשון\u0006 כאילו \u0005הרג אותו],\u0006 ולא שחטו, ששחיטת קדשים בחוץ שחיטה שאינה ראויה היא, ולפיכך \u0003שני\u0004 — ראוי להיות \u0003מתקבל בפנים הוא,\u0004 שאין איסור לשוחטו בו ביום. ואם כן כששוחט אותו בחוץ, מדוע שנינו שרק סופג את הארבעים? \u0003כרת נמי ליחייב\u0004 \u0005[גם כן יתחייב]!\u0006","וכן מה ששנינו שאם שחט אותו ואת בנו \u0003חולין בפנים\u0004 — \u0003שניהם פסולין, והשני סופג את הארבעים\u0004 משום אותו ואת בנו; \u0003מכדי שמעינן ליה\u0004 \u0005[הואיל ושמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אמר שחיטה שאינה ראויה לא שמה שחיטה,\u0004 אם כן \u0003קמא מיקטל קטליה\u0004 \u0005[את הראשון\u0006 כאילו \u0005הרג אותו],\u0006 ששחיטת חולין בפנים שחיטה שאינה ראויה היא, שהרי נאסר בהנאה. והואיל ושחיטת הראשון אינה שחיטה, על שחיטת ה\u0003שני אמאי\u0004 \u0005[מדוע]\u0006 \u0003סופג את הארבעים?\u0004 והרי לא שחט אותו ואת בנו!","וכן מה ששנינו: שחט אותו ואת בנו \u0003קדשים בפנים\u0004 — \u0003הראשון כשר ופטור, והשני סופג את הארבעים, ופסול\u0004 משום פסול מחוסר זמן, שכיון שאינו יכול להישחט באותו יום הריהו כנשחט קודם זמנו.","\u0003מכדי שמעינן ליה\u0004 \u0005[הואיל ושמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אמר: שחיטה שאינה ראויה לא שמה שחיטה,\u0004 הרי \u0003שחיטת קדשים נמי\u0004 \u0005[גם כן]\u0006 \u0003שחיטה שאינה ראויה היא,\u0004 ומדוע? \u0003דכמה דלא זריק\u0004 \u0005[שכל עוד שאינו זורק]\u0006 \u0003דם\u0004 — \u0003לא מישתרי בשר\u0004 \u0005[אין הבשר מותר]\u0006 בהקרבה ובאכילה. וכיון ששחיטת הראשון אינה קרויה שחיטה, אם כן על שחיטת \u0003השני אמאי\u0004 \u0005[מדוע]\u0006 \u0003סופג את הארבעים, ו\u0004מדוע הוא \u0003פסול?\u0004 הרי לא נשחט קודם זמנו! \u0003אלא, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמשנתנו היא ש\u0003לא כר' שמעון.\u0004","ומתקשים: \u0003פשיטא דהכי איתא\u0004 \u0005[פשוט שכך הוא]!\u0006 ומדוע היה צריך להביא את כל הראיות האלה? ומשיבים: בענין \u0003שחיטת קדשים\u0004 אותו ואת בנו בפנים \u0003איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 להשמיע שאינה כשיטת ר' שמעון. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003שחיטת קדשים\u0004 — \u0003שחיטה ראויה היא, דהא אי נחר וזריק\u0004 \u0005[שהרי אם היה נוחר,\u0006 הורג את הבהמה, \u0005וזורק]\u0006 את ה\u0003דם\u0004 — \u0003לא מישתרי בשר\u0004 \u0005[אין הבשר ניתר],\u0006 \u0003וכי שחט\u0004 \u0005[ו\u0006רק \u0005כאשר שוחט]\u0006 את הבהמה \u0003מישתרי\u0004 \u0005[מותר]\u0006 ה\u0003בשר, ו\u0004אם כן נמצא ש\u0003שחיטה ראויה היא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלא.","ושואלים על מקרה זה של קדשים בפנים, שלפי משנתנו הריהו לוקה על שחיטת השני משום אותו ואת בנו: \u0003ולילקי נמי\u0004 \u0005[ושילקה גם כן]\u0006 על שחיטת השני \u0003משום לאו\u0004 של הקרבת קרבן \u0003מחוסר זמן,\u0004 שאינו ראוי להקרבה עד למחרת. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין לכל הפסולין שבשור ושבשה,\u0004 מן הבקר ומן הצאן, שאם הקדישם, או שחטם, או הקריבם, \u0003שהוא\u0004 עובר ולוקה עליו \u0003ב\u0004איסור \u0003\"לא ירצה\"?\u0004","\u0003תלמוד לומר\u0004 באמצע פרשת איסור בעלי מום למזבח: \u0003\"ושור ושה שרוע וקלוט...\u0004 ולנדר לא ירצה\" \u0003וגו'\u0004 (ויקרא כב, כג), ולא היה צריך לכתוב \"ושור ושה\", שהרי בהם הוא עוסק באותה פרשה. אלא \u0003לימד על\u0004 כל \u0003הפסולין\u0004 להקרבה \u0003שבשור ושבשה,\u0004 ובכלל זה מחוסר זמן, \u0003שהוא ב\u0004איסור \u0003\"לא ירצה\"!\u0004","ומשיבים: אכן, כך הדין, אלא \u0003כי קא חשיב\u0004 \u0005[כאשר הוא מונה]\u0006 במשנתנו את הלאוים — \u0003לאוי\u0004 \u0005[את הלאוים]\u0006 של \u0003אותו ואת בנו\u0004 הוא מונה, \u0003לאוי נוכראי לא קא חשיב\u0004 \u0005[לאוים זרים,\u0006 אחרים, \u0005אינו מונה].\u0006","ושואלים: \u0003ולא\u0004 מונה אותם התנא? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003קדשים בחוץ, דלאוי נוכראי נינהו\u0004 \u0005[שלאוים זרים הם],\u0006 \u0003וקא חשיב\u0004 \u0005[והוא מונה\u0006 אותם\u0005]!\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]:\u0006 \u0003קדשים בחוץ\u0004 — \u0003הראשון חייב כרת, ושניהם סופגין את הארבעים;\u0004","\u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 שעל ה\u0003שני\u0004 סופג את הארבעים \u0003משום\u0004 ה\u0003לאו\u0004 של \u0003אותו ואת בנו, אלא\u0004 על ה\u0003ראשון אמאי\u0004 \u0005[מדוע]\u0006 \u0003סופג\u0004 מלקות? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שהוא עובר על \u0003לאו\u0004 של \u0003שחוטי חוץ?\u0004 ואם כן, בדין קדשים בפנים גם כן היה צריך למנות את הלאו של \"לא ירצה\"!","ומשיבים: \u0003כל היכא דליכא\u0004 \u0005[בכל מקום שאין]\u0006 בשחיטה \u0003לאו\u0004 של \u0003אותו ואת בנו\u0004 — \u0003חשיב לאוי נוכראי\u0004 \u0005[מונה הוא לאוים זרים],\u0006 \u0003וכל היכא דאיכא\u0004 \u0005[ובכל מקום שיש]\u0006 \u0003לאו\u0004 של \u0003אותו ואת בנו\u0004 — \u0003לא חשיב לאוי נוכראי\u0004 \u0005[אין מונה הוא לאוים זרים],\u0006 אלא רק את הלאו של \"אותו ואת בנו\".","\u0003ר' זירא אמר\u0004 הסבר אחר: \u0003הנח למחוסר זמן,\u0004 שאין לוקים עליו, מפני ש\u0003הכתוב\u0004"],["\u0003נתקו\u0004 משאר הפסולים שעובר עליהם בלאו \"לא ירצה\", \u0003ל\u0004עבור עליו ב\u0003עשה\u0004 בלבד. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 מהיכן למדים שיש בו איסור עשה? \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 במחוסר זמן: \u0003\"מיום השמיני והלאה ירצה\u0004 לקרבן\" (ויקרא כב, כז), \u0003\"מיום השמיני\"\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מעיקרא\u0004 \u0005[מתחילה,\u0006 קודם לכן\u0005]\u0006 — \u0003לא,\u0004 ואם כן הרי זה \u0003לאו הבא מכלל עשה,\u0004 ולאו הבא מכלל עשה אינו נידון כלאו ללקות עליו, אלא כ\u0003עשה.\u0004","ושואלים: \u0003והא מיבעיא ליה\u0004 \u0005[והרי צריך\u0006 פסוק \u0005זה]\u0006 \u0003לכ\u0004 מו שאמר \u0003ר' אפטוריקי,\u0004 ש\u0003ר' אפטוריקי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 בפסוק אחד \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"והיה שבעת ימים תחת אמו\"\u0004 (שם), ומשמע: \u0003הא\u0004 \u0005[אבל]\u0006 ב\u0003לילה\u0004 שלאחר היום השביעי הוא כבר \u0003חזי\u0004 \u0005[ראוי];\u0006 \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"מיום השמיני והלאה ירצה\",\u0004 ומשמע: \u0003מיום השמיני והלאה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003לילה\u0004 שלפני כן — \u0003לא!\u0004","ותירץ: \u0003הא כיצד\u0004 מיישבים את הכתובים? \u0003לילה\u0004 הוא \u0003לקדושה,\u0004 שאפשר להקדיש אותו כבר בלילה שלאחר היום השביעי, ואינו עובר על איסור הקדשת קרבן פסול. ו\u0003יום\u0004 השמיני הוא \u0003להרצאה,\u0004 שאפשר להקריב אותו שיעלה לרצון! ומשיבים: \u0003כתיב קרא אחרינא\u0004 \u0005[כתוב פסוק אחר]\u0006 שיש בו עשה זה — \u0003\"כן תעשה לשורך לצאנך\u0004 שבעת ימים יהיה עם אמו ביום השמיני תתנו לי\" (שמות כב, כט).","ושבים לדון בשיטת ר' שמעון בענין אותו ואת בנו. \u0003אמר רב המנונא: אומר היה ר' שמעון, אין\u0004 איסור \u0003אותו ואת בנו נוהג בקדשים, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כיון\u0004 ש\u0003אמר ר' שמעון: שחיטה שאינה ראויה\u0004 (שאינה מתירה באכילה) — \u0003לא שמה\u0004 \u0005[אינה נחשבת]\u0006 כ\u0003שחיטה\u0004 כלל, הרי \u0003שחיטת קדשים נמי\u0004 \u0005[גם כן]\u0006 \u0003שחיטה שאינה ראויה היא,\u0004 שאינה מתירה את הבשר להקרבה ולאכילה עד שייזרק הדם.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: שחט \u0003אותו ואת בנו קדשים בחוץ, ר' שמעון אומר:\u0004 על ה\u0003שני\u0004 עובר \u0003בלא תעשה,\u0004 משום שחיטת חוץ. \u0003שהיה ר' שמעון אומר, כל הראוי לבא לאחר זמן\u0004 והקריבו בחוץ — \u0003הרי הוא\u0004 עובר עליו \u0003בלא תעשה\u0004 משום שחיטת חוץ, \u0003ואין בו\u0004 עונש \u0003כרת. וחכמים אומרים כל שאין בו כרת\u0004 משום שחיטת חוץ, שאינו ראוי להקרבה באותה שעה — אף \u0003אינו בלא תעשה.\u0004","\u0003וקשיא לן\u0004 \u0005[ו\u0006היה \u0005קשה לנו]:\u0006 שחט \u0003קדשים בחוץ,\u0004 מדוע \u0003ה\u0004\u0003שני\u0004 רק \u0003ב\u0004איסור \u0003לא תעשה?\u0004 הלא לשיטת ר' שמעון, ששחיטה שאינה ראויה להתיר את הבהמה באכילה — אינה קרויה כלל שחיטה, נמצא כי \u0003קמא מיקטל קטל\u0004 \u0005[\u0006את \u0005הראשון\u0006 ששחט בחוץ כאילו \u0005הרג\u0006 אותו\u0005],\u0006 שהרי שחיטה פסולה היא, ואם כן ה\u0003שני מקבל\u0004 \u0005[מתקבל]\u0006 \u0003בפנים הוא,\u0004 וראוי להקרבה, ולפי זה \u0003כרת נמי ליחייב\u0004 \u0005[גם כן שיתחייב]\u0006 על שחיטתו בחוץ!","\u0003ואמר רבא ואמרי לה כדי\u0004 \u0005[ויש אומרים אותה בלי שם]:\u0006 \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך יש לשנותה]:\u0006 אם שחט \u0003קדשים\u0004 אותו ואת בנו \u0003שניהם בחוץ, לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 על ה\u0003ראשון ענוש כרת,\u0004 ה\u0003שני פסול\u0004 משום שהוא מחוסר זמן \u0003ו\u0004לכן \u0003פטור\u0004 עליו \u0003מלאו\u0004 של \u0003שחוטי חוץ. ל\u0004דעת","\u0003ר' שמעון\u0004 — על \u0003שניהם ענושים כרת,\u0004 גם על השני, כיון ששחיטתו של הראשון אינה שחיטה, לאסור את השני משום אותו ואת בנו.","אם שחט קדשים, אותו ואת בנו, \u0003אחד בחוץ ואחד\u0004 אחריו \u0003בפנים\u0004 — \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 על ה\u0003ראשון ענוש כרת,\u0004 ואילו ה\u0003שני פסול,\u0004 משום שהוא מחוסר זמן, \u0003ו\u0004לכן \u0003פטור\u0004 על שחיטתו משום שחיטת חוץ. \u0003ל\u0004דעת \u0003ר' שמעון שני כשר\u0004 לגמרי, ומקריבים אותו, שאין בו איסור אותו ואת בנו, שהרי שחיטת הראשון שחיטה שאינה ראויה היא.","שחט קדשים, אותו ואת בנו, \u0003אחד בפנים ואחד\u0004 אחריו \u0003בחוץ, לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 ה\u0003ראשון כשר ופטור,\u0004 שאין כל פגם בשחיטתו. ה\u0003שני פסול\u0004 משום שנשחט בחוץ, \u0003ופטור\u0004 על שחיטתו בחוץ, משום שאינו ראוי להקרבה בפנים, שהרי הוא מחוסר זמן. ואילו \u0003ל\u0004דעת \u0003ר' שמעון\u0004 על שחיטת ה\u0003שני\u0004 בחוץ עובר \u0003בלא תעשה,\u0004 וכדין מחוסר זמן שהקריבו בחוץ.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003אין\u0004 איסור \u0003אותו ואת בנו נוהג בקדשים,\u0004 על שחיטת ה\u0003שני\u0004 בחוץ \u0003אמאי\u0004 \u0005[מדוע]\u0006 עובר רק \u0003בלא תעשה\u0004 \u0003ותו\u0004 \u0005[ועוד]\u0006 \u0003לא?\u0004 עונש \u0003כרת נמי ליחייב\u0004 \u0005[גם כן שיתחייב],\u0006 שהואיל ואין בו איסור אותו ואת בנו — מתקבל בפנים הוא! אלא בוודאי יש איסור אותו ואת בנו בקדשים!","\u0003אלא אמר רבא, הכי קא אמר\u0004 \u0005[כך אומר]\u0006 \u0003רב המנונא:\u0004 איסור אותו ואת בנו נוהג בקדשים, אבל \u0003אין\u0004 עונש \u0003מלקות\u0004 על \u0003אותו ואת בנו נוהג בקדשים,\u0004 ומדוע?","\u0003כיון דכמה דלא זריק\u0004 \u0005[שכל עוד שלא זורק]\u0006 את ה\u0003דם לא מישתרי בשר\u0004 \u0005[לא מותר הבשר]\u0006 לאכילה ולהקרבה. נמצא כי \u0003מעידנא דקא שחיט\u0004 \u0005[מזמן שהוא שוחט],\u0006 כשמתרים בו על איסור שחיטת אותו ואת בנו — \u0003הואי\u0004 \u0005[הרי זו]\u0006 רק \u0003התראת ספק,\u0004 שמא לא ייזרק הדם, \u0003והתראת ספק לא שמה\u0004 \u0005[אינה נחשבת]\u0006 \u0003התראה\u0004 ללקות עליה.","ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא:\u0004 לדעת ר' שמעון, ששחיטה שאינה ראויה אין חייבים עליה משום אותו ואת בנו, אם \u0003היא\u0004 האם \u0003חולין ובנה שלמים,\u0004 ו\u0003שחט\u0004 תחילה את האם שהיא \u0003חולין, ואחר כך שחט\u0004 את הבן שהוא \u0003שלמים\u0004 בו ביום — הרי הוא \u0003פטור\u0004 על שחיטת הבן, משום התראת ספק, שמא לא ייזרק הדם, ואין זו שחיטה ראויה.","אבל אם שחט קודם את הבן שהוא \u0003שלמים, ואחר כך\u0004 שחט את האם שהיא \u0003חולין\u0004 — \u0003חייב\u0004 על שחיטת האם, שהרי התראת ודאי היא, שכיון שהוא חולין — אין אחר השחיטה כלום. \u0003ואמר רבא: היא\u0004 הבהמה \u0003חולין ובנה עולה,\u0004 ושחטם ביום אחד, \u0003לא מיבעיא\u0004 \u0005[לא נצרכה\u0006 לומר\u0005]\u0006 במקרה ש\u0003שחט\u0004 תחילה את האם ה\u0003חולין ואחר כך שחט\u0004 את הבן ה\u0003עולה\u0004 שהוא \u0003פטור,\u0004"],["\u0003אלא, אפילו שחט\u0004 את בנה ל\u0003עולה\u0004 וזרק את דמו, \u0003ואחר כך שחט\u0004 אותה ל\u0003חולין\u0004 — \u0003פטור,\u0004 ומדוע? \u0003שחיטה קמייתא לאו\u0004 \u0005[ראשונה לא]\u0006 \u0003שחיטה בת אכילה\u0004 \u0003היא,\u0004 שהרי עולה קריבה כליל ואינה נאכלת. ולדעת ר' שמעון, שחיטה שאינה ראויה לאכילה — אינה שחיטה.","\u0003ור' יעקב אמר ר' יוחנן: אכילת מזבח שמה\u0004 \u0005[נחשבת]\u0006 \u0003אכילה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 בדין פיגול: \u0003\"ואם האכל יאכל מבשר זבח שלמיו\u0004 ביום השלישי לא ירצה\" (ויקרא ז, יח) — הביטוי הכפול \"האכל יאכל\" מלמד כי","\u0003בשתי אכילות הכתוב מדבר, אחד אכילת אדם ואחד אכילת מזבח,\u0004 ששתיהן נחשבות אכילה, לענין פיגול, ולעניינים אחרים. ולכן, שחיטת עולה — שחיטה ראויה לאכילה היא, והשוחט את הבן לעולה, ואת אמו לחולין — לוקה משום אותו ואת בנו, גם לדעת ר' שמעון.","\u0003השוחט\u0004 בהמה ובנה \u0003ונמצא\u0004 שאחד מהם \u0003טרפה,\u0004 ושחיטתו לא התירה אותו באכילה. וכן \u0003השוחט\u0004 אחד מהם \u0003ל\u0004שם \u0003עבודה זרה, והשוחט פרת חטאת\u0004 (פרה אדומה), \u0003ו\u0004השוחט \u0003שור הנסקל,\u0004 שנגזר דינו לסקילה, כגון שהרג אדם, \u0003ו\u0004כן השוחט \u0003עגלה ערופה,\u0004 שכל אלה אסורים בהנאה — \u0003ר' שמעון פוטר\u0004 משום אותו ואת בנו, שלדעתו, שחיטה שאינה ראויה (שאינה מתירה את הבהמה לאכילה) — אינה קרויה שחיטה לחייב עליה. \u0003וחכמים מחייבין,\u0004 שלדעתם אין צורך שתהא השחיטה ראויה לאכילה.","אבל גם לדעת חכמים, \u0003השוחט ונתנבלה\u0004 הבהמה \u0003בידו,\u0004 שקלקל בשחיטתה, או \u0003הנוחר\u0004 (הורג אותה על ידי דקירה), או \u0003המעקר\u0004 את הקנה והוושט, וכך הורג אותה — \u0003פטור משום אותו ואת בנו,\u0004 שאיסור זה נאמר רק בשחיטה, שנאמר \"אותו ואת בנו לא תשחטו\" (ויקרא כב, כח), והרי לא היתה כאן שחיטה.","בענין השוחט לעבודה זרה, שנחלקו במשנה האם חייב על שחיטה זו משום אותו ואת בנו, \u0003אמר ר' שמעון בן לקיש: לא שנו\u0004 שמחייבים חכמים על שחיטת השני, \u0003אלא ששחט\u0004 את ה\u0003ראשון לעבודה זרה ו\u0004את ה\u0003שני לשלחנו,\u0004 לעצמו, \u0003אבל\u0004 אם שחט את ה\u0003ראשון לשלחנו ו\u0004את ה\u0003שני לעבודה זרה\u0004 — הריהו \u0003פטור\u0004 ממלקות על השני, גם לדעת חכמים, משום \u0003דקם ליה בדרבה מיניה\u0004 \u0005[שהוא עומד ב\u0006עונש \u0005גדול ממנו],\u0006 שהשוחט לעבודה זרה חייב מיתה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: זו,\u0004 שהנענש בעונש חמור נפטר מן העונש הקל יותר — \u0003אפילו תינוקות של בית רבן יודעין אותה! אלא, פעמים שאפילו שחט\u0004 את ה\u0003ראשון לשלחנו ו\u0004את ה\u0003שני לעבודה זרה\u0004 — \u0003חייב\u0004 מלקות על שחיטת השני, כיצד?","\u0003כגון דאתרו ביה\u0004 \u0005[שהתרו בו]\u0006 על שחיטת השני \u0003משום אותו ואת בנו, ולא אתרו\u0004 \u0005[התרו]\u0006 \u0003בו משום עבודה זרה,\u0004 שכיון שאינו נענש משום עבודה זרה — לוקה על האיסור הקל. \u0003ור' שמעון בן לקיש אמר: כיון דכי אתרו ביה\u0004 \u0005[שכאשר,\u0006 אם \u0005היו מתרים בו]\u0006 משום עבודה זרה היה \u0003פטור\u0004 משום אותו ואת בנו, \u0003כי לא אתרו ביה\u0004 \u0005[כאשר לא התרו בו]\u0006 משום עבודה זרה — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור.\u0004 שכיון שעבר אדם על איסור חמור שיש בו עונש מיתה, למרות שאינו נענש עליו בפועל — אינו נענש על האיסור הקל.","ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והולכים הם לטעמיהם,\u0006 לשיטותיהם\u0005]\u0006 לענין זה, \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: חייבי מיתות שוגגין, וחייבי מלקות שוגגין, ודבר אחר,\u0004 אדם שעשה מעשה שיש בו שני איסורים, אחד שיש בו עונש מיתה או מלקות, ואחד שיש בו עונש ממון, והתרו בו על עונש הממון, ולא התרו בו על עונש המיתה או המלקות — \u0003ר' יוחנן אומר: חייב\u0004 בעונש הממון, \u0003וריש לקיש אומר: פטור.\u0004","ומסבירים: \u0003ר' יוחנן אומר חייב\u0004 בעונש הממון — \u0003דהא לא אתרו\u0004 \u0005[שהרי לא התרו]\u0006 \u0003בו\u0004 על העבירה החמורה, ונשאר עונש זה לבדו. \u0003וריש לקיש אומר פטור\u0004 — \u0003דכיון דכי אתרו ביה\u0004 \u0005[שכיון שכאשר,\u0006 אם, \u0005היו מתרים בו]\u0006 על העבירה החמורה היה \u0003פטור\u0004 מתשלום הממון, \u0003כי לא אתרו ביה\u0004 \u0005[כאשר לא התרו בו]\u0006 על העבירה החמורה — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריכה]\u0006 המחלוקת להיאמר בשני המקרים, \u0003דאי אשמועינן בהא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק \u0005בזו]\u0006 בשוחט את האם לצורך עצמו, ואת בנה באותו יום לעבודה זרה — הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו,\u0006 שיש מיתה ומלקות, \u0005אומר]\u0006 \u0003ר' שמעון בן לקיש\u0004 שאם לא התרו בו משום עבודה זרה — פטור ממלקות משום אותו ואת בנו, \u0003אבל בהא\u0004 \u0005[בזו],\u0006 בעבירה שיש בה עונש מיתה או מלקות, ועונש ממון, ולא התרו בו בעונש המיתה או המלקות — \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לר' יוחנן,\u0004 שחייב בעונש הממון.","ולהיפך, \u0003ואי איתמר בהא\u0004 \u0005[ואם היה נאמר בזו],\u0006 בעבירה שיש בה עונש מיתה או מלקות, ועונש ממון, ולא התרו בו על עונש המיתה או המלקות — הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003ר' יוחנן\u0004 שחייב בעונש הממון, \u0003אבל בהא\u0004 \u0005[בזו],\u0006 ששחט אותו ואת בנו לעבודה זרה, שיש עונש מיתה ועונש מלקות, ולא התרו בו על המיתה — \u0003אימא מודי\u0004 \u0005[אמור שמודה]\u0006 \u0003לר' שמעון בן לקיש\u0004 שפטור ממלקות, על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 המחלוקת להיאמר בשני אופנים אלה.","שנינו במשנה, שהשוחט פרת חטאת (פרה אדומה), פטור לדעת ר' שמעון משום אותו ואת בנו, מפני שהיא שחיטה שאינה ראויה לאכילה. ושואלים: \u0003ו\u0004האם שחיטת \u0003פרת חטאת שחיטה שאינה ראויה היא? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: פרה\u0004 אדומה שנשחטה \u0003מטמאה טומאת אוכלין,\u0004 אף על פי שאינה מותרת באכילה, ומדוע? \u0003הואיל והיתה לה שעת הכושר,\u0004 שהיתה שעה שהיתה ראויה להיפדות ולהיאכל."],["\u0003ו\u0004מהי אותה שעה? \u0003אמר ר' שמעון בן לקיש, אומר היה ר' שמעון: פרה\u0004 אדומה \u0003נפדית,\u0004 אם יש בכך צורך, אפילו כבר נשחטה \u0003על גבי מערכתה,\u0004 מערכת העצים המיועדת לשריפתה. ואם כן, כשנשחטה היתה ראויה לאכילה, ומדוע אומר ר' שמעון שאינו חייב עליה משום אותו ואת בנו? \u0003אמר רב שמן בר אבא אמר ר' יוחנן: פרת חטאת אינה משנה,\u0004 כלומר, יש למחוק פרת חטאת מן המשנה, שאף לדעת ר' שמעון חייבים על שחיטתה משום אותו ואת בנו.","ועוד שואלים: \u0003ועגלה ערופה,\u0004 ששנינו שלדעת ר' שמעון אין חייבים על שחיטתה משום אותו ואת בנו, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003שחיטה ראויה היא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אם לקחו עגלה כדי לעורפה ובכך לכפר על חלל שנמצא ולא נודע מי הרגו, ו\u0003נמצא ההורג עד שלא תערף העגלה\u0004 — \u0003תצא ותרעה בעדר,\u0004 ככל בהמה. הרי שקודם עריפה אינה אסורה בהנאה, ושחיטה ראויה היא! \u0003אמר ר' שמעון בן לקיש משום\u0004 (בשם) \u0003ר' ינאי: עגלה ערופה אינה משנה,\u0004 וגם לדעת ר' שמעון חייבים על שחיטתה משום אותו ואת בנו.","ושואלים: \u0003ומי אמר\u0004 \u0005[והאם אומר]\u0006 \u0003ר' ינאי הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' ינאי: גבול שמעתי בה\u0004 בעגלה הערופה, ממתי היא נאסרת בהנאה, \u0003ושכחתי\u0004 מהו הגבול, \u0003ונסבין חבריא\u0004 \u0005[ומציעים החברים,\u0006 בני הישיבה\u0005]\u0006 \u0003לומר\u0004 ש\u0003ירידתה לנחל איתן\u0004 היא \u0003אוסרתה.\u0004","\u0003ואם איתא\u0004 \u0005[אכן]\u0006 כך הוא, \u0003לישני\u0004 \u0005[שיתרץ]\u0006 כך את \u0005הקושיה:\u0006 \u0003כאן\u0004 שלפני עריפתה הריהי מותרת בהנאה, ויכול לעבור עליה משום אותו ואת בנו — מדובר שנשחטה \u0003קודם ירידה\u0004 לנחל איתן. \u0003כאן\u0004 במשנתנו ששנה ר' שמעון שאינו עובר משום אותו ואת בנו — מדובר \u0003לאחר ירידה,\u0004 שכבר נאסרה בהנאה, ובמקרה זה, ששחיטתה אינה ראויה, חלוקים ר' שמעון וחכמים במשנתנו!","\u0003אמר ר' פנחס בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי: אנן משמיה\u0004 \u0005[אנו משמו]\u0006 של \u0003ר' שמעון בן לקיש\u0004 בלבד \u0003מתנינן לה\u0004 \u0005[שונים אנו אותה],\u0006 שאמר בעצמו ש\u0003עגלה ערופה אינה משנה,\u0004 ולא שאמר כן משמו של ר' ינאי. \u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו\u0006 לומדים \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב פפי קשיא לן\u0004 \u0005[היה קשה לנו]\u0006 על כך: \u0003מי אמר\u0004 \u0005[האם אומר]\u0006 \u0003ר' שמעון בן לקיש הכי\u0004 \u0005[כך],\u0006 שעגלה ערופה אינה משנה, משום ששחיטתה שחיטה ראויה היא?","\u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו אמוראים בשאלה: \u0003צפורי מצורע\u0004 שעושים לטהרת המצורע, שהם אסורים בהנאה, \u0003מאימתי נאסרין? ר' יוחנן אמר: משעת שחיטה\u0004 של הציפור, \u0003ור' שמעון בן לקיש אמר: משעת לקיחה,\u0004 משעה שקנו אותם לשם כך. \u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון בן לקיש?\u0004","\u0003גמר\u0004 \u0005[\u0006הריהו \u0005לומד]\u0006 דבר זה בגזירה שווה \u0003\"קיחה\" \"קיחה\" מעגלה ערופה,\u0004 שכשם שעגלה ערופה שנאמר בה \"ולקחו\" (דברים כא, ד) אסורה בהנאה משעת לקיחתה לשם כך — כך ציפורי מצורע, שנאמר בהם \"ולקח\" (ויקרא יד, ד) נאסרו משעת לקיחה. והואיל ולדעתו עגלה ערופה אסורה בהנאה כבר משעת לקיחתה בעודה חיה, נמצא ששחיטתה אינה ראויה, וממילא ר' שמעון פוטר על שחיטתה משום אותו ואת בנו, כפי ששנינו במשנתנו!","\u0003אלא\u0004 צריך לומר ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: עגלה ערופה אינה משנה,\u0004 כלומר, שדבר זה נאמר על ידי ר' יוחנן, ולא על ידי ריש לקיש.","\u0003שנים שלקחו\u0004 (קנו) \u0003פרה ובנה,\u0004 האחד אותה והאחר את בנה, \u0003איזה\u0004 מהם \u0003שלקח\u0004 (קנה) \u0003ראשון\u0004 — הוא \u0003ישחוט ראשון,\u0004 והשני ימתין וישחט ביום הבא, כדי שלא יעבור על \"אותו ואת בנו לא תשחטו ביום אחד\" (ויקרא כב, כח), \u0003ואם קדם השני\u0004 ושחט — \u0003זכה.\u0004","\u0003אמר רב יוסף:\u0004 מה ששנינו שאיזה שלקח ראשון ישחט ראשון, לא לענין איסור והיתר נאמר, שאין איסור על השני לשחוט קודם הראשון, אלא \u0003לענין דינא תנן\u0004 \u0005[דין שנינו],\u0006 שאם באים שניהם לבית דין — יכול הראשון לעכב את השני מלשחוט עד שהוא ישחט תחילה. וכן \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: \u0003אם קדם השני\u0004 ושחט — \u0003הרי זה זריז ונשכר.\u0004 ומפרשים: \u0003זריז\u0004 — שעשה כראוי, \u0003דלא עבד איסורא\u0004 \u0005[שלא עשה איסור],\u0006 שנמנע מלהגיע לידי \u0005איסור,\u0006 \u0003ונשכר\u0004 — \u0003דקאכיל בשרא\u0004 \u0005[שהוא אוכל\u0006 כבר היום \u0005בשר].\u0006","\u0003שחט פרה ואחר כך\u0004 שחט את \u0003שני בניה\u0004 באותו יום — \u0003סופג שמונים\u0004 מלקות, שעבר שתי עבירות נפרדות. אבל אם \u0003שחט שני בניה ואחר כך שחטה\u0004 — \u0003סופג את הארבעים,\u0004 שעשה מעשה אחד של איסור. אם \u0003שחטה ואת בתה, ו\u0004אחר כך שחט \u0003את בת בתה\u0004 באותו יום — \u0003סופג שמונים,\u0004 ששחט פעמיים בת אחרי האם.","אבל אם \u0003שחטה ו\u0004אחר כך \u0003את בת בתה,\u0004 ובשלב זה לא עבר איסור, \u0003ואחר כך שחט\u0004 את \u0003בתה\u0004 בו ביום — \u0003סופג את הארבעים\u0004 על שחיטת בתה. \u0003סומכוס אומר משום\u0004 (בשם) \u0003ר' מאיר:\u0004 במקרה זה \u0003סופג שמונים,\u0004 שהרי בשחיטת בתה עבר שתי עבירות. שבת זו נשחטה ביום ששחט את אמה וביום ששחט את בתה.","שנינו במשנה שאם שחט שני בניה של פרה ואחר כך שחט אותה — לוקה. שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 לוקה? והרי \u0003\"אותו ואת בנו\"\u0004 (ויקרא כב, כח) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003ולא בנו ואותו!\u0004 ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לפרש כן, \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"אותו ואת בנו\"\u0004 — \u0003אין לי אלא אותו ואת בנו,\u0004 קודם האם ואחר כך הבן, \u0003אותו ו\u0004אחר כך \u0003את אמו מנין\u0004 שאסור לשחוט ביום אחד?","\u0003כשהוא אומר \"לא תשחטו\u0004 ביום אחד\" — \u0003הרי כאן שנים,\u0004 ששני אנשים הוזהרו באיסור זה. \u0003הא כיצד\u0004 מתקיים הדבר? כשיש שלוש בהמות — פרה, ואמה, ובנה, כאשר \u0003אחד השוחט\u0004 תחילה \u0003את הפרה,\u0004 ו\u0003אחד השוחט\u0004 אחר כך \u0003את אמה, ואחד השוחט\u0004 אחר כך \u0003את בנה\u0004 — \u0003שנים האחרונים חייבין,\u0004 האחד משום אותו ואת אמו, והשני משום אותו ואת בנו."],["ושואלים: \u0003האי מיבעי ליה לגופיה\u0004 \u0005[כתוב זה נצרך לו לגופו],\u0006 לעצם האיסור לשחוט אותו ואת בנו! ומשיבים: \u0003אם כן ליכתוב\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"לא תשחוט\"\u0004 בלשון יחיד, \u0003מאי\u0004 \u0005[מה,\u0006 מדוע\u0005]\u0006 \u0003\"לא תשחטו\"\u0004 בלשון רבים? אלא מכאן למדנו אזהרה לשנים.","ושואלים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין נצרך לו]\u0006 לשון רבים לענין אחר, \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 \u0003\"לא תשחוט\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003חד\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 אסור לו לשחוט אותו ואת בנו, \u0003תרי\u0004 \u0005[שנים]\u0006 — \u0003לא,\u0004 ואם אדם אחד שחט את האם — מותר לאחר לשחוט את הבן, על כן","\u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"לא תשחטו\"\u0004 — \u0003ואפילו תרי\u0004 \u0005[שנים]!\u0006 ומשיבים: \u0003אם כן,\u0004 שרק דבר זה למדנו מכאן, \u0003לכתוב\u0004 \u0005[שתכתוב\u0006 התורה\u0005]\u0006 \u0003\"לא ישחטו\",\u0004 לומר שאין חשיבות מי שוחט, אלא שלא יישחטו האם ובנה ביום אחד.","נמצא שבכל אופן, רק אחד עובר על האיסור, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא תשחטו\",\u0004 שיש איסור על שני אנשים שונים לשחוט? \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שתים],\u0006 שתי הלכות: שהאיסור הוא גם בשנים, וגם שיש שני איסורים, לשחוט אותו ואת בנו, ולשחוט את בנו ואותו.","שנינו במשנה: \u0003שחטה ואת בת בתה\u0004 ואחר כך שחט את בתה — סופג ארבעים. סומכוס אומר משום ר' מאיר: סופג שמונים, שבשחיטת הבת עבר פעמיים על איסור אותו ואת בנו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003סומכוס\u0004 שלוקה פעמיים על שחיטת הבת?","האם משום ש\u0003קא סבר\u0004 \u0005[סבור]\u0006 \u0003סומכוס\u0004 באופן כללי, שאם \u0003אכל שני זיתי\u0004 (שתי חתיכות בשיעור כזית) \u0003חלב בהעלם אחד,\u0004 כלומר, בשגגה אחת, שלא נודע לו חטאו בין שני הזיתים — \u0003חייב שתי חטאות,\u0004 כיון שעבר פעמיים על האיסור. וכן במזיד, אם לאחר שהתרו בו שהוא עומד ללקות, עשה איסור אחד פעמיים — לוקה פעמיים. והוא הדין במשנתנו, כשעבר בשחיטת הבת פעמיים על איסור אותו ואת בנו.","\u0003ובדין הוא\u0004 (ראוי היה) \u0003דלישמעינן בעלמא\u0004 \u0005[שהיה\u0006 רבי מסדר המשנה \u0005משמיע לנו\u0006 דבר זה \u0005בכלל,\u0006 במקרה רגיל\u0005],\u0006 כגון אוכל שני זיתי חלב בהעלם אחד, שלדעת סומכוס חייב שתי חטאות, \u0003והאי דקא משמע לן בהא\u0004 \u0005[וזה שמשמיע לנו ב\u0006מקרה \u0005זה],\u0006 כששחט אותה ואת בת בתה, ואחר כך שחט בתה, הוא \u0003להודיעך כחן דרבנן\u0004 \u0005[של חכמים],\u0006 עד כמה הם מקילים, \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003גופין מוחלקין,\u0004 שעל ידי שחיטת שתי פרות שונות, האם והבת, נעברה העבירה — \u0003פטרי רבנן\u0004 \u0005[פוטרים חכמים]\u0006 מעונש כפול.","\u0003או דלמא קסבר\u0004 \u0005[שמא סבור]\u0006 \u0003סומכוס:\u0004 בדרך כלל, מי ש\u0003אכל שני זיתי חלב בהעלם אחד,\u0004 שעבר עבירה כפולה באיסור אחד ובהתראה אחת — \u0003אינו חייב אלא אחת, והכא היינו טעמא\u0004 \u0005[כאן זהו הטעם]\u0006 שלוקה פעמיים — \u0003הואיל וגופין מוחלקין? אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אין\u0004 \u0005[כן],\u0006 \u0003קסבר\u0004 \u0005[סבור]\u0006 סומכוס שאם \u0003אכל שני זיתי חלב בהעלם אחד\u0004 — \u0003חייב שתי חטאות.\u0004","\u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]?\u0006 \u0003מדתנן\u0004 \u0005[ממה ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הזורע כלאים כלאים,\u0004 שזרע פעמיים תבואה יחד עם חרצני ענבים — \u0003לוקה\u0004 משום כלאי הכרם. ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לוקה? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לוקה\u0004 סדרת מלקות \u0003אחת\u0004 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, ומה באה הברייתא לחדש? \u0003ועוד,\u0004 אם לוקה אחת, \u0003מאי\u0004 \u0005[מה\u0006 ענין\u0005]\u0006 \u0003כלאים כלאים,\u0004 שזרע פעמיים? והרי אפילו זרע פעם אחת לוקה! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהכוונה היא שלוקה \u0003שני\u0004 עונשי \u0003מלקיות.\u0004","ויש לשאול: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שזרע \u0003בזה אחר זה, ובשתי התראות\u0004 שונות — לא הוצרכנו לומר דין זה בברייתא, שהרי כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במפורש במשנה: \u0003נזיר שהיה שותה יין כל היום\u0004 — \u0003אינו חייב אלא אחת. אמרו לו: אל תשתה! והוא שותה,\u0004 ושוב חזרו והתרו בו: \u0003אל תשתה! והוא שותה\u0004 — \u0003חייב על כל אחת ואחת! אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר שזרע פעמיים \u0003בבת אחת ובהתראה אחת,\u0004 שלאחר שהתרו בו, זרע ביד אחת חטה וחרצן של ענבים, ובידו האחרת שעורה וחרצן של ענבים, ובא ללמד שלוקה על כך פעמיים.","ויש לשאול: ברייתא זו \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אילימא רבנן דפליגי עליה\u0004 \u0005[אם תאמר\u0006 כשיטת \u0005חכמים שחולקים עליו]\u0006 על \u0003סומכוס\u0004 במשנתנו, ואומרים שאם שחט את האם ובת הבת, ואחר כך שחט את הבת לוקה פעם אחת — לא ייתכן הדבר, שהרי \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003ומה התם\u0004 \u0005[שם]\u0006 במשנתנו, שיש \u0003גופין מוחלקין,\u0004 ששחט את האם ואת בת הבת, ואחר כך את הבת — \u0003פטרי רבנן\u0004 \u0005[פוטרים אותו חכמים]\u0006 משתי מלקויות, כיון שעשה מעשה אחד ובהתראה אחת. \u0003הכא\u0004 \u0005[כאן]\u0006 בזריעת כלאיים, שאין גופים מוחלקים של בעלי חיים שונים, אם זרע שתי זריעות בבת אחת — \u0003לא כל שכן\u0004 שאינו חייב אלא אחת?","\u0003אלא\u0004 ברייתא זו בענין כלאיים \u0003לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003סומכוס היא?\u0004 ובא ללמד, שגם בגוף אחד של איסור, אם עשה את האיסור פעמיים, כגון שאכל חלב וחזר ואכל חלב — לוקה שתים? ודוחים: \u0003לא, לעולם\u0004 תאמר שברייתא זו שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, ומדובר כשהתרו בו לפני כל זריעה, ולכן לוקה פעמיים. \u0003ו\u0004אף שלכאורה אין בכך חידוש, \u0003מילתא אגב אורחיה קא משמע לן\u0004 \u0005[דבר\u0006 אחר \u0005בדרך אגב משמיע לנו]\u0006 במה ששנה \"כלאים כלאים\" — \u0003דאיכא תרי גווני\u0004 \u0005[שיש שני סוגי]\u0006 \u0003כלאים\u0004 בכלאי הכרם, חיטה וגפן, ושעורה וגפן.","\u0003ולאפוקי\u0004 \u0005[ולהוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יאשיה,\u0004 ש\u0003אמר ר' יאשיה:\u0004 אינו חייב משום כלאי הכרם \u0003עד שיזרע\u0004 גם \u0003חטה ו\u0004גם \u0003שעורה ו\u0004גם \u0003חרצן\u0004 של גפן \u0003במפולת יד\u0004 אחת (בבת אחת), \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא \u0003דכי זרע\u0004 \u0005[שכאשר זורע]\u0006 \u0003חטה וחרצן\u0004 בלבד, \u0003ו\u0004כן \u0003שעורה וחרצן\u0004 בלבד, \u0003נמי מחייב\u0004 \u0005[גם כן מתחייב]\u0006 משום כלאי הכרם. ואם כן, עדיין לא נתבררה שיטת סומכוס במי שעובר פעמיים על איסור אחד, בהעלם אחד, או בהתראה אחת.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בענין אכילת גיד הנשה: \u0003אכל מזה כזית ומזה כזית,\u0004 מירך ימין וירך שמאל של בהמה אחת — \u0003סופג שמונים\u0004 מלקות. \u0003ר' יהודה אומר: אינו סופג אלא ארבעים.\u0004 ויש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאכלם \u0003בזה אחר זה ובשתי התראות\u0004 שונות — \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 שלוקה? והרי לדעת ר' יהודה \u0003התראת ספק היא,\u0004 שכן לשיטתו ספק אם איסור גיד הנשה נוהג בירך ימין או בירך שמאל, \u0003ושמעינן ליה\u0004 \u0005[ושמענו אותו]\u0006 את \u0003ר' יהודה\u0004 ש\u0003אמר: התראת ספק\u0004 \u0003לא שמה התראה.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מי שספק אם הוא בנו של אדם זה או אדם אחר, אם \u0003הכה את זה וחזר והכה את זה,\u0004 או \u0003קלל את זה וחזר וקלל את זה, או שהכה שניהם בבת אחת, או שקלל שניהם בבת אחת\u0004 — \u0003חייב\u0004 משום \"ומכה אביו ואמו מות יומת\" (שמות כא, טו), או משום \"ומקלל אביו ואמו מות יומת\" (שם יז).","\u0003ר' יהודה אומר:\u0004 היכה או קילל את שניהם \u0003בבת אחת\u0004 — \u0003חייב, בזה אחר זה\u0004 — \u0003פטור,\u0004 כיון שבכל פעם שהיכה או קילל — הרי זו התראת ספק, שמא אין זה אביו (והרי רק כאשר הוא ודאי אביו — חייב). ואם כן, הוא הדין אם התרו בו ואכל גיד הנשה מירך ימין, ואחר כך חזרו והתרו בו ואכל מגיד הנשה של ירך שמאל, שיהא פטור, שהרי בכל פעם היתה זו התראת ספק! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר שאכל אותם \u0003בבת אחת ובהתראה אחת,\u0004 ולכן לוקה ארבעים לדעת ר' יהודה.","ומעתה יש לשאול: \u0003ומאן תנא קמא\u0004 \u0005[ומיהו התנא הראשון],\u0006 הסבור שבמקרה זה סופג שמונים? \u0003אילימא רבנן דפליגי עליה\u0004 \u0005[אם תאמר חכמים שחולקים עליו]\u0006 על \u0003סומכוס\u0004 במשנתנו בענין אותו ואת בנו — דבר זה לא ייתכן לשיטתם, שהרי \u0003השתא\u0004 \u0005[עכשיו],\u0006 \u0003ומה התם\u0004 \u0005[שם]\u0006 ששחט תחילה אותה ואת בת בתה ואחר כך שחט בתה, שיש \u0003גופין\u0004 (בעלי חיים) \u0003מוחלקין\u0004 — \u0003פטרי רבנן\u0004 \u0005[פוטרים חכמים]\u0006 משתי מלקיות, \u0003הכא\u0004 \u0005[כאן],\u0006 בגיד הנשה, שאין מדובר בשני בעלי חיים שונים — \u0003לא כל שכן\u0004 שאינו חייב אלא אחת? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003סומכוס היא?\u0004 ומכאן, שלדעתו, האוכל פעמיים אותו דבר איסור, כגון שני זיתי חלב, בהתראה אחת — לוקה פעמיים!","ודוחים: \u0003לא, לעולם\u0004 תפרש שאכל מגיד של ירך ימין ומגיד של ירך שמאל \u0003בזה אחר זה,\u0004 ובהתראות נפרדות, \u0003ורבנן\u0004 \u0005[ו\u0006שיטת \u0005חכמים]\u0006 החולקים במשנתנו על סומכוס היא. \u0003ו\u0004מה שהקשית: אם מדובר כשאכלם בזה אחר זה, מדוע מחייב ר' יהודה? והרי בכל פעם התראת ספק היא! על כך יש לומר כי \u0003האי תנא סבר לה כאידך תנא\u0004 \u0005[ותנא זה\u0006 ששנה את המשנה \u0005סבור בענין זה כתנא האחר]\u0006 בשיטתו של \u0003ר' יהודה,\u0004","\u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003התראת ספק שמה התראה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר בקרבן הפסח \u0003\"לא תותירו ממנו עד בקר והנותר ממנו עד בקר באש תשרופו\"\u0004 (שמות יב, י) —"],["\u0003בא הכתוב ליתן עשה\u0004 (\"והנותר ממנו עד בוקר באש תשרופו\") \u0003אחר לא תעשה\u0004 (\"ולא תותירו ממנו עד בוקר\"), \u0003לומר שאין לוקין עליו,\u0004 אלו \u0003דברי ר' יהודה.\u0004 ומכאן שאם לא כן היה לוקה משום \"לא תותירו\", למרות שהיא התראת ספק, שהרי צריך להתרות בו סמוך לעבירה, ובכל פעם שמתרים בו יכול הוא לומר שעדיין לילה הוא.","\u0003ר' יעקב אומר: לא מן השם הוא זה,\u0004 לא זה הוא הטעם, \u0003אלא משום דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003לאו שאין בו מעשה,\u0004 שדי שישב ולא יעשה דבר כדי שיעבור על \"לא תותירו\", \u0003וכל לאו שאין בו מעשה\u0004 — \u0003אין לוקין עליו.\u0004","ומציעים \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה על דעת סומכוס, ממה ששנינו בברייתא בענין איסור גיד הנשה: \u0003אכל שני גידין משתי ירכות משתי בהמות\u0004 שונות — \u0003סופג שמונים. ר' יהודה אומר: אינו סופג אלא ארבעים.\u0004 ויש לשאול: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאינו אוכלם יחד, אלא \u0003בזה אחר זה, ובשתי התראות\u0004 שונות — \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 ש\u0003אמר:\u0004 סופג \u0003ארבעים ותו לא\u0004 \u0005[ולא יותר]?\u0006 והרי עבר שתי עבירות נפרדות ובשתי התראות נפרדות! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר שאכלם \u0003בבת אחת ובחדא התראה\u0004 \u0005[ובהתראה אחת].\u0006","ומעתה יש לשאול: \u0003מאן תנא קמא\u0004 \u0005[מיהו התנא הראשון]\u0006 שלדעתו סופג שמונים? \u0003אילימא רבנן דפליגי עליה\u0004 \u0005[אם תאמר חכמים שחלקו על]\u0006 \u0003סומכוס\u0004 במשנתנו — דבר זה אינך יכול לומר, שהרי \u0003ומה התם\u0004 \u0005[שם],\u0006 כששחט פרה ובת בתה ואחר כך שחט את בתה, שיש \u0003גופין\u0004 (בעלי חיים) \u0003מוחלקין\u0004 שגורמים לעבירה הכפולה — \u0003פטרי רבנן\u0004 \u0005[פוטרים חכמים]\u0006 מללקות פעמיים, \u0003הכא\u0004 \u0005[כאן],\u0006 בשני גידים, שאינם גופים חלוקים — \u0003לא כל שכן\u0004 שלוקה אחת כשאכלם בבת אחת? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003סומכוס היא?\u0004 ומכאן שלדעתו, כל העובר עבירה כפולה בגוף אחד, כגון שאכל שני זיתי חלב בהעלם אחד — חייב שתיים!","ודוחים: \u0003לעולם\u0004 מדובר שאכל את שני הגידים \u0003בזה אחר זה,\u0004 ובשתי התראות נפרדות, ולכן סופג שמונים גם לדעת חכמים החולקים במשנתנו על סומכוס. \u0003ודקאמרת\u0004 \u0005[ומה שאמרת]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 שמחייב רק אחת? על כך יש להשיב: מדובר \u0003כגון דלית ביה\u0004 \u0005[שאין בו]\u0006 באחד מהם \u0003כזית,\u0004 ור' יהודה הולך בענין זה לשיטתו. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אכלו\u0004 את גיד הנשה \u0003ואין בו כזית\u0004 — \u0003חייב\u0004 מלקות, \u0003ר' יהודה אומר:\u0004 אינו חייב \u0003עד שיהא בו כזית.\u0004","\u0003בארבעה פרקים\u0004 (זמנים) \u0003בשנה,\u0004 שרגילים ישראל לעשות סעודות גדולות, וקונים בהמות לשחיטה בו ביום, \u0003המוכר בהמה לחבירו צריך להודיעו: אמה מכרתי\u0004 היום \u0003לשחוט,\u0004 כדי שלא ישחוט את הבת בו ביום, או: \u0003בתה מכרתי\u0004 היום \u0003לשחוט,\u0004 כדי שלא ישחוט את האם. \u0003ואלו הן: ערב יום טוב האחרון של חג\u0004 הסוכות, שמיני עצרת. \u0003וערב יום טוב הראשון של פסח, וערב עצרת, וערב ראש השנה. וכדברי ר' יוסי הגלילי\u0004 — \u0003אף ערב יום הכפורים בגליל.\u0004","\u0003אמר ר' יהודה: אימתי\u0004 המוכר פרה צריך להודיע — \u0003בזמן שאין לו ריוח\u0004 של זמן, שמכר את האם או הבת באותו יום, \u0003אבל\u0004 אם \u0003יש לו ריוח,\u0004 שמכר את האם או הבת אתמול — \u0003אין צריך להודיעו,\u0004 שכל הקונה — מן הסתם לשחוט בו ביום הוא קונה. \u0003ומודה ר' יהודה במוכר את האם לחתן, ואת הבת לכלה\u0004 — \u0003שצריך להודיעו,\u0004 למרות שלא מכרם באותו יום, שכן \u0003בידוע ששניהם שוחטין ביום אחד\u0004 לכבוד שמחת הנישואין המשותפת.","ומוסיפים: \u0003בארבעה פרקים אלו\u0004 ששנינו לעיל \u0003משחיטין את הטבח בעל כרחו,\u0004 מכריחים את השוחט לשחוט בהמה שיש לו, כיצד? \u0003אפילו שור שוה אלף דינרים ואין לו ללוקח\u0004 (לקונה) \u0003אלא דינר,\u0004 ואין שם אלא קונה זה, אם נתן לו את הדינר — \u0003כופין אותו לשחוט\u0004 ולתת לו בשר בשווי דינר; \u0003לפיכך, אם מת\u0004 השור קודם שחיטה — \u0003מת ללוקח,\u0004 והפסיד את הדינר שנתן. \u0003אבל בשאר ימות השנה אינו כן,\u0004 אלא כדי שיחשב השור כשלו לענין זה, צריך הקונה למשוך את השור לרשותו, וכל זמן שלא עשה כן — יכול הטבח לחזור בו. \u0003לפיכך, אם מת\u0004 קודם שחיטה — \u0003מת למוכר,\u0004 וצריך לתת לקונה את כספו.","על מה ששנינו במשנה שבארבעה פרקים בשנה מוטל על המוכר להודיע לקונה שמכר בו ביום את אמה או בתה של הפרה שהוא מוכר לו, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 משום כך אין חובה על הקונה לברר את הדבר, ולכן \u0003אם לא הודיעו\u0004 המוכר — \u0003הולך\u0004 הקונה \u0003ושוחט ואינו נמנע.\u0004","שנינו: \u0003אמר ר' יהודה אימתי\u0004 וכו'. ומודה ר' יהודה במוכר את האם לחתן ואת הבת לכלה שצריך להודיעו. ושואלים: \u0003למה לי למיתני\u0004 \u0005[לשנות]:\u0006 \u0003את האם לחתן ואת הבת לכלה?\u0004 שישנה: את זו לחתן ואת זו לכלה! ומשיבים: \u0003מלתא אגב אורחיה קמשמע לן\u0004 \u0005[דבר בדרך אגב משמיע לנו]:\u0006 \u0003דאורח ארעא למטרח בי חתנא טפי מבי כלתא\u0004 \u0005[שדרך ארץ לטרוח\u0006 לחתונה ב\u0005בית החתן יותר מבית הכלה],\u0006 ולכן חתן קונה את האם הגדולה, והכלה את הבת הקטנה.","שנינו: \u0003בארבעה פרקים אלו\u0004 משחיטין את הטבח בעל כורחו, לפיכך אם מת — מת ללוקח. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 עדיין \u0003לא משך\u0004 את הבהמה כדי לקנותה, ועדיין אינה שלו (למרות ששילם)! \u0003אמר רב הונא אמר רב:\u0004 מדובר במשנה \u0003כשמשך.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של המשנה: \u0003אבל בשאר ימות השנה אינו כן, לפיכך, אם מת\u0004 — \u0003מת למוכר.\u0004 ואם מדובר במשנה כשמשך, מדוע לא מת לקונה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003משך!\u0004","\u0003אמר ר' שמואל בר רב יצחק: לעולם\u0004 מדובר במשנה \u0003שלא משך\u0004 הקונה, \u0003ו\u0004מדובר \u0003כגון שזיכה לו\u0004 המוכר \u0003על ידי\u0004 אדם \u0003אחר,\u0004 שמסר לאותו אדם את השור כדי שיקנה בו בשר בשווי דינר עבור הקונה; \u0003בארבעה פרקים אלו\u0004 ש\u0003זכות הוא לו,\u0004 שהרי הוא רוצה שיהיה לו בשר לחג — חל הכלל ש\u0003זכין לאדם שלא בפניו,\u0004 ואולם \u0003בשאר ימות השנה,\u0004 ש\u0003חוב הוא לו,\u0004 שאין הוא רוצה להוציא הוצאות שאינו חייב בהם — הרי \u0003אין חבין לאדם שלא בפניו,\u0004 ולכן אם מת — מת למוכר.","\u0003ר' אלעזר אומר, אמר ר' יוחנן\u0004 הסבר אחר: \u0003בארבעה פרקים אלו העמידו חכמים דבריהם על דין תורה\u0004 שמעות קונות מיטלטלין, והמעות ששילם הקונה עבור הבשר קונות לו, ואין צורך במשיכה.","שכך \u0003אמר ר' יוחנן: דבר תורה\u0004 — \u0003מעות קונות\u0004 מיטלטלין בלא שימשוך, \u0003ומה טעם אמרו\u0004 חכמים: רק \u0003משיכה קונה\u0004 — \u0003גזירה שמא\u0004 לאחר שקיבל המוכר את המעות שוב לא ידאג לשלומם של המיטלטלין שמכר, ואם תאחז בהם אש — לא יטרח להצילם, ו\u0003יאמר לו\u0004 לקונה: \u0003נשרפו חטיך בעליה\u0004 ואין זה מענייני. ומשום שמחת יום טוב, החזירו חכמים את הדבר לדין תורה, ואמרו שהכסף ששילם הלוקח קונה לו, ומשחיטים את הטבח בעל כורחו.","\u0003\"יום אחד\" האמור באותו ואת בנו\u0004 (\"אותו ואת בנו לא תשחטו ביום אחד\". ויקרא כב, כח) — \u0003היום הולך אחר הלילה,\u0004 שאם שחט את האם בלילה — אסור לשחוט את בנה ביום המחרת. אבל אם שחט את האם ביום — יכול לשחוט את בנה בלילה שלאחריו. \u0003את זו דרש ר' שמעון בן זומא: נאמר במעשה בראשית \"יום אחד\"\u0004 (בראשית א, ה), \u0003ונאמר באותו ואת בנו \"יום אחד\", מה יום אחד האמור במעשה בראשית\u0004 — \u0003היום הולך אחר הלילה\u0004 שלפניו, שהרי נאמר: \"ויהי ערב ויהי בוקר יום אחד\", \u0003אף יום אחד האמור באותו ואת בנו\u0004 — \u0003היום הולך אחר הלילה\u0004 שלפניו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003את זו דרש ר' שמעון בן זומא: לפי שכל הענין כולו\u0004 שאיסור אותו ואת בנו כתוב בו, \u0003אינו מדבר אלא בקדשים, ובקדשים לילה הולך אחר היום, יכול אף זה כן?\u0004 לכך צריך ללימוד מיוחד, \u0003נאמר כאן: \"יום אחד\", ונאמר במעשה בראשית: \"יום אחד\", מה \"יום אחד\" האמור במעשה בראשית\u0004 — \u0003היום הולך אחר הלילה, אף יום האמור באותו ואת בנו\u0004 — \u0003היום הולך אחר הלילה.\u0004"],["\u0003רבי אומר:\u0004 מה שנאמר \"אותו ואת בנו לא תשחטו ב\u0003יום אחד\"\u0004 (ויקרא כב, כח), \"יום אחד\" רומז ליום מיוחד, וכתוב זה בא להדגיש: \u0003יום המיוחד טעון כרוז\u0004 כדי שלא ישחטו בו אותו ואת בנו. \u0003מכאן אמרו\u0004 חכמים במשנה: \u0003בארבעה פרקים\u0004 זמנים מיוחדים \u0003בשנה, המוכר בהמה לחבירו צריך להודיעו:\u0004 אמה מכרתי לשחוט, או: בתה מכרתי לשחוט.","","מצות \u0003כסוי הדם\u0004 לאחר שחיטה \u0003נוהג בארץ ובחוצה לארץ, בפני הבית\u0004 (כשבית המקדש קיים) \u0003ושלא בפני הבית,\u0004 ונוהג דווקא \u0003בחולין אבל לא במוקדשין. ונוהג בחיה ובעוף,\u0004 אבל לא בבהמה. ונוהג בין \u0003במזומן\u0004 לו בביתו, \u0003ו\u0004בין \u0003בשאינו מזומן,\u0004 אלא ניצוד בשדה. \u0003ונוהג ב\u0004בעל החיים הקרוי \u0003כוי, מפני שהוא ספק\u0004 בהמה ספק חיה.","\u0003ואין שוחטין אותו\u0004 את הכוי \u0003ביום טוב,\u0004 מפני שכיסוי הדם כרוך באיסור מלאכה, ולא הותר הדבר אלא כשהיא מצוה ודאית, ולא בספק. \u0003ו\u0004גם בדיעבד, \u0003אם שחטו\u0004 את הכוי ביום טוב — \u0003אין מכסין את דמו\u0004 עד למוצאי יום טוב.","ושואלים: \u0003מוקדשין,\u0004 קרבנות העוף, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 חייב לכסות את דמם? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 דבריו של \u0003ר' זירא,\u0004 ש\u0003אמר ר' זירא: השוחט\u0004 חיה או עוף \u0003צריך שיתן\u0004 תחילה \u0003עפר למטה\u0004 וישחט עליו, \u0003ו\u0004אחר כך יתן \u0003עפר למעלה, שנאמר: \"ושפך את דמו וכסהו בעפר\"\u0004 (ויקרא יז, יג), \"וכסהו \u0003עפר\" לא נאמר, אלא:\u0004 \"וכסהו \u0003בעפר\",\u0004 שיהא מכוסה מכל צדדיו בעפר — \u0003מלמד שהשוחט צריך שיתן עפר למטה ועפר למעלה;\u0004","\u0003והכא\u0004 \u0005[וכאן],\u0006 בקרבן העוף, הרי \u0003לא אפשר\u0004 הדבר, שכן \u0003היכי ליעביד\u0004 \u0005[כיצד יעשה]?\u0006 אם תאמר: לאחר שהיזה מדם העוף על המזבח \u0003ליתיב וליבטליה\u0004 \u0005[יתן עפר ויבטלנו]\u0006 את העפר למזבח, שיהא מונח שם לעולם — הלא בכך \u0003קמוסיף אבנין\u0004 \u0005[הריהו מוסיף על הבנין],\u0006 \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 על בנין המקדש: \u0003\"הכל בכתב מיד ה' עלי השכיל\"\u0004 (דברי הימים א א, כח), לומר שהכל נעשה על פי נבואה, ולא ניתן להוסיף על הבנין!","אם תאמר: \u0003לא ליבטליה\u0004 \u0005[\u0006ש\u0005לא יבטלנו\u0006 את העפר\u0005]\u0006 — \u0003קא הוי\u0004 \u0005[הריהו]\u0006 \u0003חציצה\u0004 בין דם העוף למזבח.","וכיון שלא ניתן לתת עפר למטה אמרה המשנה שכיסוי הדם אינו נוהג בקדשים — טעם זה אינו מספיק, שכן \u0003נהי\u0004 \u0005[גם אם אמנם]\u0006 לתת עפר \u0003למטה\u0004 קודם המליקה \u0003לא אפשר,\u0004 מכל מקום לתת עפר \u0003למעלה\u0004 אחרי המליקה — \u0003אפשר,\u0004 ואם כן \u0003ליעביד\u0004 \u0005[שיעשה]\u0006 \u0003כסוי\u0004 על כל פנים מלמעלה!","\u0003מי לא תניא\u0004 \u0005[האם לא שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יונתן בן יוסף אומר: שחט חיה ואחר כך שחט בהמה\u0004 באותו מקום, ונתכסה דם החיה בדם הבהמה — \u0003פטור מלכסות,\u0004 שהרי הוא מכוסה. אבל אם שחט \u0003בהמה ואחר כך\u0004 שחט \u0003חיה\u0004 — \u0003חייב לכסות\u0004 את דם החיה מלמעלה, למרות שאינו מכוסה מלמטה בעפר, אלא בדם החיה! ומשיבים: טעם הדבר שכאן אין לומר כן, הוא \u0003כ\u0004דברי \u0003ר' זירא,\u0004 ש\u0003אמר ר' זירא\u0004 על מצות הבלילה של הסולת והשמן שבמנחות: \u0003כל הראוי\u0004 מצד עצמו \u0003לבילה\u0004 (לבלילה) — \u0003אין\u0004 מצות \u0003בילה מעכבת בו\u0004 בדיעבד, וגם אם לא בלל — כשר, \u0003וכל שאינו\u0004 \u0003ראוי\u0004 כלל \u0003לבילה\u0004 — \u0003בילה מעכבת בו.\u0004 ולענייננו, כששחט בהמה ואחר כך חיה, הואיל וניתן היה לכסות את דם הבהמה בעפר ולשחוט עליו את החיה, הרי גם אם לא עשה כן — אין זה מעכב. אבל בקדשים, הואיל ואינו יכול בשום אופן ליתן עפר למטה, מפני שהוא כמוסיף על הבנין — הרי זה מעכב את הכיסוי.","","ושואלים: ועדיין, מדוע אינו יכול לקיים כיסוי הדם בקדשים? \u0003וליגרריה וליכסיה\u0004 \u0005[ושיגרר,\u0006 יגרד את הדם מן המזבח, \u0005ויכסה אותו]!\u0006 \u0003מי לא תנן\u0004 \u0005[האם לא שנינו]:\u0006 \u0003דם\u0004 חיה ועוף \u0003הניתז\u0004 רחוק ממקום השחיטה, \u0003ו\u0004כן הדם \u0003ש\u0004נותר \u0003על הסכין\u0004 — \u0003חייב לכסות. אלמא דגריר ומכסי ליה\u0004 \u0005[מכאן שיכול לגרר\u0006 את הדם \u0005ולכסות אותו]\u0006 במקום אחר. ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בדם קדשים, \u0003נגרור ונכסי ליה\u0004 \u0005[שיגרר את הדם\u0006 מן המזבח \u0005ויכסה אותו]\u0006 במקום אחר!","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 היה מדובר \u0003בקדשי מזבח\u0004 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יכול היה לעשות. אבל \u0003הכא\u0004 \u0005[כאן],\u0006 ששנינו במשנתנו שכיסוי הדם אינו נוהג במוקדשים, \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003בקדשי בדק הבית,\u0004 בעופות שהוקדשו למקדש כדי למוכרם ולהשתמש בדמיהם לבדק הבית, שאסור לשחוט אותם, ואם נשחטו הריהם אסורים בהנאה. ולדעת משנתנו, שחיטה שאינה ראויה לאכילה פטורה מכיסוי."],["ושואלים: וגם אם מדובר בקדשי בדק הבית, מדוע אין כיסוי הדם נוהג בהם? \u0003וליפרקינהו וליכסינהו\u0004 \u0005[ושיפדו אותם ויכסו אותם,\u0006 את דמם]! ומשיבים: לא ניתן לפדות בעל חיים שכבר נשחט, מפני ש\u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003העמדה והערכה\u0004 כדי לפדותו, כלשון הכתוב \"והעמיד... והעריך\" (ויקרא כז, יז), וכשהוא מת לא ניתן להעמידו, וממילא לא ניתן לפדותו.","ושואלים: \u0003ו\u0004לדרך זו, שמדובר במשנתנו בקדשי בדק הבית, \u0003כמאן\u0004 \u0005[וכ\u0006שיטת \u0005מי]\u0006 היא שנויה? \u0003אי\u0004 \u0005[אם]\u0006 תאמר \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 ש\u0003אמר: הכל,\u0004 גם קדשי מזבח וגם קדשי בדק הבית, \u0003היו בכלל\u0004 דין \u0003העמדה והערכה,\u0004 ולכן לא ניתן לפדותם ולכסות את דמם — \u0003האמר\u0004 \u0005[הרי\u0006 מצד אחר הוא \u0005אומר]:\u0006 \u0003שחיטה שאינה ראויה\u0004 לאכילה — \u0003שמה שחיטה,\u0004 לחייב בכיסוי הדם. ואם כן, גם אם לא נפדו — דמם חייב בכיסוי!","\u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 ש\u0003אמר: שחיטה שאינה ראויה לא שמה שחיטה\u0004 — \u0003האמר\u0004 \u0005[הרי הוא אומר]:\u0006 קדשי בדק הבית \u0003לא היו בכלל העמדה והערכה,\u0004 ואם כן ניתן לפדותם לאחר שחיטה, ולכסות את דמם!","\u0003אמר רב יוסף:\u0004 משנתנו שיטת \u0003רבי היא, ונסיב לה אליבא דתנאי\u0004 \u0005[\u0006והוא \u0005מביא,\u0006 שונה \u0005אותה לפי שיטת\u0006 שני \u0005תנאים]\u0006 שונים; \u0003ב\u0004ענין \u0003שחיטה שאינה ראויה סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' שמעון,\u0004 שאינה שחיטה, ואילו \u0003ב\u0004ענין \u0003העמדה והערכה\u0004 — \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' מאיר,\u0004 שגם קדשי מזבח וגם קדשי בדק הבית צריכים העמדה והערכה. וכיון שלא ניתן לפדותם לאחר שחיטה, נמצא ששחיטתם אינה ראויה, ואינה מחייבת בכיסוי הדם.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 משנתנו \u0003כולה\u0004 שיטת \u0003ר' שמעון היא,\u0004 הסבור שניתן לפדות את קדשי בדק הבית. ואם כן לכאורה, שחיטתם שחיטה ראויה היא, \u0003ו\u0004אולם \u0003שאני הכא דאמר קרא\u0004 \u0005[שונה כאן שאמר הכתוב]\u0006 ברצף אחד: \u0003\"ושפך וכסה\"\u0004 (\"ושפך את דמו וכסהו בעפר\". ויקרא יז, יג), לומר: באיזה דם מדובר — ב\u0003מי שאינו מחוסר אלא שפיכה וכסוי, יצא זה,\u0004 דם קדשי בדק הבית, \u0003ש\u0004הוא \u0003מחוסר\u0004 גם \u0003שפיכה\u0004 גם \u0003פדייה ו\u0004גם \u0003כסוי.\u0004","ומעירים: \u0003והשתא דאתית להכי\u0004 \u0005[עכשיו שבאת לכך],\u0006 שאתה מציע טעם זה, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר במשנתנו ב\u0003קדשי מזבח,\u0004 יש להסביר שאינם חייבים בכיסוי מטעם זה עצמו, שנאמר: \"ושפך וכסה\" — \u0003מי שאינו מחוסר אלא שפיכה וכסוי, יצא זה,\u0004 דם של עוף קדשים, \u0003שמחוסר\u0004 גם \u0003שפיכה,\u0004 גם \u0003גרירה\u0004 של הדם מעל המזבח, \u0003ו\u0004גם \u0003כסוי.\u0004","\u0003מר בר רב אשי אמר:\u0004 מנין שכיסוי הדם אינו נוהג במוקדשים? ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין כיסוי הדם \u0003\"חיה או עוף\",\u0004 ויש להשוותם זה לזה: \u0003מה חיה אינה קדש,\u0004 שאין מקריבים חיה לקרבן — \u0003אף עוף\u0004 שחייבים בכיסוי דמו הוא דווקא זה ש\u0003אינו קדש,\u0004 שרק דם של עוף חולין חייב בכיסוי.","ויש לשאול, \u0003אי\u0004 \u0005[אם]\u0006 כך, שאתה למד מחיה לעוף, שמא נאמר: \u0003מה חיה\u0004 — מדובר בדבר \u0003שאין במינו קדש, אף עוף\u0004 — רק דבר \u0003שאין במינו קדש\u0004 חייב בכיסוי, \u0003אוציא תורין ובני יונה\u0004 מדין כיסוי הדם, ואפילו הם חולין, \u0003ש\u0004הרי \u0003יש במינן קדש!\u0004","ודוחים: \u0003לא,\u0004 הואיל והוקש דינו של עוף לדינה של חיה, דינו לגמרי \u0003כ\u0004של \u0003חיה; מה חיה\u0004 — \u0003לא חלקת בה\u0004 בין מין זה למין אחר לענין כיסוי, \u0003אף עוף\u0004 — \u0003לא תחלוק בו\u0004 בין מין זה למין אחר.","ובטעם הדבר שכיסוי הדם נוהג בחיה ולא בבהמה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003יעקב מינאה\u0004 \u0005[המין]\u0006 \u0003לרבא: קיימא לן\u0004 \u0005[מוחזק בידינו]\u0006 ש\u0003חיה,\u0004 כגון צבי, היא \u0003בכלל בהמה\u0004 שהזכיר הכתוב \u0003ל\u0004ענין \u0003סימנין,\u0004 שתהא מעלה גרה ושוסעת פרסה (דברים יד, ד—ו), ואם כן, \u0003אימא נמי\u0004 \u0005[אמור גם כן]\u0006 להיפך, ש\u0003בהמה\u0004 היא \u0003בכלל חיה\u0004 \u0003ל\u0004ענין \u0003כסוי\u0004 הדם (ויקרא יז, יג)!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עליך,\u0004 על טענתך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 ביחס לדם הבהמה: \"וזבחת מבקרך ומצאנך... רק חזק לבלתי אכול הדם... \u0003על הארץ תשפכנו כמים\"\u0004 (דברים יב, כא—כד), ומן ההשוואה של דם הבהמה למים, יש ללמוד: \u0003מה מים לא בעי\u0004 \u0005[אינם צריכים]\u0006 \u0003כסוי, אף האי נמי\u0004 \u0005[זה גם כן,\u0006 דם בהמה\u0005]\u0006 \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003כסוי.\u0004","ושואלים: \u0003אלא מעתה,\u0004 שהכתוב משוה את דין דם הבהמה לדין מים, \u0003יטבילו בו\u0004 את הטמאים לטהרם, כמו במים! ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אך מעין ובור מקוה מים יהיה טהור\"\u0004 (ויקרא יא, לו), כלומר, יטהר את הטמאים. ולשון \"אך\" באה למעט: \u0003הני אין\u0004 \u0005[אלה כן]\u0006 מטהרים, \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 \u0003לא.\u0004","ושואלים, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלו\u0006 נאמרו\u0005]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שאר משקין, דלא איקרו\u0004 \u0005[שאינם קרויים]\u0006 \u0003מים, אבל דם דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003מים,\u0004 שנאמר: \"על הארץ תשפכנו כמים\" — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יטבילו בו!","ומשיבים: \u0003תרי מיעוטי כתיבי\u0004 \u0005[שני מיעוטים כתובים]:\u0006 \u0003\"מעין מים\" \"ובור מים\",\u0004 למעט גם שאר משקים וגם דם.","ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003אידי ואידי למעוטי\u0004 \u0005[זה וזה למעט]\u0006 \u0003שאר משקין, חד למעוטי\u0004 \u0005[אחד למעט]\u0006 ולומר שאינם מטהרים כמעין כשהם \u0003זוחלין, וחד למעוטי\u0004 \u0005[ואחד למעט]\u0006 שאינם מטהרים כבור ומקוה כשהם \u0003מכונסין!\u0004","ומשיבים, \u0003תלתא מיעוטי כתיבי\u0004 \u0005[שלושה מיעוטים כתובים]:\u0006 \u0003\"מעין מים\"\u0004 — למעט שאר משקים זוחלים, \u0003\"ובור מים\"\u0004 — למעט שאר משקים מכונסים, \u0003\"מקוה מים\"\u0004 — למעט דם הקרוי מים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר במצות כיסוי הדם: \"ואיש... אשר יצוד ציד חיה או עוף אשר יאכל ושפך את דמו וכסהו בעפר\" (ויקרא יז, יג). ומ\u0003\"אשר יצוד\", אין לי\u0004 ללמוד \u0003אלא\u0004 חיה ועוף \u0003אשר יצוד,\u0004 חיה ועוף ה\u0003נצודין ועומדין מאליהן\u0004 (שאין צורך לצודם) \u0003מנין\u0004 שצריך לכסות את דמם. ו\u0003כגון אווזין ותרנגולים?\u0004","\u0003תלמוד לומר: \"ציד\", מכל מקום. אם כן, מה תלמוד לומר \"אשר יצוד\"?\u0004 מדוע השתמשה התורה בלשון זו? \u0003למדה תורה\u0004 אגב כך \u0003דרך ארץ, שלא יאכל אדם בשר\u0004 תדיר, \u0003אלא בהזמנה\u0004 (בהכנה) \u0003הזאת,\u0004 כאדם שצריך לטרוח ולצוד ציד, ואין הבשר מזומן לו בביתו.","וכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 במה שאמר הכתוב \u0003\"כי ירחיב ה' אלהיך את גבולך...\u0004 בכל אות נפשך תאכל בשר\" (דברים יב, כ) — \u0003למדה תורה דרך ארץ, שלא יאכל אדם בשר אלא לתאבון,\u0004 כשגופו ונפשו זקוקים לכך, ולא דרך גרגרנות. ועוד בענין זה.","\u0003יכול יקח\u0004 (יקנה) \u0003אדם\u0004 בשר \u0003מן השוק ויאכל? תלמוד לומר: \"וזבחת מבקרך ומצאנך\"\u0004 (שם כא) — משלך ולא משל אחרים. \u0003יכול יזבח\u0004 (ישחט) \u0003כל בקרו ויאכל,\u0004 או \u0003כל צאנו ויאכל? תלמוד לומר: \"מבקרך\"\u0004 — \u0003ולא כל בקרך, \"מצאנך\"\u0004 — \u0003ולא כל צאנך.\u0004","\u0003מכאן אמר ר' אלעזר בן עזריה: מי שיש לו מנה\u0004 (מאה דינרים) — \u0003יקח לפסו\u0004 (לקדירתו), \u0003ליטרא ירק,\u0004 מי שיש לו \u0003עשרה מנה\u0004 — \u0003יקח לפסו ליטרא דגים, חמשים מנה\u0004 — \u0003יקח לפסו ליטרא בשר, מאה מנה\u0004 — \u0003ישפתו לו קדרה\u0004 של בשר על הכירה \u0003בכל יום.\u0004 ושואלים: \u0003ואינך אימת\u0004 \u0005[ואלו\u0006 ששנה קודם, \u0005מתי,\u0006 כל כמה זמן\u0005]\u0006 יאכלו בשר? ומשיבים: \u0003מערב שבת לערב שבת.\u0004","\u0003אמר רב: צריכין אנו לחוש לדברי זקן,\u0004 ר' אלעזר בן עזריה, ולהסתפק במזונות קלים, ולמעט בהוצאות על מאכל. \u0003אמר ר' יוחנן: אבא\u0004 (כך קרא לרב שאמר כן) \u0003ממשפחת\u0004 אנשים \u0003בריאים הוה\u0004 \u0005[היה],\u0006 \u0003אבל כגון אנו,\u0004 שאיננו בריאים, \u0003מי שיש לו\u0004 אפילו \u0003פרוטה בתוך כיסו\u0004 — \u0003יריצנה לחנווני,\u0004 ויקנה דברי מאכל כראוי לו. \u0003אמר רב נחמן,\u0004 שני דורות מאוחר יותר: אנשים \u0003כגון אנו,\u0004 שנחלשנו יותר, לא רק כשיש לנו פרוטה בכיסנו צריכים אנו ללכת ולקנות מאכל, אלא אפילו \u0003לווין ואוכלין.\u0004 ועוד בעניינים שידאג בהם אדם לפרנסתו, מביאים מה שדרשו חכמים על הכתוב: \"כבשים ללבושך ומחיר שדה עתודים. ודי חלב עזים ללחמך ללחם ביתך וחיים לנערותיך\" (משלי כז, כו—כז).","\u0003\"כבשים ללבושך\"\u0004 — \u0003מגז כבשים יהא מלבושך,\u0004 קנה לך צאן, ומצמרו עשה לך בגדים. \u0003\"ומחיר שדה עתודים\"\u0004 — \u0003לעולם ימכור אדם שדה ויקח עתודים\u0004 (כבשים), שיוכל ליהנות מחלבם ומצמרם ומוולדותיהם, \u0003ואל ימכור אדם עתודים ויקח שדה. \"ודי חלב עזים\"\u0004 — \u0003דיו לאדם שיתפרנס מחלב גדיים וטלאים שבתוך ביתו.\u0004","\u0003\"ללחמך ללחם ביתך\"\u0004 — \u0003לחמך קודם ללחם ביתך. \"וחיים לנערותיך\"\u0004 — \u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן: תן חיים לנערותיך,\u0004 לבני ביתך הצעירים, \u0003מיכן למדה תורה דרך ארץ שלא ילמד\u0004 (ירגיל) \u0003אדם את בנו\u0004 באכילת \u0003בשר ו\u0004שתיית \u0003יין,\u0004 שגורם בכך להוציאו מדרכי חיים.","\u0003אמר רבי יוחנן:\u0004"],["\u0003הרוצה שיתעשר\u0004 \u0003יעסוק בבהמה דקה.\u0004 וכן \u0003אמר רב חסדא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ועשתרות צאנך\"\u0004 (דברים ז, יג) \u0003ש\u0004הן \u0003מעשרות את בעליהן. ו\u0004עוד","\u0003אמר ר' יוחנן\u0004 בהדרכה לדרך החיים הראויה: מוטב לו לאדם לשתות \u0003כסא דחרשין\u0004 \u0005[כוס של מכשפים,\u0006 שעשו בה כישוף\u0005]\u0006 \u0003ולא כסא דפושרין\u0004 \u0005[כוס של\u0006 מים \u0005פושרים],\u0006 שיש בכך סכנה גדולה יותר. ומוסיפים: \u0003והני מילי\u0004 \u0005[ודברים אלה אמורים]\u0006 \u0003בכלי מתכות, אבל בכלי חרש\u0004 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה,\u0004 אין לחשוש לדבר. \u0003ובכלי מתכות נמי לא אמרן\u0004 \u0005[גם כן לא אמרנו],\u0006 \u0003אלא\u0004 במקרה \u0003דלא שדי בהו ציביא\u0004 \u0005[שלא הטיל לתוכם עשבים],\u0006 כמו תה, \u0003אבל שדי בהו ציביא\u0004 \u0005[הטיל לתוכם עשבים]\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש. \u0003וכי לא שדי בהו ציביא נמי לא אמרן\u0004 \u0005[וכאשר לא הטיל לתוכם עשבים גם כן לא אמרנו]\u0006 שיש בהם סכנה, \u0003אלא\u0004 במקרה ש\u0003לא ציץ\u0004 \u0005[רתחו]\u0006 המים, \u0003אבל ציץ\u0004 \u0005[רתחו]\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש.","\u0003ו\u0004עוד \u0003אמר ר' יוחנן: מי שהניח לו אביו מעות\u0004 בירושה \u0003ורוצה לאבדן\u0004 — \u0003ילבש כלי פשתן, וישתמש בכלי זכוכית, וישכור פועלים ואל ישב עמהן.\u0004 ומפרשים: \u0003ילבוש כלי פשתן\u0004 — \u0003בכיתנא רומיתא\u0004 \u0005[בפשתן רומאי],\u0006 שהוא יקר ועדין, \u0003וישתמש בכלי זכוכית\u0004 — \u0003בזוגיתא חיורתא\u0004 \u0005[בזכוכית לבנה],\u0006 \u0003וישכור פועלים ואל ישב עמהן\u0004 \u0003בתורי, דנפיש פסידייהו\u0004 \u0005[בשוורים, שמרובה הפסדם],\u0006 שאם אין משגיחים על הפועלים החורשים בשוורים אינם חוששים לחבלות שייגרמו לשוורים, ואינם מעמיקים את המחרישה כראוי.","ועוד בענייני פרנסה \u0003דרש רב עוירא, זימנין\u0004 \u0005[פעמים]\u0006 \u0003אמר לה משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אמי, וזימנין\u0004 \u0005[ופעמים]\u0006 \u0003אמר לה משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אסי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"טוב איש חונן ומלוה יכלכל דבריו במשפט\"\u0004 (תהלים קיב, ה)? \u0003לעולם יאכל אדם וישתה\u0004 ב\u0003פחות ממה שיש לו,\u0004 שלא יפנק עצמו למרות שיש לו יכולת כלכלית גבוהה, \u0003ו\u0004אולם \u0003ילבש ויתכסה במה שיש לו,\u0004 לפי יכולתו, כדי שלא יתבזה. \u0003ויכבד אשתו ובניו יותר ממה שיש לו,\u0004 שילוה מאחרים לשם כך, מפני \u0003שהן תלויין בו, והוא תלוי במי שאמר והיה העולם.\u0004","שנינו במשנה שאין שוחטים את הכוי ביום טוב, מפני שהוא ספק חיה ספק בהמה, שאם היה ודאי חיה היה צריך בכיסוי הדם, ואולם מאחר שהוא ספק — אין מחללים את יום טוב מחמת הספק. ואם שחטו — אין מכסים את דמו. ובענין זה מסופר, \u0003דרש רב עינא\u0004 ברבים \u0003אפתחא דבי ריש גלותא\u0004 \u0005[על פתח בית ראש הגולה]:\u0006 \u0003השוחט\u0004 חיה או עוף \u0003לחולה\u0004 מסוכן \u0003בשבת,\u0004 \u0003חייב לכסות\u0004 את דמו. \u0003אמר\u0004 \u0003להו\u0004 \u0005[להם]\u0006 \u0003רבה: אשתומא קאמר, לישמטוה לאמוריה מיניה\u0004 \u0005[דבר תמוה הוא אומר, שיורידו את המתורגמן שלו ממנו],\u0006 המשמיע את דבריו לרבים. ומנין שאמר שלא כראוי? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0005ר' יוסי אומר: כוי אין שוחטין אותו ביום טוב, ואם שחטו\u0006 \u0003אין מכסין את דמו,\u0004","\u0003מקל וחומר: ומה מילה שודאה דוחה שבת,\u0004 \u0003אין ספיקה דוחה יום טוב,\u0004 שתינוק שספק אם יומו השמיני חל ביום טוב — אסור למולו, \u0003כסוי\u0004 הדם \u0003שאין ודאו דוחה שבת\u0004 \u0003אין דין,\u0004 לא קל וחומר הוא \u0003שאין ספקו,\u0004 כגון כיסוי דם הכוי, שהוא ספק חיה ספק בהמה, \u0003דוחה יום טוב?\u0004","\u0003אמר\u0004 (אמרו) \u0003לו: תקיעת שופר\u0004 בראש השנה \u0003בגבולים\u0004 (מחוץ למקדש) \u0003תוכיח, שאין ודאה דוחה שבת,\u0004 שאם חל ראש השנה בשבת — אסור לתקוע בשופר מחוץ למקדש, \u0003ו\u0004מכל מקום \u0003ספיקה דוחה יום טוב!\u0004","וכן \u0003השיב ר' אלעזר הקפר בריבי\u0004 (הגדול) \u0003תשובה\u0004 לקל וחומר של ר' יוסי: אין להוכיח ממילה שאין ספיקה דוחה יום טוב, לכיסוי הדם, שגם ספיקו לא ידחה יום טוב, שהרי \u0003מה למילה שכן אינה נוהגת בלילי ימים טובים,\u0004 שמילה נוהגת ביום ולא בלילה, \u0003תאמר בכסוי\u0004 הדם \u0003שנוהג בלילי ימים טובים,\u0004 שהשוחט חיה בליל יום טוב צריך לכסות את דמה!","ועל דברי ר' אלעזר הקפר \u0003אמר רבי אבא:\u0004 אותו קל וחומר ממנו למד ר' יוסי שאין מכסים דמו של כוי ביום טוב, \u0003זה אחד מן הדברים שאמר\u0004 עליהם \u0003ר' חייא: אין לי עליהם תשובה, והשיב ר' אלעזר הקפר בריבי\u0004 (הגדול) \u0003תשובה\u0004 עליו.","\u0003קתני מיהת\u0004 \u0005[הריהו שונה על כל פנים]\u0006 בברייתא: \u0003כסוי\u0004 הדם \u0003שאין ודאו דוחה שבת.\u0004 ויש לשאול: \u0003מאי ודאו דכסוי דלא דחי שבת\u0004 \u0005[מהו ודאו של כיסוי שאינו דוחה שבת]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003השוחט\u0004 חיה או עוף \u0003לחולה בשבת,\u0004 שאין מכסים את דמו? ומכאן קושיה לדברי רב עינא, שאמר שהוא חייב בכיסוי!","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אין מדובר בברייתא בשוחט לחולה, ששם יש מקום לומר שכיון שנדחתה השבת אצל שחיטה זו נדחתה גם אצל כיסוי. אלא מדובר במקרה ש\u0003עבר ושחט\u0004 בשבת באיסור!","ודוחים: אינך יכול לפרש כן, מפני שצריך אתה לפרש כיסוי הדם שבברייתא זו \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מילה,\u0004 שממנה הוכיח ר' יוסי, \u0003מה מילה\u0004 \u0003ברשות,\u0004 שמצוה למול בשבת — \u0003אף כסוי\u0004 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003ברשות,\u0004 בשוחט לחולה בהיתר, ואם כן הקושיה על רב עינא עומדת בעינה.","ודנים במה ש\u0003אמרו לו\u0004 לר' יוסי: \u0003תקיעת שופר בגבולין תוכיח, שאין ודאה דוחה שבת, וספיקה דוחה יום טוב.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003ספיקה\u0004 של תקיעה שדוחה יום טוב? \u0003אילימא\u0004 \u0005[אם תאמר]:\u0006 כגון שהיה אותו ראש השנה \u0003ספק חול ספק יום טוב\u0004 — לא ניתן לפרש כן, שכן \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ודאי יום טוב דחיא\u0004 \u0005[\u0006התקיעה \u0005דוחה],\u0006 \u0003ספק יום טוב ספק חול מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהיא דוחה? ואין מכאן הוכחה לכיסוי דם הכוי, שספק מצוה שבו ידחה ודאי יום טוב!"],["\u0003אלא\u0004 צריך אתה לומר שמדובר ב\u0003ספק איש ספק אשה,\u0004 כגון טומטום, וביום טוב ודאי. שלמרות שאשה פטורה מתקיעת שופר, טומטום שהוא ספק איש ספק אישה — חייב בתקיעת שופר. ומכאן יש ללמוד שגם כוי, שהוא ספק בהמה ספק חיה — טעון כיסוי ביום טוב.","ומעירים: \u0003ור' יוסי\u0004 אינו מקבל הוכחה זאת, שהוא הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: אשה ודאית נמי תקעה\u0004 \u0005[גם כן תוקעת\u0006 ביום טוב\u0005].\u0006 ומניין? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 ממה שנאמר בפרשת קרבן העולה: \"דבר אל בני ישראל... וסמך ידו על ראש העולה\" (ויקרא א— ד), יש לדייק: \u0003בני ישראל סומכין\u0004 על קרבנם, \u0003ולא בנות ישראל סומכות.\u0004","\u0003ר' יוסי ור' שמעון אומרים: נשים סומכות רשות,\u0004 כלומר, רשות בידן לסמוך, למרות שאינן מצוות בכך, ולמרות שיש בסמיכה ללא צורך משום איסור עבודה בקדשים, שהרי הסומך נשען על הקרבן בכל כוחו. והוא הדין לתקיעת שופר, שלדעת ר' יוסי, למרות שאין אשה מצווה לתקוע בשופר — רשות בידה לתקוע, ואין בכך משום חילול יום טוב.","\u0003אמר רבינא: ולמאי דקאמרי רבנן\u0004 \u0005[ולמה שאמרו חכמים]\u0006 שספק איש ספק אשה תוקע ביום טוב, ומשם רצו להוכיח לכיסוי דם הכוי, שאף על פי שהוא ספק הריהו דוחה יום טוב — \u0003נמי אית ליה פירכא\u0004 \u0005[גם כן יש לו פירכה]:\u0006 \u0003מה לתקיעת שופר\u0004 שספקה דוחה יום טוב — \u0003שכן ודאה דוחה שבת במקדש,\u0004 שבמקדש היו תוקעים בראש השנה שחל בשבת, \u0003תאמר בכיסוי\u0004 הדם — \u0003דליתיה\u0004 \u0005[שאינו]\u0006 דוחה \u0003כלל\u0004 שבת!","ומביאים מה ש\u0003השיב ר' אלעזר הקפר בריבי\u0004 (הגדול) לדחות את הקל וחומר של ר' יוסי: \u0003מה למילה שכן אינה נוהגת בלילי ימים טובים,\u0004 תאמר בכיסוי הדם שנוהג בלילי ימים טובים? ותמהים, \u0003בלילי ימים טובים הוא דלא נהגא\u0004 \u0005[ש\u0006מילה \u0005אינה נוהגת],\u0006 \u0003בשאר לילי\u0004 \u0005[לילות]\u0006 \u0003נהגא\u0004 \u0005[נוהגת]?\u0006 והרי מילה נוהגת בכל מקרה רק ביום!","\u0003אלא\u0004 כך צריך להסביר: \u0003מה למילה\u0004 — \u0003שכן אינה נוהגת בלילות כבימים, תאמר בכסוי\u0004 — \u0003שנוהג בלילות כבימים!\u0004 ועל כך \u0003אמר ר' אבא: זה אחד מן הדברים שאמר [לי] ר' חייא\u0004 ש\u0003אין עליהן תשובה, והשיב ר' אלעזר [הקפר] ברבי תשובה.\u0004","\u0003השוחט\u0004 חיה או עוף \u0003ונמצאת\u0004 שהיתה \u0003טריפה\u0004 כשנשחטה, \u0003ו\u0004כן \u0003השוחט לעבודה זרה, והשוחט חולין בפנים,\u0004 או \u0003קדשים בחוץ,\u0004 או השוחט \u0003חיה ועוף הנסקלים,\u0004 שנגמר דינם לסקילה, כגון שהרגו אדם, שכל אלו אסורים בהנאה — \u0003ר' מאיר מחייב\u0004 בכיסוי הדם, \u0003וחכמים פוטרים,\u0004 מפני שלדעתם שחיטה שאינה ראויה לאכילה — אינה שחיטה, ופטורה מכיסוי.","אבל \u0003השוחט\u0004 חיה (או עוף) \u0003ונתנבלה בידו,\u0004 שנתקלקלה השחיטה ונעשתה נבילה. וכן \u0003הנוחר\u0004 (הדוקר) \u0003והמעקר\u0004 את הקנה והוושט, וכך הורג את בעל החיים — \u0003פטור מלכסות\u0004 גם לדעת ר' מאיר, מפני שלא היתה שם כלל שחיטה, ורק שחיטה מחייבת כיסוי.","בענין המחלוקת במשנתנו, האם שחיטה שאינה ראויה לאכילה נחשבת שחיטה לחייבה בכיסוי הדם, \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: ראה רבי\u0004 יהודה הנשיא, עורך ומסדר המשנה, את \u0003דבריו של ר' מאיר,\u0004 הסבור ששחיטה שאינה ראויה שמה שחיטה, \u0003ב\u0004דין \u0003אותו ואת בנו,\u0004 \u0003ושנאו בלשון חכמים,\u0004 שלדעת סתם משנה שם חייב על שחיטת טריפה משום אותו ואת בנו. \u0003ו\u0004ראה דבריו של \u0003ר' שמעון,\u0004 הסבור ששחיטה שאינה ראויה לאכילה אינה שחיטה, \u0003בכסוי הדם,\u0004 \u0003ושנאו\u0004 במשנתנו \u0003בלשון חכמים,\u0004 שלדעת סתם משנה שחיטה כזו פטורה מכיסוי הדם.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ר' מאיר באותו ואת בנו? אמר ר' יהושע \u0003בן לוי: גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003שחיטה שחיטה משחוטי חוץ,\u0004 שבשחיטת חוץ נאמר: \"אשר ישחט מחוץ למחנה\" (ויקרא יז, ג), ובאותו ואת בנו נאמר: \"אותו ואת בנו לא תשחטו ביום אחד\" (שם כב, כח),","\u0003מה התם\u0004 \u0005[שם],\u0006 בשחיטת חוץ — \u0003שחיטה שאינה ראויה\u0004 לאכילה \u0003שמה שחיטה,\u0004 שמתחייב על השחיטה, למרות שהקדשים שנשחטו נאסרו בהנאה, \u0003אף הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לענין אותו ואת בנו — \u0003שחיטה שאינה ראויה שמה שחיטה\u0004 להתחייב עליה.","ושואלים: \u0003ור' שמעון, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 מהיכן הוא למד שרק שחיטה הראויה לאכילה קרויה שחיטה לענין אותו ואת בנו? \u0003אמר ר' מני בר פטיש: גמר\u0004 \u0005[למד]\u0006 \u0003מ\"טבוח טבח והכן\u0004 כי אתי יאכלו האנשים\" (בראשית מג, טז), \u0003מה להלן\u0004 שנאמרה טביחה (שחיטה) — מדובר ב\u0003שחיטה ראויה\u0004 לאכילה, \u0003אף כאן\u0004 לענין אותו ואת בנו — רק \u0003שחיטה ראויה\u0004 לאכילה קרויה שחיטה.","ושואלים: \u0003ור' מאיר נמי\u0004 \u0005[גם כן],\u0006 \u0003ליגמר\u0004 \u0005[שילמד]\u0006 \u0003מ\"טבוח\"\u0004 שרק שחיטה ראויה לאכילה שמה שחיטה! ומשיבים: לדעתו \u0003דנין שחיטה משחיטה, ואין דנין שחיטה מטביחה.\u0004","ומקשים: \u0003מה נפקא מינה\u0004 \u0005[מה יוצא מזה,\u0006 מה זה משנה\u0005]?\u0006 \u0003הא תנא\u0004 \u0005[הרי שנה\u0006 התנא\u0005]\u0006 \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו \u0005של]\u0006 \u0003ר' ישמעאל:\u0004 מה שנאמר בדיני צרעת הבתים \u0003\"ושב הכהן\"\u0004 (ויקרא יד, לט) ואחר כך נאמר \u0003\"ובא הכהן\"\u0004 (שם מד) — \u0003זו היא שיבה זו היא ביאה,\u0004 ולמדים גזירה שווה זו מזו, למרות שהמלים אינן זהות!","ודוחים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שלמדים גזירה שווה ממלה דומה, אמורים \u0003היכא דליכא דדמי ליה\u0004 \u0005[במקום שאין\u0006 כתוב אחר \u0005שדומה לו\u0006 בדיוק\u0005],\u0006 \u0003אבל איכא דדמי ליה\u0004 \u0005[כשיש\u0006 כתוב אחר \u0005שדומה לו\u0006 בדיוק\u0005]\u0006 — \u0003מדדמי ליה ילפינן\u0004 \u0005[מן הדומה לו אנו למדים],\u0006 ולכן הוא למד משחיטת חוץ ששם נאמרה לשון שחיטה, ולא מ\"וטבוח טבח\".","ושואלים: \u0003ור' שמעון נמי\u0004 \u0005[גם כן],\u0006 \u0003ליגמר\u0004 \u0005[שילמד]\u0006 \u0003משחוטי חוץ\u0004 ששחיטה שאינה ראויה לאכילה שמה שחיטה! ומשיבים: \u0003דנין\u0004 דין שחיטת \u0003חולין מ\u0004שחיטת \u0003חולין, ואין דנין\u0004 שחיטת \u0003חולין מ\u0004שחיטת \u0003קדשים,\u0004 ודין אותו ואת בנו נאמר בעיקרו בחולין (ראה לעיל עח,א).","\u0003ור' מאיר\u0004 משיב: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003אותו ואת בנו בקדשים מי לא נהיג\u0004 \u0005[האם אינו נוהג]?\u0006 ומעירים: \u0003היינו דקאמר\u0004 \u0005[זהו שאומר]\u0006 \u0003ר' חייא:\u0004 מטעם זה \u0003ראה רבי את דבריו של ר' מאיר באותו ואת בנו, ושנאו בלשון חכמים.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר\u0004 שמחייב שחיטה שאינה ראויה \u0003בכסוי הדם? אמר ר' שמעון בן לקיש: גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003שפיכה שפיכה משחוטי חוץ,\u0004 שבשחיטת חוץ נאמר: \"דם שפך\" (ויקרא יז, ד), ובכיסוי הדם נאמר \"ושפך את דמו\" (שם יג), \u0003מה להלן\u0004 — \u0003שחיטה שאינה ראויה שמה שחיטה, אף כאן\u0004 — \u0003שחיטה שאינה ראויה שמה שחיטה.\u0004","ושואלים: \u0003ור' שמעון\u0004 מה הוא משיב על כך? ומשיבים: \"חיה או עוף \u0003אשר יאכל\" כתיב\u0004 \u0005[נאמר]\u0006 בכיסוי הדם (שם), הרי הכתוב מדגיש שמדובר בשחיטה ראויה לאכילה. ושואלים: \u0003ור' מאיר,\u0004 מה הוא למד מביטוי זה? ומשיבים: לשיטתו, הכתוב \u0003ההוא\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003עוף טמא,\u0004 שאינו עומד לאכילה, \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 לומר שאין צורך לכסות את דמו. \u0003ור' שמעון\u0004 משיב: \u0003עוף טמא מאי טעמא\u0004 \u0005[מה טעם]\u0006 אינו חייב בכיסוי — מפני \u0003דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003אכילה הוא,\u0004 שאינו עומד לאכילה, \u0003טרפה נמי\u0004 \u0005[גם כן]\u0006 \u0003לאו בר\u0004 \u0005[לא בן]\u0006 \u0003אכילה הוא,\u0004 ולכן פטורה שחיטתה מכיסוי הדם.","ומעירים, \u0003והיינו דאמר\u0004 \u0005[וזהו שאמר]\u0006 \u0003ר' חייא:\u0004 מטעם זה \u0003ראה רבי\u0004 את \u0003דבריו של ר' שמעון בכסוי הדם, ושנאו בלשון חכמים.\u0004","\u0003אמר ר' אבא\u0004 :"],["\u0003לא לכל\u0004 ענין \u0003אמר ר' מאיר\u0004 ש\u0003שחיטה שאינה ראויה\u0004 לאכילה, כגון שוחט טריפה — \u0003שמה שחיטה,\u0004 אלא \u0003מודה ר' מאיר שאין מתירתה באכילה; ולא לכל אמר ר' שמעון\u0004 ש\u0003שחיטה שאינה ראויה לא שמה שחיטה,\u0004 אלא \u0003מודה ר' שמעון ש\u0004השחיטה \u0003מטהרתה\u0004 את הטריפה והדומות לה \u0003מידי\u0004 טומאת \u0003נבלה.\u0004 ודנים בדברים אלו.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 ר' אבא: \u0003לא לכל אמר ר' מאיר שחיטה שאינה ראויה שמה שחיטה, מודה ר' מאיר שאין מתירתה באכילה.\u0004 ותמהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]!\u0006 \u0003טרפה בשחיטה מי מישתריא\u0004 \u0005[האם\u0006 היא \u0005מותרת]?\u0006","ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו אלא \u0003לשוחט את הטרפה ומצא בה\u0004 עובר \u0003בן תשעה\u0004 חדשים \u0003חי; סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל\u0004 ש\u0003אמר ר' מאיר שחיטה שאינה ראויה שמה שחיטה\u0004 — \u0003תהני ליה\u0004 \u0005[תועיל לו]\u0006 \u0003שחיטת אמו,\u0004 כפי שמועילה שחיטת בהמה כשרה לולד שנמצא במעיה, \u0003ולא ליבעי\u0004 \u0005[ולא יצטרך]\u0006 \u0003שחיטה,\u0004 לכן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 ר' אבא, שלדעת ר' מאיר שחיטה שאינה מתירה את האם באכילה — אינה מועילה לעובר שבמעיה, והוא טעון שחיטה בעצמו.","ומקשים: \u0003ותסברא\u0004 \u0005[וכי יכול היית לסבור כן],\u0006 שלא יצטרך שחיטה לדעת ר' מאיר, עד שהוצרך ר' אבא לומר שצריך שחיטה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' מאיר: בן פקועה,\u0004 ולד שהיה במעי בהמה שנשחטה, ופקעו את רחמה והוציאוהו, אפילו היא כשרה — \u0003טעון שחיטה,\u0004 שאין שחיטת האם מתירה את ולדה!","ומתרצים: באמת \u0003לא צריכא\u0004 \u0005[לא נצרכו]\u0006 דברי ר' אבא לשיטת ר' מאיר עצמו, אלא לשיטת רבי ההולך לשיטתו, מפני ש\u0003רבי סבר לה\u0004 \u0005[סבור]\u0006 בדבר אחד \u0003כר' מאיר, וסבר לה כרבנן\u0004 \u0005[וסבור\u0006 בדבר אחר \u0005כחכמים].\u0006 ומפרטים: מצד אחד \u0003סבר לה\u0004 \u0005[סבור]\u0006 רבי בענין אותו ואת בנו \u0003כר' מאיר,\u0004 ש\u0003אמר: שחיטה שאינה ראויה שמה שחיטה, ו\u0004אולם מצד אחר \u0003סבר לה כרבנן דאמרי\u0004 \u0005[סבור\u0006 רבי \u0005כחכמים שאומרים]:\u0006 בן פקועה — \u0003שחיטת אמו\u0004 הכשרה \u0003מטהרתו\u0004 (מכשירה אותו) לאכילה.","ומעתה, \u0003כיון דאמור רבנן\u0004 \u0005[שאמרו חכמים]\u0006 בבן פקועה כשרה ש\u0003שחיטת אמו מטהרתו,\u0004 ולענין זה סבור רבי כמותם, שמא בטריפה \u0003תהני ליה\u0004 \u0005[תועיל לו]\u0006 לולד \u0003שחיטת אמו\u0004 להתירו באכילה, \u0003ולא ליבעי\u0004 \u0005[ולא יצטרך]\u0006 \u0003שחיטה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ר' אבא, שלדעת רבי, למרות שהוא סבור כר' מאיר, ששחיטת טריפה (שאינה ראויה) שמה שחיטה — לא תועיל השחיטה להתיר את הוולד שבמעיה. ודנים בהמשך דברי ר' אבא.","\u0003ולא לכל אמר ר' שמעון\u0004 ש\u0003שחיטה שאינה ראויה לא שמה שחיטה,\u0004 אלא \u0003מודה ר' שמעון שמטהרתה מידי נבלה.\u0004 ותמהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]!\u0006 שהרי \u0003אמר רב יהודה אמר רב, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים שבברייתא שנה]:\u0006 נאמר \u0003\"וכי ימות מן הבהמה...\u0004 הנוגע בנבלתה יטמא\" (ויקרא יא, לט), ומן הלשון \"מן הבהמה\" למדנו: \u0003מקצת בהמה\u0004 (חלק מן הבהמות) \u0003מטמאה\u0004 בטומאת נבילה, \u0003ומקצת בהמה אינה מטמאה, ואי זו\u0004 שאינה מטמאה — \u0003זו טרפה ששחטה!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכו]\u0006 דברי ר' אבא אלא \u0003לשוחט את הטרפה והיא חולין בעזרה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003השוחט את הטרפה, וכן השוחט\u0004 בהמה \u0003ונמצאת\u0004 לאחר שחיטתה שהיא \u0003טריפה, זה וזה\u0004 מדובר ב\u0003חולין\u0004 שנשחטו \u0003בעזרה\u0004 — \u0003ר' שמעון מתיר בהנאה,\u0004 שלא כדין חולין כשרים שנשחטו בעזרה, שהם אסורים בהנאה, \u0003וחכמים אוסרין;\u0004","\u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0005הואיל ואמר ר' שמעון: מותר בהנאה,\u0006 \u0003אלמא\u0004 \u0005[מכאן]\u0006 ששחיטת הטריפה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003שחיטה היא כלל,\u0004 וכאילו הרג אותה, ואם כן \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מידי\u0004 טומאת \u0003נבלה נמי לא מטהרה\u0004 \u0005[מטהרת\u0006 השחיטה\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ר' אבא, שלענין זה מועילה השחיטה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: וסבר\u0004 \u0005[ו\u0006כי \u0005סבור]\u0006 \u0003ר' שמעון\u0004 שאיסור הנאה ב\u0003חולין\u0004 שנשחטו \u0003בעזרה דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003והתנן\u0004 \u0005[וכן שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 בהמות \u0003חולין שנשחטו בעזרה\u0004 — \u0003ישרפו באש, וכן חיה שנשחטה בעזרה. אי אמרת בשלמא דאורייתא\u0004 \u0005[נניח אם אתה אומר ש\u0006בבהמת חולין \u0005הוא מן התורה]\u0006 — \u0003היינו דגזרינן\u0004 \u0005[זהו שאנו גוזרים]\u0006 איסור הנאה מ\u0003חיה\u0004 שנשחטה בעזרה \u0003אטו\u0004 \u0005[משום]\u0006 \u0003בהמה.\u0004","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שבבהמה עצמה הוא איסור \u0003דרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים],\u0006 הרי \u0003בהמה\u0004 של חולין שנשחטה בעזרה \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסרוה חכמים? \u0003דילמא אתי למיכל\u0004 \u0005[שמא יבואו לאכול]\u0006 \u0003קדשים בחוץ,\u0004 כשרואים ששוחטים בהמות בעזרה ואוכלים אותן בחוץ. והרי איסור הנאה בבהמה \u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003גזרה, ואנן ניקום\u0004 \u0005[ואנחנו נעמוד]\u0006 \u0003ונגזור גזירה לגזירה?\u0004","שנינו במשנה כי הנוחר והמעקר, שהורג חיה או עוף שלא בדרך שחיטה — פטור מלכסות את הדם. ובענין זה מסופר, \u0003ר' חייא נפל ליה יאניבא בכיתניה\u0004 \u0005[נפל לו עש בפשתנו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבי\u0004 לשאול מה לעשות, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שקול עופא ושחוט על בוביתא דמיא\u0004 \u0005[קח עוף ושחוט אותו על ביב המים]\u0006 ששורים שם את הפשתן, \u0003דמורח דמא ושביק ליה\u0004 \u0005[ש\u0006העש \u0005מריח את הדם ועוזב אותו,\u0006 את הפשתן\u0005].\u0006","ושואלים: \u0003היכי עביד הכי\u0004 \u0005[איך עשה כך]?\u0006 איך מותר הדבר? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003השוחט\u0004 חיה או עוף \u0003וצריך לדם\u0004 — \u0003חייב לכסות,\u0004 ואינו יכול להשתמש בדם. \u0003כיצד יעשה?\u0004 \u0003או נוחרו\u0004 (דוקר אותו) את בעל החיים, \u0003או עוקרו,\u0004 עוקר את הסימנים, וכך הורגו, כך שאינו חייב בכיסוי הדם!","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל, \u0003אמר: \"צא טרוף\" אמר ליה\u0004 \u0005[לו]\u0006 רבי לר' חייא, שיעשה את העוף טריפה ואחר כך ישחט אותו, כפי ששנינו במשנה, שהשוחט טריפה פטור מכיסוי הדם. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר: \"צא נחור\u0004 את העוף\" \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי לר' חייא.","ושואלים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003\"צא טרוף\"\u0004 אמר לו, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 לו: \u0003צא נחור?\u0004","\u0003וכי תימא\u0004 \u0005[וכי תאמר]\u0006 \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003אין שחיטה לעוף מן התורה, ו\u0004אם כן \u0003נחירתו\u0004 — \u0003זו היא שחיטתו,\u0004 וגם היא חייבת בכיסוי — דבר זה אינך יכול לומר, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 מה שנאמר \"וזבחת \u0003כאשר צויתיך\"\u0004 (דברים יב, כא) — \u0003מלמד ש\u0004כבר \u0003נצטוה משה\u0004 קודם לכן על מצות השחיטה — \u0003על הושט ועל הקנה,\u0004 שחיתוכם הוא שחיטה, \u0003ועל\u0004 הצורך בשחיטת \u0003רוב\u0004 סימן \u0003אחד בעוף, ועל רוב שנים בבהמה\u0004 והרי רבי הוא ששנה את משנתנו!"]]};
